INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SC4-2-u1-C1','sci',4,2,'u1',1,'밤하늘에서 볼 수 있는 것 — 밤하늘에는 달, 행성, 별이 있음 · 둥근 달, 반달, 반짝이는 별을 본 경험을 나눔',ARRAY['[4과13-01] 달의 모양과 표면, 달의 위상 변화를 관찰하여 밤하늘 관찰에 흥미를 가질 수 있다(지도서 교육과정 상세화 원문 · W7 확인)']::text[],1) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SC4-2-u1-C2','sci',4,2,'u1',1,'밤하늘 단어 놀이 하는 방법 — 들어 본 단어 다섯 개를 종이에 각각 적음 → 첫 친구가 들어 본 내용을 말하며 내려놓음 → 같은 단어가 있으면 함께 내려놓으며 말함 → 모두 내려놓을 때까지 되풀이 · 같은 단어라도 친구마다 들어 본 내용이 다름',ARRAY['[4과13-01] 달의 모양과 표면, 달의 위상 변화를 관찰하여 밤하늘 관찰에 흥미를 가질 수 있다(지도서 교육과정 상세화 원문 · W7 확인)']::text[],2) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SC4-2-u1-C3','sci',4,2,'u1',1,'놀이 태도와 더 알고 싶은 것 — 경쟁하지 않고 소통에 집중함 · 친구 말을 비난하지 않고 존중함 · 낱말의 자세한 뜻보다 들어 본 내용·경험한 내용을 간단히 말함 · 놀이 뒤 달·태양계·행성에 대해 더 알고 싶은 것이 생김',ARRAY['[4과13-01] 달의 모양과 표면, 달의 위상 변화를 관찰하여 밤하늘 관찰에 흥미를 가질 수 있다(지도서 교육과정 상세화 원문 · W7 확인)']::text[],3) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SC4-2-u1-C4','sci',4,2,'u1',2,'달의 모양 — 달은 전체적으로 둥근 공 모양 · 사진처럼 앞에서만 보면 납작한 원과 둥근 공이 똑같이 보이므로 모형을 옆에서도 보아야 알 수 있음',ARRAY['[4과13-01] 달의 모양과 표면, 달의 위상 변화를 관찰하여 밤하늘 관찰에 흥미를 가질 수 있다(지도서 교육과정 상세화 원문 · W7 확인)']::text[],4) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SC4-2-u1-C5','sci',4,2,'u1',2,'달 표면의 특징 — 달 표면은 단단한 땅으로 되어 있고 울퉁불퉁함 · 움푹 파인 크고 작은 충돌 구덩이가 많음 · 전체적으로 회색을 띠고 밝은 곳과 어두운 곳이 있음',ARRAY['[4과13-01] 달의 모양과 표면, 달의 위상 변화를 관찰하여 밤하늘 관찰에 흥미를 가질 수 있다(지도서 교육과정 상세화 원문 · W7 확인)']::text[],5) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SC4-2-u1-C6','sci',4,2,'u1',2,'달의 바다 — 달 표면의 어두운 곳을 달의 바다라고 함 · 실제로 물은 없음 · 주변보다 어둡고 매끈매끈하게 보여 바다처럼 보여서 붙은 이름',ARRAY['[4과13-01] 달의 모양과 표면, 달의 위상 변화를 관찰하여 밤하늘 관찰에 흥미를 가질 수 있다(지도서 교육과정 상세화 원문 · W7 확인)']::text[],6) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SC4-2-u1-C7','sci',4,2,'u1',2,'달을 조사하는 방법 — 달 사진을 관찰하고 스마트 기기로 조사함 · 밝고 어두운 차이, 움푹 파인 곳을 주의 깊게 살핌 · 조사한 정보의 출처를 확인하고 옳은 정보와 거짓 정보를 구분함',ARRAY['[4과13-01] 달의 모양과 표면, 달의 위상 변화를 관찰하여 밤하늘 관찰에 흥미를 가질 수 있다(지도서 교육과정 상세화 원문 · W7 확인)']::text[],7) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SC4-2-u1-C8','sci',4,2,'u1',3,'여러 날 동안 달 관찰하기 — 관찰 기간과 장소를 먼저 정함 · 주변이 어둡고 탁 트인 넓은 곳에서 2일~3일 간격으로 관찰함 · 관찰한 날짜를 쓰고 같은(가장 비슷한) 모양의 붙임딱지를 붙임 · 달이 보이지 않는 날도 있어 스마트 기기를 활용할 수 있음',ARRAY['[4과13-01] 달의 모양과 표면, 달의 위상 변화를 관찰하여 밤하늘 관찰에 흥미를 가질 수 있다(지도서 교육과정 상세화 원문 · W7 확인)']::text[],8) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SC4-2-u1-C9','sci',4,2,'u1',3,'달을 관찰할 때의 안전 — 어른과 함께 외출하여 관찰함 · 너무 늦은 밤이나 새벽 시간에는 관찰하지 않음',ARRAY['[4과13-01] 달의 모양과 표면, 달의 위상 변화를 관찰하여 밤하늘 관찰에 흥미를 가질 수 있다(지도서 교육과정 상세화 원문 · W7 확인)']::text[],9) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SC4-2-u1-C10','sci',4,2,'u1',3,'달의 모양이 달라지는 차례 — 초승달(눈썹 모양) → 상현달(반달) → 보름달(둥근 모양) → 하현달(반달) → 그믐달(눈썹 모양) 차례로 조금씩 달라짐',ARRAY['[4과13-01] 달의 모양과 표면, 달의 위상 변화를 관찰하여 밤하늘 관찰에 흥미를 가질 수 있다(지도서 교육과정 상세화 원문 · W7 확인)']::text[],10) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SC4-2-u1-C11','sci',4,2,'u1',3,'되풀이되는 달의 모양 — 그믐달을 본 뒤 며칠이 지나면 다시 초승달을 볼 수 있음 · 같은 모양의 달을 다시 보려면 약 30일이 걸림 · 보이는 달의 모양이 달라질 뿐 실제 달의 모양은 변하지 않음(까닭은 다루지 않음)',ARRAY['[4과13-01] 달의 모양과 표면, 달의 위상 변화를 관찰하여 밤하늘 관찰에 흥미를 가질 수 있다(지도서 교육과정 상세화 원문 · W7 확인)']::text[],11) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SC4-2-u1-C12','sci',4,2,'u1',4,'태양계의 뜻 — 태양을 비롯하여 태양의 영향을 받는 천체들과 그 공간 · 천체는 우주에 있는 별, 행성 등을 모두 가리킴 · 태양은 태양계 중심에 있고 행성은 태양 주위를 돎 · 여덟 행성 말고도 여러 가지 천체가 있음',ARRAY['[4과13-02] 태양계 구성원을 알고, 태양과 행성을 조사할 수 있다(지도서 교육과정 상세화 원문 · W7 확인)']::text[],12) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SC4-2-u1-C13','sci',4,2,'u1',4,'태양계의 여덟 행성 — 태양에서 가까운 차례로 수성, 금성, 지구, 화성, 목성, 토성, 천왕성, 해왕성 · 달과 태양은 행성이 아님',ARRAY['[4과13-02] 태양계 구성원을 알고, 태양과 행성을 조사할 수 있다(지도서 교육과정 상세화 원문 · W7 확인)']::text[],13) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SC4-2-u1-C14','sci',4,2,'u1',4,'태양계 행성의 특징 — 행성마다 색깔이 다양하고 고리를 가진 행성도 있음 · 수성·금성·지구·화성은 표면에 단단한 땅이 있고 고리가 없음 · 목성·토성·천왕성·해왕성은 표면이 기체로 이루어져 있고 고리가 있음(토성은 크고 뚜렷, 나머지는 희미함) · 수성 회색, 금성 노란색, 지구 다양한 색, 화성 붉은색, 목성 줄무늬와 붉은 점, 토성 연한 노란색, 천왕성 청록색, 해왕성 파란색과 검은 점',ARRAY['[4과13-02] 태양계 구성원을 알고, 태양과 행성을 조사할 수 있다(지도서 교육과정 상세화 원문 · W7 확인)']::text[],14) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SC4-2-u1-C15','sci',4,2,'u1',4,'태양계 행성 모형 만들기 — 모둠에서 만들 행성을 나누고 빠뜨린 행성이 없는지 확인함 · 행성 표면의 특징이 잘 드러나게 만듦 · 그림 도구의 뾰족한 곳에 찔리지 않게 조심하고 장난치지 않음 · 친구 모형의 잘한 점을 이야기하고 비난하지 않음',ARRAY['[4과13-02] 태양계 구성원을 알고, 태양과 행성을 조사할 수 있다(지도서 교육과정 상세화 원문 · W7 확인)']::text[],15) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SC4-2-u1-C16','sci',4,2,'u1',5,'별의 뜻 — 스스로 빛을 내는 천체를 별이라고 함 · 행성은 별과 달리 스스로 빛을 내지 않음 · 태양은 태양계의 유일한 별 · 북극성은 별, 목성은 행성',ARRAY['[4과13-03] 별의 정의를 알고, 북극성 주변의 별자리를 관찰할 수 있다(지도서 교육과정 상세화 원문 · W7 확인)']::text[],16) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SC4-2-u1-C17','sci',4,2,'u1',5,'별자리 — 별자리는 별들을 연결해 이름을 붙인 것 · 옛날에는 별자리의 모습이나 이름이 지역에 따라 달랐고 시간이 지나며 바뀌기도 함 · 천문학자들이 공통으로 쓸 이름과 모양을 정함',ARRAY['[4과13-03] 별의 정의를 알고, 북극성 주변의 별자리를 관찰할 수 있다(지도서 교육과정 상세화 원문 · W7 확인)']::text[],17) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SC4-2-u1-C18','sci',4,2,'u1',5,'북극성과 북극성 주변의 별자리 — 큰곰자리·작은곰자리·카시오페이아자리는 북쪽 밤하늘의 대표적인 별자리 · 북극성은 작은곰자리의 꼬리 부분에 있고 정확한 북쪽 부근에서 위치가 거의 변하지 않아 방향을 찾는 데 이용함 · 북두칠성은 큰곰자리의 꼬리 부분에 있는 일곱 개의 별 · 북극성 주변에는 이 밖에도 여러 별자리가 있음',ARRAY['[4과13-03] 별의 정의를 알고, 북극성 주변의 별자리를 관찰할 수 있다(지도서 교육과정 상세화 원문 · W7 확인)']::text[],18) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SC4-2-u1-C19','sci',4,2,'u1',5,'별과 별자리를 조사·관찰하는 방법 — 행성과 견주어 별의 다른 점을 스마트 기기로 조사하고 출처를 확인함 · 밤하늘 그림에 별자리 투명 필름을 대어 일치하는 별자리를 찾음 · 천체 관측 프로그램은 사용 방법을 미리 확인하고 먼저 북극성을 찾은 뒤 주변 별자리를 확인함',ARRAY['[4과13-03] 별의 정의를 알고, 북극성 주변의 별자리를 관찰할 수 있다(지도서 교육과정 상세화 원문 · W7 확인)']::text[],19) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SC4-2-u1-C20','sci',4,2,'u1',6,'우주여행 — 예전에는 우주 비행사만 우주에 갈 수 있었음 · 일반인이 우주선을 타고 우주에 갔다가 돌아오는 것도 우주여행 · 다른 천체로 가는 것만 우주여행인 것은 아님',ARRAY['[4과13-02] 태양계 구성원을 알고, 태양과 행성을 조사할 수 있다(지도서 교육과정 상세화 원문 · W7 확인)']::text[],20) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SC4-2-u1-C21','sci',4,2,'u1',6,'태양계 여행 홍보 자료 만들기 — 홍보할 천체와 그 특징을 정하고 홍보 내용과 역할을 계획함 → 도화지를 접음 → 역할을 나누어 꾸밈 → 꾸민 내용을 도화지에 붙여 완성 · 천체의 특징이 잘 드러나게 만듦 · 칼이나 가위를 쓸 때 다치지 않게 조심함',ARRAY['[4과13-02] 태양계 구성원을 알고, 태양과 행성을 조사할 수 있다(지도서 교육과정 상세화 원문 · W7 확인)']::text[],21) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SC4-2-u1-C22','sci',4,2,'u1',6,'홍보 자료 공유와 평가 — 평가 기준 = 천체의 특징을 잘 나타냈는가, 홍보 내용을 잘 표현했는가, 창의적으로 만들었는가 · 다른 모둠 발표를 경청하고 비난하지 않으며 잘한 점 위주로 찾음 · 우리 모둠의 보완할 점을 생각함',ARRAY['[4과13-02] 태양계 구성원을 알고, 태양과 행성을 조사할 수 있다(지도서 교육과정 상세화 원문 · W7 확인)']::text[],22) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SC4-2-u1-C23','sci',4,2,'u1',6,'배운 내용으로 옳은 것 가려내기 — 풍선 놀이에서 달·태양계·별에 대해 배운 내용으로 옳은 문장과 옳지 않은 문장을 가려냄 · 옳지 않은 문장은 어디가 잘못되었는지 바로잡음',ARRAY['[4과13-03] 별의 정의를 알고, 북극성 주변의 별자리를 관찰할 수 있다(지도서 교육과정 상세화 원문 · W7 확인)']::text[],23) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SC4-2-u1-C24','sci',4,2,'u1',7,'망원경이 바꾼 밤하늘 관찰 — 망원경이 없던 때에는 맨눈으로 관찰해 행성의 모습을 자세히 알기 어려웠음 · 망원경이 발명되면서 달의 표면이 울퉁불퉁하다는 것을 알아내고 맨눈으로 보기 어려운 천왕성과 해왕성을 발견함',ARRAY['[4과13-03] 별의 정의를 알고, 북극성 주변의 별자리를 관찰할 수 있다(지도서 교육과정 상세화 원문 · W7 확인)']::text[],24) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SC4-2-u1-C25','sci',4,2,'u1',7,'오늘날 망원경이 주는 도움 — 태양계 천체의 모습이나 표면 상태를 연구하고 태양계 밖 천체를 자세히 관찰함 · 지구 밖으로 보낸 망원경은 날씨에 상관없이 우주를 관찰함 · 지상 망원경과 제임스 웹 우주 망원경이 지금도 우주를 살펴봄',ARRAY['[4과13-03] 별의 정의를 알고, 북극성 주변의 별자리를 관찰할 수 있다(지도서 교육과정 상세화 원문 · W7 확인)']::text[],25) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SC4-2-u1-C26','sci',4,2,'u1',7,'직접 천체에 가서 관찰하기 — 달 탐사선 다누리호는 우리나라 최초의 달 탐사선으로 달 주위를 돌며 달 표면을 탐사하고 달 기지를 만들기 적당한 곳을 찾음 · 망원경으로 관찰하기도 하고 직접 천체에 가서 관찰하기도 함',ARRAY['[4과13-03] 별의 정의를 알고, 북극성 주변의 별자리를 관찰할 수 있다(지도서 교육과정 상세화 원문 · W7 확인)']::text[],26) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC4-2-u1-X01','sci',4,'u1',ARRAY['SC4-2-u1-C1']::text[],'밤하늘에는 달만 있다고 여기거나 달·행성·별 가운데 일부를 빠뜨린다','달, 행성, 별') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC4-2-u1-X02','sci',4,'u1',ARRAY['SC4-2-u1-C2']::text[],'단어 놀이 순서를 잘못 안다(주사위 굴리기·뜻 외우기부터 하기, 같은 단어가 없는데 내려놓기 등)','다섯 단어를 적고 시작') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC4-2-u1-X03','sci',4,'u1',ARRAY['SC4-2-u1-C2']::text[],'같은 단어라면 친구들이 들어 본 내용도 모두 같다고 여긴다','친구마다 달라요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC4-2-u1-X04','sci',4,'u1',ARRAY['SC4-2-u1-C3']::text[],'단어 놀이를 단어를 많이 아는 사람이 앞서는 겨루기로 여기고 서두른다','나누는 놀이') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC4-2-u1-X05','sci',4,'u1',ARRAY['SC4-2-u1-C3']::text[],'단어의 정확한 뜻을 설명해야 하거나 잘 모르는 단어는 말하면 안 된다고 여긴다','들어 본 내용 · 경험') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC4-2-u1-X06','sci',4,'u1',ARRAY['SC4-2-u1-C3']::text[],'친구가 말한 내용을 비난하거나 무시한다','존중해요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC4-2-u1-X07','sci',4,'u1',ARRAY['SC4-2-u1-C4']::text[],'달을 납작한 원 모양이라고 여긴다','둥근 공 모양') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC4-2-u1-X08','sci',4,'u1',ARRAY['SC4-2-u1-C4']::text[],'사진처럼 앞에서 본 모습만으로 공인지 원인지 알 수 있다고 여긴다','옆에서도 보아요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC4-2-u1-X09','sci',4,'u1',ARRAY['SC4-2-u1-C5']::text[],'달 표면이 매끈매끈하거나 어디나 평평하다고 여긴다','울퉁불퉁해요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC4-2-u1-X10','sci',4,'u1',ARRAY['SC4-2-u1-C5']::text[],'충돌 구덩이를 달의 바다·밝은 곳 등 다른 것과 헷갈린다','움푹 파인 곳') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC4-2-u1-X11','sci',4,'u1',ARRAY['SC4-2-u1-C6']::text[],'달의 바다에 실제로 물이 있다고 여긴다','물이 없어요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC4-2-u1-X12','sci',4,'u1',ARRAY['SC4-2-u1-C6']::text[],'달의 바다를 달 표면의 밝은 곳이라고 여긴다','어두운 곳') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC4-2-u1-X13','sci',4,'u1',ARRAY['SC4-2-u1-C7','SC4-2-u1-C19']::text[],'조사할 때 출처를 확인하지 않거나 옳은 정보와 거짓 정보를 구분하지 않는다','출처 확인') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC4-2-u1-X14','sci',4,'u1',ARRAY['SC4-2-u1-C8']::text[],'달 관찰 계획·방법을 잘못 안다(밝고 좁은 곳, 하루만 관찰, 붙임딱지 한꺼번에 붙이기, 날짜 안 쓰기)','어둡고 탁 트인 곳 · 여러 날') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC4-2-u1-X15','sci',4,'u1',ARRAY['SC4-2-u1-C8']::text[],'달이 보이지 않는 날에는 달이 없어졌다고 여기거나 관찰을 그만둔다','스마트 기기로도') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC4-2-u1-X16','sci',4,'u1',ARRAY['SC4-2-u1-C9']::text[],'어른 없이 혼자 나가거나 너무 늦은 밤·새벽에 달을 관찰한다','어른과 함께') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC4-2-u1-X17','sci',4,'u1',ARRAY['SC4-2-u1-C10']::text[],'달의 모양이 달라지는 차례를 잘못 안다(상현달과 하현달 뒤바꾸기 등)','초승 · 상현 · 보름 · 하현 · 그믐') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC4-2-u1-X18','sci',4,'u1',ARRAY['SC4-2-u1-C10']::text[],'달의 이름과 모양을 잘못 잇는다(초승달 — 둥근 모양 등)','눈썹 · 반달 · 둥근') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC4-2-u1-X19','sci',4,'u1',ARRAY['SC4-2-u1-C10','SC4-2-u1-C11']::text[],'달의 모양이 하루 만에 바뀌거나 아무 차례 없이 달라진다고 여긴다','조금씩 차례로') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC4-2-u1-X20','sci',4,'u1',ARRAY['SC4-2-u1-C11']::text[],'같은 모양의 달을 다시 보는 데 걸리는 날을 잘못 안다(약 15일, 약 7일 등)','약 30일') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC4-2-u1-X21','sci',4,'u1',ARRAY['SC4-2-u1-C11']::text[],'달의 모양이 실제로 변해서 다르게 보인다고 여긴다','실제 모양은 그대로') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC4-2-u1-X22','sci',4,'u1',ARRAY['SC4-2-u1-C11']::text[],'그믐달 뒤에는 달을 다시 볼 수 없다고 여긴다','다시 초승달') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC4-2-u1-X23','sci',4,'u1',ARRAY['SC4-2-u1-C12']::text[],'태양계에는 태양과 행성만 있다고 여긴다','여러 가지 천체') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC4-2-u1-X24','sci',4,'u1',ARRAY['SC4-2-u1-C12']::text[],'태양계는 천체만 가리키고 공간은 들어가지 않는다고 여긴다','천체와 공간') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC4-2-u1-X25','sci',4,'u1',ARRAY['SC4-2-u1-C12']::text[],'태양을 행성으로 여기거나 태양계의 중심에 지구나 다른 행성이 있다고 여긴다','태양이 중심') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC4-2-u1-X26','sci',4,'u1',ARRAY['SC4-2-u1-C13']::text[],'여덟 행성의 이름이나 태양에서 가까운 차례를 잘못 안다(달을 행성에 넣기 등)','수 · 금 · 지 · 화 · 목 · 토 · 천 · 해') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC4-2-u1-X27','sci',4,'u1',ARRAY['SC4-2-u1-C14']::text[],'모든 행성에 단단한 땅이 있다고 여기거나 땅이 있는 행성과 기체로 된 행성을 뒤바꾼다','수금지화는 땅') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC4-2-u1-X28','sci',4,'u1',ARRAY['SC4-2-u1-C14']::text[],'고리가 있는 행성은 토성뿐이라고 여긴다','희미한 고리도 고리') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC4-2-u1-X29','sci',4,'u1',ARRAY['SC4-2-u1-C14']::text[],'행성과 색깔·특징을 잘못 잇는다(화성 — 고리, 금성 — 붉은색 등)','색깔 · 표면 · 고리') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC4-2-u1-X30','sci',4,'u1',ARRAY['SC4-2-u1-C15']::text[],'모형을 만들 때 그림 도구를 위험하게 다룬다(뾰족한 곳을 친구 쪽으로 향하기, 던지기)','뾰족한 곳 조심') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC4-2-u1-X31','sci',4,'u1',ARRAY['SC4-2-u1-C15']::text[],'행성 모형은 특징보다 예쁘게 꾸미는 것이 중요하다고 여기거나 친구 모형을 비난한다','특징이 드러나게') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC4-2-u1-X32','sci',4,'u1',ARRAY['SC4-2-u1-C16']::text[],'행성도 별처럼 스스로 빛을 낸다고 여기거나 별과 행성을 뒤바꾼다','스스로 빛을 내면 별') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC4-2-u1-X33','sci',4,'u1',ARRAY['SC4-2-u1-C16']::text[],'태양은 별이 아니라고 여기거나 태양계에 별이 여러 개 있다고 여긴다','태양계의 유일한 별') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC4-2-u1-X34','sci',4,'u1',ARRAY['SC4-2-u1-C17']::text[],'별자리를 별들이 스스로 그린 그림, 행성을 이은 것, 옛날부터 한 번도 바뀌지 않은 것으로 여긴다','사람이 별을 이어 이름 붙임') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC4-2-u1-X35','sci',4,'u1',ARRAY['SC4-2-u1-C18']::text[],'북극성이 들어 있는 별자리를 큰곰자리나 북두칠성으로 여긴다','작은곰자리 꼬리') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC4-2-u1-X36','sci',4,'u1',ARRAY['SC4-2-u1-C18']::text[],'북두칠성이 작은곰자리에 있다고 여기거나 북두칠성과 북극성을 헷갈린다','큰곰자리 꼬리의 일곱 별') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC4-2-u1-X37','sci',4,'u1',ARRAY['SC4-2-u1-C18']::text[],'북쪽 하늘의 별자리는 큰곰자리·작은곰자리·카시오페이아자리 세 개뿐이라고 여긴다','더 있어요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC4-2-u1-X38','sci',4,'u1',ARRAY['SC4-2-u1-C18']::text[],'북극성의 위치가 크게 달라진다거나 남쪽 하늘에 있다고 여겨 방향을 찾는 데 쓰지 못한다','북쪽 부근 · 거의 그대로') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC4-2-u1-X39','sci',4,'u1',ARRAY['SC4-2-u1-C19']::text[],'필름이나 천체 관측 프로그램으로 별자리를 찾는 방법을 잘못 안다(북극성을 먼저 찾지 않기, 사용 방법 확인하지 않기)','먼저 북극성') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC4-2-u1-X40','sci',4,'u1',ARRAY['SC4-2-u1-C20']::text[],'지구 밖의 다른 천체로 가는 것만 우주여행이라고 여긴다','갔다가 돌아오는 것도') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC4-2-u1-X41','sci',4,'u1',ARRAY['SC4-2-u1-C21']::text[],'홍보 자료 만드는 차례나 안전을 잘못 안다(계획 없이 꾸미기, 칼·가위를 아무 데나 두기)','계획부터 · 조심') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC4-2-u1-X42','sci',4,'u1',ARRAY['SC4-2-u1-C21','SC4-2-u1-C22']::text[],'예쁘게 꾸미거나 글자를 꽉 채우는 것이 좋은 홍보 자료라고 여긴다','천체의 특징이 드러나게') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC4-2-u1-X43','sci',4,'u1',ARRAY['SC4-2-u1-C22']::text[],'다른 모둠 발표를 비난하거나 경청하지 않고, 자료를 그대로 따라 하거나 혼자 다 만든다','경청 · 잘한 점 · 협력') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC4-2-u1-X44','sci',4,'u1',ARRAY['SC4-2-u1-C23']::text[],'풍선 놀이에서 옳지 않은 문장을 옳다고 판단하거나 어디가 잘못되었는지 찾지 못한다','배운 내용으로 확인') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC4-2-u1-X45','sci',4,'u1',ARRAY['SC4-2-u1-C24']::text[],'망원경이 없던 때에도 행성을 자세히 알았다거나 천왕성·해왕성이 그때는 없었다고 여긴다','맨눈으로는 보기 어려워요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC4-2-u1-X46','sci',4,'u1',ARRAY['SC4-2-u1-C25']::text[],'망원경이 있으면 밤하늘을 관찰할 필요가 없다거나 지구 밖 망원경도 날씨가 좋을 때만 관찰한다고 여긴다','날씨에 상관없이') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC4-2-u1-X47','sci',4,'u1',ARRAY['SC4-2-u1-C26']::text[],'망원경으로 관찰하는 것과 직접 천체에 가서 관찰하는 것을 헷갈린다(다누리호를 망원경으로 여기기 등)','다누리호는 직접 가서') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_sci_u1_L01_basic#1','sci',4,2,'u1','L01','g4_2_sci_u1_L01_basic','lesson_basic','SC4-2-u1-C1',1,'mc','auto','밤하늘에서 볼 수 있는 것을 바르게 묶은 것은 무엇인가요?',ARRAY['SC4-2-u1-X01']::text[],false,'{"seq":1,"concept":"SC4-2-u1-C1","difficulty":1,"kind":"mc","stem":"밤하늘에서 볼 수 있는 것을 바르게 묶은 것은 무엇인가요?","options":[{"t":"달, 행성, 별","correct":true},{"t":"달 하나뿐","mis":"SC4-2-u1-X01"},{"t":"구름, 무지개, 해돋이","mis":"SC4-2-u1-X01"},{"t":"별, 무지개, 소나기","mis":"SC4-2-u1-X01"}],"explanation":["밤하늘을 떠올려요.","세 가지가 있어요.","달, 행성, 별이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_sci_u1_L01_basic#2','sci',4,2,'u1','L01','g4_2_sci_u1_L01_basic','lesson_basic','SC4-2-u1-C2',1,'sa','auto','밤하늘 단어 놀이 하는 방법에서 단어를 하나씩 적는 곳을 두 글자로 쓰세요.','{}'::text[],false,'{"seq":2,"concept":"SC4-2-u1-C2","difficulty":1,"kind":"sa","stem":"밤하늘 단어 놀이 하는 방법에서 단어를 하나씩 적는 곳을 두 글자로 쓰세요.","answer":["종이"],"explanation":["①을 읽어요.","적어서 내려놓아요.","종이예요."],"asset":{"type":"passage","lines":["① 밤하늘에 대해 들어 본 단어 다섯 개를 종이에 하나씩 적어요.","② 첫 친구가 단어에 대해 들어 본 내용을 말하며 종이를 내려놓아요.","③ 같은 단어를 가진 친구도 함께 내려놓으며 들어 본 내용을 말해요.","④ 종이를 모두 내려놓을 때까지 ②와 ③을 되풀이해요."],"title":"밤하늘 단어 놀이 하는 방법"},"mis":"SC4-2-u1-X02"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_sci_u1_L01_basic#3','sci',4,2,'u1','L01','g4_2_sci_u1_L01_basic','lesson_basic','SC4-2-u1-C3',1,'ox','auto','밤하늘 단어 놀이를 할 때에는 친구가 말하는 내용을 비난하지 않아요.',ARRAY['SC4-2-u1-X06']::text[],false,'{"seq":3,"concept":"SC4-2-u1-C3","difficulty":1,"kind":"ox","stem":"밤하늘 단어 놀이를 할 때에는 친구가 말하는 내용을 비난하지 않아요.","answer":"O","reason_options":[{"t":"다른 사람의 생각이나 표현을 존중해야 하기 때문에","correct":true},{"t":"잘못 말한 친구는 바로 놀려 주어야 하기 때문에","mis":"SC4-2-u1-X06"}],"mis":"SC4-2-u1-X06","explanation":["놀이 약속을 떠올려요.","서로 존중해요.","그래서 O예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_sci_u1_L01_basic#4','sci',4,2,'u1','L01','g4_2_sci_u1_L01_basic','lesson_basic','SC4-2-u1-C1',1,'mc','auto','친구들이 밤하늘에서 본 모습으로 알맞은 것은 무엇인가요?',ARRAY['SC4-2-u1-X01']::text[],false,'{"seq":4,"concept":"SC4-2-u1-C1","difficulty":1,"kind":"mc","stem":"친구들이 밤하늘에서 본 모습으로 알맞은 것은 무엇인가요?","options":[{"t":"별들이 반짝이는 것을 보았다","correct":true},{"t":"밤하늘에 무지개가 뜬 것을 보았다","mis":"SC4-2-u1-X01"},{"t":"한밤중에 해가 떠 있는 것을 보았다","mis":"SC4-2-u1-X01"},{"t":"밤하늘에는 아무것도 없었다","mis":"SC4-2-u1-X01"}],"explanation":["밤에 본 것을 떠올려요.","반짝이는 것이 있어요.","별이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_sci_u1_L01_basic#5','sci',4,2,'u1','L01','g4_2_sci_u1_L01_basic','lesson_basic','SC4-2-u1-C2',2,'mc','auto','친구가 낸 단어와 같은 단어의 종이를 가진 친구는 어떻게 하나요?',ARRAY['SC4-2-u1-X02','SC4-2-u1-X04']::text[],false,'{"seq":5,"concept":"SC4-2-u1-C2","difficulty":2,"kind":"mc","stem":"친구가 낸 단어와 같은 단어의 종이를 가진 친구는 어떻게 하나요?","options":[{"t":"같이 내려놓으면서 들어 본 내용을 말한다","correct":true},{"t":"아무 말 없이 그냥 들고 있는다","mis":"SC4-2-u1-X02"},{"t":"다른 단어로 바꾸어 적는다","mis":"SC4-2-u1-X02"},{"t":"먼저 내려놓은 친구의 종이를 가져온다","mis":"SC4-2-u1-X04"}],"explanation":["③을 읽어요.","함께 내려놓아요.","들어 본 내용도 말해요."],"asset":{"type":"passage","lines":["① 밤하늘에 대해 들어 본 단어 다섯 개를 종이에 하나씩 적어요.","② 첫 친구가 단어에 대해 들어 본 내용을 말하며 종이를 내려놓아요.","③ 같은 단어를 가진 친구도 함께 내려놓으며 들어 본 내용을 말해요.","④ 종이를 모두 내려놓을 때까지 ②와 ③을 되풀이해요."],"title":"밤하늘 단어 놀이 하는 방법"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_sci_u1_L01_basic#6','sci',4,2,'u1','L01','g4_2_sci_u1_L01_basic','lesson_basic','SC4-2-u1-C3',2,'mc','auto','단어에 대해 말할 때 알맞은 방법은 무엇인가요?',ARRAY['SC4-2-u1-X05','SC4-2-u1-X04']::text[],false,'{"seq":6,"concept":"SC4-2-u1-C3","difficulty":2,"kind":"mc","stem":"단어에 대해 말할 때 알맞은 방법은 무엇인가요?","options":[{"t":"들어 본 내용이나 경험한 내용을 간단하게 말한다","correct":true},{"t":"책에 나온 뜻을 그대로 외워 말한다","mis":"SC4-2-u1-X05"},{"t":"뜻을 모르면 아무 말도 하지 않는다","mis":"SC4-2-u1-X05"},{"t":"친구보다 빨리 말하려고 서두른다","mis":"SC4-2-u1-X04"}],"explanation":["뜻을 외우는 시간이 아니에요.","내가 들어 본 것을 말해요.","간단하게 말해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_sci_u1_L01_basic#7','sci',4,2,'u1','L01','g4_2_sci_u1_L01_basic','lesson_basic','SC4-2-u1-C1',2,'match','auto','친구가 들어 본 내용과 단어를 알맞게 이으세요.','{}'::text[],false,'{"seq":7,"concept":"SC4-2-u1-C1","difficulty":2,"kind":"match","stem":"친구가 들어 본 내용과 단어를 알맞게 이으세요.","pairs":[{"l":"「나는 어제 둥글게 꽉 찬 달을 보았어.」","r":"보름달"},{"l":"「국자 모양의 별들을 본 적이 있어.」","r":"북두칠성"},{"l":"「북쪽 하늘에 있는 별이래.」","r":"북극성"}],"mis":"SC4-2-u1-X01","explanation":["친구 말을 하나씩 읽어요.","국자 모양을 떠올려요.","꽉 찬 달-보름달, 국자-북두칠성, 북쪽-북극성이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_sci_u1_L01_basic#8','sci',4,2,'u1','L01','g4_2_sci_u1_L01_basic','lesson_basic','SC4-2-u1-C2',2,'ox','auto','같은 단어를 적었다면 친구들이 들어 본 내용도 모두 똑같아요.',ARRAY['SC4-2-u1-X03']::text[],false,'{"seq":8,"concept":"SC4-2-u1-C2","difficulty":2,"kind":"ox","stem":"같은 단어를 적었다면 친구들이 들어 본 내용도 모두 똑같아요.","answer":"X","reason_options":[{"t":"같은 단어라도 친구마다 들어 본 내용이나 경험한 내용이 다르기 때문에","correct":true},{"t":"한 단어에는 들어 본 내용이 하나뿐이기 때문에","mis":"SC4-2-u1-X03"}],"mis":"SC4-2-u1-X03","explanation":["친구들 이야기를 떠올려요.","저마다 달랐어요.","그래서 X예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_sci_u1_L01_basic#9','sci',4,2,'u1','L01','g4_2_sci_u1_L01_basic','lesson_basic','SC4-2-u1-C3',2,'mc','auto','놀이할 때 하지 않아야 할 행동은 무엇인가요?',ARRAY['SC4-2-u1-X06','SC4-2-u1-X05','SC4-2-u1-X04']::text[],false,'{"seq":9,"concept":"SC4-2-u1-C3","difficulty":2,"kind":"mc","stem":"놀이할 때 하지 않아야 할 행동은 무엇인가요?","options":[{"t":"앞서려고 서둘러 종이를 내려놓는다","correct":true},{"t":"친구의 생각이나 표현을 존중한다","mis":"SC4-2-u1-X06"},{"t":"들어 본 내용을 친구에게 말한다","mis":"SC4-2-u1-X05"},{"t":"규칙을 지키며 놀이한다","mis":"SC4-2-u1-X04"}],"explanation":["놀이 약속을 떠올려요.","겨루는 놀이가 아니에요.","서두르는 행동이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_sci_u1_L01_basic#10','sci',4,2,'u1','L01','g4_2_sci_u1_L01_basic','lesson_basic','SC4-2-u1-C2',3,'mc','auto','밤하늘 단어 놀이 하는 방법에서 ③을 마친 뒤에 할 일은 무엇인가요?',ARRAY['SC4-2-u1-X02','SC4-2-u1-X04','SC4-2-u1-X05']::text[],false,'{"seq":10,"concept":"SC4-2-u1-C2","difficulty":3,"kind":"mc","stem":"밤하늘 단어 놀이 하는 방법에서 ③을 마친 뒤에 할 일은 무엇인가요?","options":[{"t":"종이를 모두 내려놓을 때까지 ②와 ③을 되풀이한다","correct":true},{"t":"남은 종이를 모두 버린다","mis":"SC4-2-u1-X02"},{"t":"종이를 가장 많이 남긴 친구를 정한다","mis":"SC4-2-u1-X04"},{"t":"단어의 뜻을 공책에 적어 외운다","mis":"SC4-2-u1-X05"}],"explanation":["④를 읽어요.","되풀이해요.","모두 내려놓을 때까지예요."],"asset":{"type":"passage","lines":["① 밤하늘에 대해 들어 본 단어 다섯 개를 종이에 하나씩 적어요.","② 첫 친구가 단어에 대해 들어 본 내용을 말하며 종이를 내려놓아요.","③ 같은 단어를 가진 친구도 함께 내려놓으며 들어 본 내용을 말해요.","④ 종이를 모두 내려놓을 때까지 ②와 ③을 되풀이해요."],"title":"밤하늘 단어 놀이 하는 방법"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_sci_u1_L01_challenge#1','sci',4,2,'u1','L01','g4_2_sci_u1_L01_challenge','lesson_challenge','SC4-2-u1-C1',2,'mc','auto','친구들이 적은 단어를 「달, 행성, 별」로 나눌 때 별 쪽에 들어가는 것끼리 묶은 것은 무엇인가요?',ARRAY['SC4-2-u1-X01']::text[],false,'{"seq":1,"concept":"SC4-2-u1-C1","difficulty":2,"kind":"mc","stem":"친구들이 적은 단어를 「달, 행성, 별」로 나눌 때 별 쪽에 들어가는 것끼리 묶은 것은 무엇인가요?","options":[{"t":"북극성, 북두칠성","correct":true},{"t":"보름달, 반달","mis":"SC4-2-u1-X01"},{"t":"지구, 목성","mis":"SC4-2-u1-X01"},{"t":"토성, 보름달","mis":"SC4-2-u1-X01"}],"explanation":["반짝이는 것을 찾아요.","북쪽 하늘의 별이 있어요.","북극성, 북두칠성이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_sci_u1_L01_challenge#2','sci',4,2,'u1','L01','g4_2_sci_u1_L01_challenge','lesson_challenge','SC4-2-u1-C3',2,'error','auto','놀이를 마친 뒤 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SC4-2-u1-X04','SC4-2-u1-X03','SC4-2-u1-X05']::text[],false,'{"seq":2,"concept":"SC4-2-u1-C3","difficulty":2,"kind":"error","stem":"놀이를 마친 뒤 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"친구 다 — 「단어를 가장 많이 아는 내가 최고야.」","correct":true,"mis_target":"SC4-2-u1-X04"},{"t":"친구 가 — 「같은 단어라도 친구마다 아는 내용이 달랐어.」","mis":"SC4-2-u1-X03"},{"t":"친구 나 — 「달에 대해 더 알고 싶어졌어.」","mis":"SC4-2-u1-X05"}],"explanation":["놀이의 목적을 떠올려요.","겨루는 놀이일까요?","친구 다가 잘못 말했어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_sci_u1_L01_challenge#3','sci',4,2,'u1','L01','g4_2_sci_u1_L01_challenge','lesson_challenge','SC4-2-u1-C3',3,'mc','auto','이 놀이에서 이기고 지는 것을 정하지 않는 까닭은 무엇인가요?',ARRAY['SC4-2-u1-X04','SC4-2-u1-X05']::text[],false,'{"seq":3,"concept":"SC4-2-u1-C3","difficulty":3,"kind":"mc","stem":"이 놀이에서 이기고 지는 것을 정하지 않는 까닭은 무엇인가요?","options":[{"t":"밤하늘에 대해 알고 있는 내용을 서로 나누며 소통하는 놀이이기 때문에","correct":true},{"t":"종이의 수가 사람마다 다르기 때문에","mis":"SC4-2-u1-X04"},{"t":"조용히 해야 하는 놀이이기 때문에","mis":"SC4-2-u1-X05"},{"t":"단어의 뜻을 외우는 시험이기 때문에","mis":"SC4-2-u1-X05"}],"explanation":["놀이를 왜 하는지 떠올려요.","서로 나누어요.","소통하는 놀이라서예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_sci_u1_L01_challenge#4','sci',4,2,'u1','L01','g4_2_sci_u1_L01_challenge','lesson_challenge','SC4-2-u1-C3',3,'mc','auto','이 놀이에서 「이렇게 말해요」에 들어갈 말은 무엇인가요?',ARRAY['SC4-2-u1-X05','SC4-2-u1-X06']::text[],false,'{"seq":4,"concept":"SC4-2-u1-C3","difficulty":3,"kind":"mc","stem":"이 놀이에서 「이렇게 말해요」에 들어갈 말은 무엇인가요?","options":[{"t":"「스마트 기기에서 국자 모양의 별들을 본 적이 있어.」","correct":true},{"t":"「달이 그렇게 보이는 까닭을 자세히 설명할게.」","mis":"SC4-2-u1-X05"},{"t":"「그 단어의 정확한 뜻을 맞혀 볼게.」","mis":"SC4-2-u1-X05"},{"t":"「네가 말한 건 엉터리야.」","mis":"SC4-2-u1-X06"}],"explanation":["들어 본 내용·경험한 내용이에요.","뜻을 설명하지 않아요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_sci_u1_L01_challenge#5','sci',4,2,'u1','L01','g4_2_sci_u1_L01_challenge','lesson_challenge','SC4-2-u1-C2',3,'ox','auto','친구가 낸 단어와 같은 단어의 종이가 없으면 아무 종이나 함께 내려놓아요.',ARRAY['SC4-2-u1-X02']::text[],false,'{"seq":5,"concept":"SC4-2-u1-C2","difficulty":3,"kind":"ox","stem":"친구가 낸 단어와 같은 단어의 종이가 없으면 아무 종이나 함께 내려놓아요.","answer":"X","reason_options":[{"t":"같은 단어의 종이가 있을 때만 함께 내려놓기 때문에","correct":true},{"t":"종이를 빨리 없애야 놀이가 끝나기 때문에","mis":"SC4-2-u1-X02"}],"mis":"SC4-2-u1-X02","explanation":["③을 떠올려요.","같은 단어일 때만이에요.","그래서 X예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_sci_u1_L01_challenge#6','sci',4,2,'u1','L01','g4_2_sci_u1_L01_challenge','lesson_challenge','SC4-2-u1-C3',3,'mc','auto','놀이를 한 뒤 친구들이 「더 알고 싶은 것」을 말했어요. 이 단원에서 알아볼 것과 거리가 먼 것은 무엇인가요?',ARRAY['SC4-2-u1-X04']::text[],false,'{"seq":6,"concept":"SC4-2-u1-C3","difficulty":3,"kind":"mc","stem":"놀이를 한 뒤 친구들이 「더 알고 싶은 것」을 말했어요. 이 단원에서 알아볼 것과 거리가 먼 것은 무엇인가요?","options":[{"t":"단어를 누가 가장 많이 아는지 겨루고 싶어요","correct":true},{"t":"달의 모양이 어떻게 달라지는지 알아보고 싶어요","mis":"SC4-2-u1-X04"},{"t":"태양계 행성의 특징을 알아보고 싶어요","mis":"SC4-2-u1-X04"},{"t":"달의 모습을 더 자세히 알고 싶어요","mis":"SC4-2-u1-X04"}],"explanation":["밤하늘에 대한 궁금증을 찾아요.","겨루기는 아니에요.","첫 번째가 거리가 멀어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_sci_u1_L01_challenge#7','sci',4,2,'u1','L01','g4_2_sci_u1_L01_challenge','lesson_challenge','SC4-2-u1-C1',3,'mc','auto','밤하늘에서 둥근 달을 본 친구와 반달을 본 친구가 있어요. 두 친구의 경험을 바르게 정리한 것은 무엇인가요?',ARRAY['SC4-2-u1-X06','SC4-2-u1-X01']::text[],false,'{"seq":7,"concept":"SC4-2-u1-C1","difficulty":3,"kind":"mc","stem":"밤하늘에서 둥근 달을 본 친구와 반달을 본 친구가 있어요. 두 친구의 경험을 바르게 정리한 것은 무엇인가요?","options":[{"t":"두 친구 모두 밤하늘에서 달을 본 경험을 말했다","correct":true},{"t":"한 친구는 잘못 본 것이다","mis":"SC4-2-u1-X06"},{"t":"달은 한 가지 모습으로만 보인다","mis":"SC4-2-u1-X01"},{"t":"반달은 밤하늘에서 볼 수 없다","mis":"SC4-2-u1-X01"}],"explanation":["두 경험을 견줘요.","둘 다 달이에요.","모두 달을 본 경험이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_sci_u1_L01_challenge#8','sci',4,2,'u1','L01','g4_2_sci_u1_L01_challenge','lesson_challenge','SC4-2-u1-C3',4,'mc','auto','친구가 「나는 행성에 대해 들어 본 게 없어서 종이를 못 내려놓겠어.」라고 했어요. 가장 알맞게 도와준 말은 무엇인가요?',ARRAY['SC4-2-u1-X06','SC4-2-u1-X05','SC4-2-u1-X02']::text[],false,'{"seq":8,"concept":"SC4-2-u1-C3","difficulty":4,"kind":"mc","stem":"친구가 「나는 행성에 대해 들어 본 게 없어서 종이를 못 내려놓겠어.」라고 했어요. 가장 알맞게 도와준 말은 무엇인가요?","options":[{"t":"「들어 본 단어로 자유롭게 정하면 돼. 떠오르지 않으면 책을 살펴봐도 좋아.」","correct":true},{"t":"「모르면 놀이에서 빠져.」","mis":"SC4-2-u1-X06"},{"t":"「행성의 정확한 뜻을 외워 와야 해.」","mis":"SC4-2-u1-X05"},{"t":"「아무 단어나 빨리 내려놓으면 돼.」","mis":"SC4-2-u1-X02"}],"explanation":["단어는 자유롭게 정해요.","도움을 받을 수 있어요.","첫 번째가 알맞아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_sci_u1_L01_challenge#9','sci',4,2,'u1','L01','g4_2_sci_u1_L01_challenge','lesson_challenge','SC4-2-u1-C2',4,'mc','auto','모둠에서 「보름달」을 적은 친구가 셋이었어요. 놀이 방법에 맞게 한 것은 무엇인가요?',ARRAY['SC4-2-u1-X03','SC4-2-u1-X04']::text[],false,'{"seq":9,"concept":"SC4-2-u1-C2","difficulty":4,"kind":"mc","stem":"모둠에서 「보름달」을 적은 친구가 셋이었어요. 놀이 방법에 맞게 한 것은 무엇인가요?","options":[{"t":"첫 친구가 말하며 내려놓으면 나머지 두 친구도 함께 내려놓으며 각자 들어 본 내용을 말한다","correct":true},{"t":"첫 친구만 말하고 나머지는 말없이 내려놓는다","mis":"SC4-2-u1-X03"},{"t":"세 친구 모두 같은 내용을 똑같이 말해야 한다","mis":"SC4-2-u1-X03"},{"t":"가장 먼저 내려놓은 친구가 종이를 모두 가져간다","mis":"SC4-2-u1-X04"}],"explanation":["같은 단어를 가진 친구가 셋이에요.","함께 내려놓아요.","각자 말해요."],"asset":{"type":"passage","lines":["① 밤하늘에 대해 들어 본 단어 다섯 개를 종이에 하나씩 적어요.","② 첫 친구가 단어에 대해 들어 본 내용을 말하며 종이를 내려놓아요.","③ 같은 단어를 가진 친구도 함께 내려놓으며 들어 본 내용을 말해요.","④ 종이를 모두 내려놓을 때까지 ②와 ③을 되풀이해요."],"title":"밤하늘 단어 놀이 하는 방법"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_sci_u1_L01_challenge#10','sci',4,2,'u1','L01','g4_2_sci_u1_L01_challenge','lesson_challenge','SC4-2-u1-C3',4,'essay','teacher','밤하늘 단어 놀이에서 내가 적고 싶은 단어 한 가지와 그 단어에 대해 들어 본 내용이나 경험한 내용을 쓰고, 놀이할 때 지킬 점을 두 가지 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"SC4-2-u1-C3","difficulty":4,"kind":"essay","stem":"밤하늘 단어 놀이에서 내가 적고 싶은 단어 한 가지와 그 단어에 대해 들어 본 내용이나 경험한 내용을 쓰고, 놀이할 때 지킬 점을 두 가지 쓰세요.","answer_guide":{"answer":"예: 「반달」 — 나는 저녁에 반달을 본 적이 있다. 놀이할 때에는 이기고 지는 것을 정하지 않고 서로의 이야기를 나누며, 친구가 말하는 내용을 비난하지 않고 존중한다.","scoring_points":["밤하늘 단어와 들어 본 내용·경험을 썼는가","놀이할 때 지킬 점 하나를 썼는가","놀이할 때 지킬 점 또 하나를 썼는가"]},"explanation":["단어를 골라요.","들어 본 내용을 써요.","지킬 점을 써요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_sci_u1_L02_basic#1','sci',4,2,'u1','L02','g4_2_sci_u1_L02_basic','lesson_basic','SC4-2-u1-C4',1,'mc','auto','달은 전체적으로 어떤 모양인가요?',ARRAY['SC4-2-u1-X07']::text[],false,'{"seq":1,"concept":"SC4-2-u1-C4","difficulty":1,"kind":"mc","stem":"달은 전체적으로 어떤 모양인가요?","options":[{"t":"둥근 공 모양","correct":true},{"t":"납작한 원 모양","mis":"SC4-2-u1-X07"},{"t":"뾰족한 세모 모양","mis":"SC4-2-u1-X07"},{"t":"반듯한 네모 모양","mis":"SC4-2-u1-X07"}],"explanation":["달 모형을 떠올려요.","옆에서 보아도 둥글어요.","둥근 공 모양이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_sci_u1_L02_basic#2','sci',4,2,'u1','L02','g4_2_sci_u1_L02_basic','lesson_basic','SC4-2-u1-C5',1,'sa','auto','달 사진을 관찰하고 정리한 내용에서 ㉠에 들어갈 말을 쓰세요. (○○ 구덩이)','{}'::text[],false,'{"seq":2,"concept":"SC4-2-u1-C5","difficulty":1,"kind":"sa","stem":"달 사진을 관찰하고 정리한 내용에서 ㉠에 들어갈 말을 쓰세요. (○○ 구덩이)","answer":["충돌 구덩이","충돌구덩이","충돌"],"explanation":["셋째 줄을 읽어요.","움푹 파였어요.","충돌 구덩이예요."],"asset":{"type":"passage","lines":["전체적으로 둥근 공 모양이에요.","전체적으로 회색을 띠어요.","표면에 움푹 파인 ㉠이 많아요.","표면에는 밝은 곳과 어두운 곳이 있어요.","어두운 곳을 ㉡(이)라고 해요."],"title":"달 사진을 관찰하고 정리한 내용"},"mis":"SC4-2-u1-X10"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_sci_u1_L02_basic#3','sci',4,2,'u1','L02','g4_2_sci_u1_L02_basic','lesson_basic','SC4-2-u1-C6',1,'ox','auto','달 표면의 어두운 곳을 달의 바다라고 해요.',ARRAY['SC4-2-u1-X11']::text[],false,'{"seq":3,"concept":"SC4-2-u1-C6","difficulty":1,"kind":"ox","stem":"달 표면의 어두운 곳을 달의 바다라고 해요.","answer":"O","reason_options":[{"t":"주변보다 어둡고 매끈매끈하게 보여 바다처럼 보이기 때문에","correct":true},{"t":"달의 어두운 곳에 바닷물이 가득 차 있기 때문에","mis":"SC4-2-u1-X11"}],"mis":"SC4-2-u1-X11","explanation":["어두운 곳을 떠올려요.","바다처럼 보여요.","그래서 O예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_sci_u1_L02_basic#4','sci',4,2,'u1','L02','g4_2_sci_u1_L02_basic','lesson_basic','SC4-2-u1-C5',1,'mc','auto','달 표면은 무엇으로 되어 있나요?',ARRAY['SC4-2-u1-X11','SC4-2-u1-X09']::text[],false,'{"seq":4,"concept":"SC4-2-u1-C5","difficulty":1,"kind":"mc","stem":"달 표면은 무엇으로 되어 있나요?","options":[{"t":"단단한 땅","correct":true},{"t":"출렁이는 물","mis":"SC4-2-u1-X11"},{"t":"부드러운 솜","mis":"SC4-2-u1-X09"},{"t":"매끈한 유리","mis":"SC4-2-u1-X09"}],"explanation":["달 사진을 떠올려요.","울퉁불퉁한 땅이에요.","단단한 땅이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_sci_u1_L02_basic#5','sci',4,2,'u1','L02','g4_2_sci_u1_L02_basic','lesson_basic','SC4-2-u1-C6',2,'mc','auto','달 사진을 관찰하고 정리한 내용에서 ㉡에 들어갈 말은 무엇인가요?',ARRAY['SC4-2-u1-X10','SC4-2-u1-X12']::text[],false,'{"seq":5,"concept":"SC4-2-u1-C6","difficulty":2,"kind":"mc","stem":"달 사진을 관찰하고 정리한 내용에서 ㉡에 들어갈 말은 무엇인가요?","options":[{"t":"달의 바다","correct":true},{"t":"충돌 구덩이","mis":"SC4-2-u1-X10"},{"t":"단단한 땅","mis":"SC4-2-u1-X10"},{"t":"밝은 곳","mis":"SC4-2-u1-X12"}],"explanation":["다섯째 줄을 읽어요.","어두운 곳의 이름이에요.","달의 바다예요."],"asset":{"type":"passage","lines":["전체적으로 둥근 공 모양이에요.","전체적으로 회색을 띠어요.","표면에 움푹 파인 ㉠이 많아요.","표면에는 밝은 곳과 어두운 곳이 있어요.","어두운 곳을 ㉡(이)라고 해요."],"title":"달 사진을 관찰하고 정리한 내용"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_sci_u1_L02_basic#6','sci',4,2,'u1','L02','g4_2_sci_u1_L02_basic','lesson_basic','SC4-2-u1-C7',2,'mc','auto','스마트 기기로 달을 조사할 때 알맞은 행동은 무엇인가요?',ARRAY['SC4-2-u1-X13']::text[],false,'{"seq":6,"concept":"SC4-2-u1-C7","difficulty":2,"kind":"mc","stem":"스마트 기기로 달을 조사할 때 알맞은 행동은 무엇인가요?","options":[{"t":"조사한 정보의 출처를 확인한다","correct":true},{"t":"처음 본 글을 그대로 믿는다","mis":"SC4-2-u1-X13"},{"t":"출처를 지우고 옮겨 쓴다","mis":"SC4-2-u1-X13"},{"t":"옳은 정보와 거짓 정보를 섞어 쓴다","mis":"SC4-2-u1-X13"}],"explanation":["정보가 옳은지 살펴요.","어디서 찾았는지 봐요.","출처를 확인해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_sci_u1_L02_basic#7','sci',4,2,'u1','L02','g4_2_sci_u1_L02_basic','lesson_basic','SC4-2-u1-C5',2,'match','auto','관찰한 모습과 이름을 알맞게 이으세요.','{}'::text[],false,'{"seq":7,"concept":"SC4-2-u1-C5","difficulty":2,"kind":"match","stem":"관찰한 모습과 이름을 알맞게 이으세요.","pairs":[{"l":"표면에 움푹 파인 곳","r":"충돌 구덩이"},{"l":"표면에서 어둡게 보이는 곳","r":"달의 바다"},{"l":"달의 전체적인 모양","r":"둥근 공 모양"}],"mis":"SC4-2-u1-X10","explanation":["하나씩 떠올려요.","움푹 파인 곳은 구덩이예요.","움푹-충돌 구덩이, 어두운 곳-달의 바다, 모양-둥근 공이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_sci_u1_L02_basic#8','sci',4,2,'u1','L02','g4_2_sci_u1_L02_basic','lesson_basic','SC4-2-u1-C4',2,'ox','auto','달 사진에서 둥근 원으로 보이니 달은 납작한 원 모양이에요.',ARRAY['SC4-2-u1-X08']::text[],false,'{"seq":8,"concept":"SC4-2-u1-C4","difficulty":2,"kind":"ox","stem":"달 사진에서 둥근 원으로 보이니 달은 납작한 원 모양이에요.","answer":"X","reason_options":[{"t":"앞에서만 보면 납작한 원과 둥근 공이 똑같아 보이지만 달은 둥근 공 모양이기 때문에","correct":true},{"t":"사진에 보이는 모습이 언제나 실제 모양 그대로이기 때문에","mis":"SC4-2-u1-X08"}],"mis":"SC4-2-u1-X08","explanation":["모형 세워 보기를 떠올려요.","옆에서 보면 달라요.","그래서 X예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_sci_u1_L02_basic#9','sci',4,2,'u1','L02','g4_2_sci_u1_L02_basic','lesson_basic','SC4-2-u1-C5',2,'mc','auto','달 표면의 모습으로 알맞지 않은 것은 무엇인가요?',ARRAY['SC4-2-u1-X09','SC4-2-u1-X10','SC4-2-u1-X12']::text[],false,'{"seq":9,"concept":"SC4-2-u1-C5","difficulty":2,"kind":"mc","stem":"달 표면의 모습으로 알맞지 않은 것은 무엇인가요?","options":[{"t":"매끈매끈한 면만 있다","correct":true},{"t":"울퉁불퉁한 곳이 있다","mis":"SC4-2-u1-X09"},{"t":"크고 작은 충돌 구덩이가 많다","mis":"SC4-2-u1-X10"},{"t":"밝은 곳과 어두운 곳이 있다","mis":"SC4-2-u1-X12"}],"explanation":["달 표면을 떠올려요.","울퉁불퉁했어요.","매끈매끈한 면만 있다는 틀린 말이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_sci_u1_L02_basic#10','sci',4,2,'u1','L02','g4_2_sci_u1_L02_basic','lesson_basic','SC4-2-u1-C4',3,'mc','auto','달 모형 세워 보기에서 알 수 있는 것은 무엇인가요?',ARRAY['SC4-2-u1-X08','SC4-2-u1-X07']::text[],false,'{"seq":10,"concept":"SC4-2-u1-C4","difficulty":3,"kind":"mc","stem":"달 모형 세워 보기에서 알 수 있는 것은 무엇인가요?","options":[{"t":"앞에서 본 모습이 같아도 옆에서 보면 달라서, 사진만으로는 원인지 공인지 알기 어렵다","correct":true},{"t":"두 모형은 옆에서 보아도 똑같다","mis":"SC4-2-u1-X08"},{"t":"달은 납작한 원 모형과 같다","mis":"SC4-2-u1-X07"},{"t":"앞에서 본 모습만 보면 충분하다","mis":"SC4-2-u1-X08"}],"explanation":["두 모형을 견줘요.","옆모습이 달라요.","첫 번째예요."],"asset":{"type":"passage","lines":["🪙 납작한 원 모형 — 앞에서 보면 둥근 원, 옆에서 보면 납작한 선","⚽ 둥근 공 모형 — 앞에서 보아도 옆에서 보아도 둥근 원"],"title":"달 모형 세워 보기"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_sci_u1_L02_challenge#1','sci',4,2,'u1','L02','g4_2_sci_u1_L02_challenge','lesson_challenge','SC4-2-u1-C6',2,'mc','auto','달의 바다에 대해 바르게 말한 것은 무엇인가요?',ARRAY['SC4-2-u1-X11','SC4-2-u1-X12']::text[],false,'{"seq":1,"concept":"SC4-2-u1-C6","difficulty":2,"kind":"mc","stem":"달의 바다에 대해 바르게 말한 것은 무엇인가요?","options":[{"t":"달의 바다에는 실제로 물이 없다","correct":true},{"t":"달의 바다에는 물고기가 산다","mis":"SC4-2-u1-X11"},{"t":"달의 바다는 달 표면의 밝은 곳이다","mis":"SC4-2-u1-X12"},{"t":"달의 바다는 얼음으로 덮여 있다","mis":"SC4-2-u1-X11"}],"explanation":["이름에 속지 않아요.","물은 없어요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_sci_u1_L02_challenge#2','sci',4,2,'u1','L02','g4_2_sci_u1_L02_challenge','lesson_challenge','SC4-2-u1-C5',2,'blank','auto','「달 표면은 울퉁불퉁하고, 크고 작은 (    )을/를 많이 볼 수 있어요.」 빈칸에 알맞은 말은 무엇인가요?',ARRAY['SC4-2-u1-X10','SC4-2-u1-X09','SC4-2-u1-X11']::text[],false,'{"seq":2,"concept":"SC4-2-u1-C5","difficulty":2,"kind":"blank","stem":"「달 표면은 울퉁불퉁하고, 크고 작은 (    )을/를 많이 볼 수 있어요.」 빈칸에 알맞은 말은 무엇인가요?","options":[{"t":"충돌 구덩이","correct":true},{"t":"달의 바다","mis":"SC4-2-u1-X10"},{"t":"매끈한 면","mis":"SC4-2-u1-X09"},{"t":"출렁이는 물결","mis":"SC4-2-u1-X11"}],"explanation":["표면의 모습이에요.","움푹 파인 곳이에요.","충돌 구덩이예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_sci_u1_L02_challenge#3','sci',4,2,'u1','L02','g4_2_sci_u1_L02_challenge','lesson_challenge','SC4-2-u1-C7',3,'error','auto','달을 조사한 뒤 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SC4-2-u1-X13','SC4-2-u1-X10']::text[],false,'{"seq":3,"concept":"SC4-2-u1-C7","difficulty":3,"kind":"error","stem":"달을 조사한 뒤 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"친구 나 — 「누리망에서 본 글이니까 출처는 안 봐도 돼.」","correct":true,"mis_target":"SC4-2-u1-X13"},{"t":"친구 가 — 「밝고 어두운 차이를 주의 깊게 살폈어.」","mis":"SC4-2-u1-X10"},{"t":"친구 다 — 「거짓 정보가 섞였는지 확인했어.」","mis":"SC4-2-u1-X13"}],"explanation":["조사할 때 지킬 것을 떠올려요.","출처는 꼭 확인해요.","친구 나가 잘못 말했어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_sci_u1_L02_challenge#4','sci',4,2,'u1','L02','g4_2_sci_u1_L02_challenge','lesson_challenge','SC4-2-u1-C6',3,'mc','auto','달 표면의 어두운 곳을 「달의 바다」라고 부르는 까닭은 무엇인가요?',ARRAY['SC4-2-u1-X11','SC4-2-u1-X12']::text[],false,'{"seq":4,"concept":"SC4-2-u1-C6","difficulty":3,"kind":"mc","stem":"달 표면의 어두운 곳을 「달의 바다」라고 부르는 까닭은 무엇인가요?","options":[{"t":"주변보다 어둡고 매끈매끈하게 보여 바다처럼 보이기 때문에","correct":true},{"t":"실제로 물이 가득 차 있기 때문에","mis":"SC4-2-u1-X11"},{"t":"바닷물이 얼어 있기 때문에","mis":"SC4-2-u1-X11"},{"t":"주변보다 밝게 빛나기 때문에","mis":"SC4-2-u1-X12"}],"explanation":["지구의 바다를 떠올려요.","바다처럼 보여요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_sci_u1_L02_challenge#5','sci',4,2,'u1','L02','g4_2_sci_u1_L02_challenge','lesson_challenge','SC4-2-u1-C4',3,'mc','auto','「달 사진을 보니 둥근 원이야. 그러니까 달은 납작해.」라는 말을 바로잡은 것은 무엇인가요?',ARRAY['SC4-2-u1-X08','SC4-2-u1-X07']::text[],false,'{"seq":5,"concept":"SC4-2-u1-C4","difficulty":3,"kind":"mc","stem":"「달 사진을 보니 둥근 원이야. 그러니까 달은 납작해.」라는 말을 바로잡은 것은 무엇인가요?","options":[{"t":"「앞에서만 보면 원과 공이 똑같이 보여. 달은 둥근 공 모양이야.」","correct":true},{"t":"「맞아, 사진에 보이는 그대로 납작해.」","mis":"SC4-2-u1-X08"},{"t":"「달은 네모 모양이야.」","mis":"SC4-2-u1-X07"},{"t":"「달은 보는 사람마다 모양이 달라.」","mis":"SC4-2-u1-X07"}],"explanation":["사진은 앞모습이에요.","옆에서도 보아요.","첫 번째가 알맞아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_sci_u1_L02_challenge#6','sci',4,2,'u1','L02','g4_2_sci_u1_L02_challenge','lesson_challenge','SC4-2-u1-C5',3,'mc','auto','달 표면에서 볼 수 있는 것끼리 바르게 묶은 것은 무엇인가요?',ARRAY['SC4-2-u1-X11','SC4-2-u1-X09']::text[],false,'{"seq":6,"concept":"SC4-2-u1-C5","difficulty":3,"kind":"mc","stem":"달 표면에서 볼 수 있는 것끼리 바르게 묶은 것은 무엇인가요?","options":[{"t":"단단한 땅, 충돌 구덩이, 어두운 곳과 밝은 곳","correct":true},{"t":"바닷물, 충돌 구덩이, 밝은 곳","mis":"SC4-2-u1-X11"},{"t":"매끈한 면, 단단한 땅, 밝은 곳만","mis":"SC4-2-u1-X09"},{"t":"바닷물, 매끈한 면, 어두운 곳","mis":"SC4-2-u1-X11"}],"explanation":["물은 없어요.","울퉁불퉁해요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_sci_u1_L02_challenge#7','sci',4,2,'u1','L02','g4_2_sci_u1_L02_challenge','lesson_challenge','SC4-2-u1-C7',3,'ox','auto','달 사진을 관찰할 때에는 표면의 밝고 어두운 차이나 움푹 파인 곳을 주의 깊게 살펴요.',ARRAY['SC4-2-u1-X09']::text[],false,'{"seq":7,"concept":"SC4-2-u1-C7","difficulty":3,"kind":"ox","stem":"달 사진을 관찰할 때에는 표면의 밝고 어두운 차이나 움푹 파인 곳을 주의 깊게 살펴요.","answer":"O","reason_options":[{"t":"그래야 달 표면의 특징을 찾아 정리할 수 있기 때문에","correct":true},{"t":"전체 모양만 보면 표면은 살펴보지 않아도 되기 때문에","mis":"SC4-2-u1-X09"}],"mis":"SC4-2-u1-X09","explanation":["관찰할 때를 떠올려요.","표면을 자세히 봐요.","그래서 O예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_sci_u1_L02_challenge#8','sci',4,2,'u1','L02','g4_2_sci_u1_L02_challenge','lesson_challenge','SC4-2-u1-C4',4,'mc','auto','친구가 공과 동전을 앞에서만 보여 주며 「둘 다 둥근 원이니 같은 모양이야.」라고 했어요. 가장 알맞게 답한 것은 무엇인가요?',ARRAY['SC4-2-u1-X08','SC4-2-u1-X07']::text[],false,'{"seq":8,"concept":"SC4-2-u1-C4","difficulty":4,"kind":"mc","stem":"친구가 공과 동전을 앞에서만 보여 주며 「둘 다 둥근 원이니 같은 모양이야.」라고 했어요. 가장 알맞게 답한 것은 무엇인가요?","options":[{"t":"「옆에서도 보자. 동전은 납작한 선, 공은 둥근 원으로 보여. 달은 공처럼 둥근 공 모양이야.」","correct":true},{"t":"「맞아, 앞에서 같으면 같은 모양이야.」","mis":"SC4-2-u1-X08"},{"t":"「달은 동전처럼 납작해.」","mis":"SC4-2-u1-X07"},{"t":"「옆에서 보아도 둘 다 납작한 선이야.」","mis":"SC4-2-u1-X08"}],"explanation":["옆에서도 보아요.","동전과 공은 달라요.","첫 번째가 알맞아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_sci_u1_L02_challenge#9','sci',4,2,'u1','L02','g4_2_sci_u1_L02_challenge','lesson_challenge','SC4-2-u1-C5',4,'mc','auto','「달 표면은 매끈매끈한 물로 되어 있고, 움푹 파인 곳을 달의 바다라고 한다.」를 바르게 고친 것은 무엇인가요?',ARRAY['SC4-2-u1-X11','SC4-2-u1-X10','SC4-2-u1-X12']::text[],false,'{"seq":9,"concept":"SC4-2-u1-C5","difficulty":4,"kind":"mc","stem":"「달 표면은 매끈매끈한 물로 되어 있고, 움푹 파인 곳을 달의 바다라고 한다.」를 바르게 고친 것은 무엇인가요?","options":[{"t":"달 표면은 단단한 땅으로 되어 있고, 움푹 파인 곳은 충돌 구덩이, 어두운 곳은 달의 바다라고 한다","correct":true},{"t":"달 표면은 물로 되어 있고, 움푹 파인 곳은 충돌 구덩이라고 한다","mis":"SC4-2-u1-X11"},{"t":"달 표면은 단단한 땅이고, 움푹 파인 곳을 달의 바다라고 한다","mis":"SC4-2-u1-X10"},{"t":"달 표면은 매끈매끈하고, 밝은 곳을 달의 바다라고 한다","mis":"SC4-2-u1-X12"}],"explanation":["잘못된 곳이 두 군데예요.","물과 이름을 고쳐요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_sci_u1_L02_challenge#10','sci',4,2,'u1','L02','g4_2_sci_u1_L02_challenge','lesson_challenge','SC4-2-u1-C5',4,'essay','teacher','달의 모양과 표면의 특징을 세 가지 쓰고, 달 표면의 어두운 곳을 「달의 바다」라고 부르는 까닭을 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"SC4-2-u1-C5","difficulty":4,"kind":"essay","stem":"달의 모양과 표면의 특징을 세 가지 쓰고, 달 표면의 어두운 곳을 「달의 바다」라고 부르는 까닭을 쓰세요.","answer_guide":{"answer":"예: 달은 둥근 공 모양이다. 달 표면은 단단한 땅으로 되어 있고 울퉁불퉁하며 크고 작은 충돌 구덩이가 많다. 표면에는 어두운 곳과 밝은 곳이 있다. 어두운 곳에는 실제로 물이 없지만 주변보다 어둡고 매끈매끈하게 보여 바다처럼 보이기 때문에 달의 바다라고 부른다.","scoring_points":["달의 모양을 썼는가","표면의 특징 두 가지를 썼는가","달의 바다라고 부르는 까닭을 썼는가"]},"explanation":["모양부터 써요.","표면을 써요.","까닭을 써요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_sci_u1_L03_basic#1','sci',4,2,'u1','L03','g4_2_sci_u1_L03_basic','lesson_basic','SC4-2-u1-C10',1,'mc','auto','초승달은 어떤 모양으로 보이나요?',ARRAY['SC4-2-u1-X18']::text[],false,'{"seq":1,"concept":"SC4-2-u1-C10","difficulty":1,"kind":"mc","stem":"초승달은 어떤 모양으로 보이나요?","options":[{"t":"눈썹 모양","correct":true},{"t":"둥근 모양","mis":"SC4-2-u1-X18"},{"t":"반달 모양","mis":"SC4-2-u1-X18"},{"t":"네모 모양","mis":"SC4-2-u1-X18"}],"explanation":["가장 먼저 보이는 달이에요.","가느다래요.","눈썹 모양이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_sci_u1_L03_basic#2','sci',4,2,'u1','L03','g4_2_sci_u1_L03_basic','lesson_basic','SC4-2-u1-C11',1,'sa','auto','같은 모양의 달을 다시 보려면 약 며칠이 걸리나요? 「약 ○○일」의 ○○에 알맞은 수를 쓰세요.','{}'::text[],false,'{"seq":2,"concept":"SC4-2-u1-C11","difficulty":1,"kind":"sa","stem":"같은 모양의 달을 다시 보려면 약 며칠이 걸리나요? 「약 ○○일」의 ○○에 알맞은 수를 쓰세요.","answer":["30"],"explanation":["한 바퀴를 떠올려요.","다시 같은 모양이 와요.","약 30일이에요."],"mis":"SC4-2-u1-X20"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_sci_u1_L03_basic#3','sci',4,2,'u1','L03','g4_2_sci_u1_L03_basic','lesson_basic','SC4-2-u1-C9',1,'ox','auto','달을 관찰할 때에는 어른과 함께 외출해요.',ARRAY['SC4-2-u1-X16']::text[],false,'{"seq":3,"concept":"SC4-2-u1-C9","difficulty":1,"kind":"ox","stem":"달을 관찰할 때에는 어른과 함께 외출해요.","answer":"O","reason_options":[{"t":"밤에 혼자 나가면 위험하기 때문에","correct":true},{"t":"달은 어른만 관찰할 수 있기 때문에","mis":"SC4-2-u1-X16"}],"mis":"SC4-2-u1-X16","explanation":["안전을 떠올려요.","밤에는 위험해요.","그래서 O예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_sci_u1_L03_basic#4','sci',4,2,'u1','L03','g4_2_sci_u1_L03_basic','lesson_basic','SC4-2-u1-C8',1,'mc','auto','여러 날 동안 달을 관찰할 때 가장 먼저 할 일은 무엇인가요?',ARRAY['SC4-2-u1-X14']::text[],false,'{"seq":4,"concept":"SC4-2-u1-C8","difficulty":1,"kind":"mc","stem":"여러 날 동안 달을 관찰할 때 가장 먼저 할 일은 무엇인가요?","options":[{"t":"달을 관찰할 기간과 장소를 정한다","correct":true},{"t":"붙임딱지를 한꺼번에 다 붙인다","mis":"SC4-2-u1-X14"},{"t":"달의 모양이 어떻게 달라졌는지 이야기한다","mis":"SC4-2-u1-X14"},{"t":"관찰할 날짜를 정하지 않고 생각날 때 본다","mis":"SC4-2-u1-X14"}],"explanation":["계획부터 세워요.","언제, 어디서예요.","기간과 장소를 정해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_sci_u1_L03_basic#5','sci',4,2,'u1','L03','g4_2_sci_u1_L03_basic','lesson_basic','SC4-2-u1-C10',2,'mc','auto','여러 날 동안 관찰한 달에서 ㉠에 알맞은 달의 이름은 무엇인가요?',ARRAY['SC4-2-u1-X17','SC4-2-u1-X18']::text[],false,'{"seq":5,"concept":"SC4-2-u1-C10","difficulty":2,"kind":"mc","stem":"여러 날 동안 관찰한 달에서 ㉠에 알맞은 달의 이름은 무엇인가요?","options":[{"t":"하현달","correct":true},{"t":"상현달","mis":"SC4-2-u1-X17"},{"t":"초승달","mis":"SC4-2-u1-X17"},{"t":"보름달","mis":"SC4-2-u1-X18"}],"explanation":["보름달 다음이에요.","다시 반달이에요.","하현달이에요."],"asset":{"type":"passage","lines":["첫째 날 — 눈썹 모양의 달","며칠 뒤 — 반달","또 며칠 뒤 — 둥근 달","또 며칠 뒤 — 다시 반달 ㉠","또 며칠 뒤 — 다시 눈썹 모양의 달"],"title":"여러 날 동안 관찰한 달"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_sci_u1_L03_basic#6','sci',4,2,'u1','L03','g4_2_sci_u1_L03_basic','lesson_basic','SC4-2-u1-C8',2,'mc','auto','달을 관찰하기에 알맞은 곳은 어디인가요?',ARRAY['SC4-2-u1-X14']::text[],false,'{"seq":6,"concept":"SC4-2-u1-C8","difficulty":2,"kind":"mc","stem":"달을 관찰하기에 알맞은 곳은 어디인가요?","options":[{"t":"주변이 어둡고 탁 트인 넓은 곳","correct":true},{"t":"밝은 가로등 바로 아래","mis":"SC4-2-u1-X14"},{"t":"높은 건물로 둘러싸인 좁은 골목","mis":"SC4-2-u1-X14"},{"t":"창문이 없는 방 안","mis":"SC4-2-u1-X14"}],"explanation":["하늘이 잘 보여야 해요.","어둡고 넓은 곳이에요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_sci_u1_L03_basic#7','sci',4,2,'u1','L03','g4_2_sci_u1_L03_basic','lesson_basic','SC4-2-u1-C10',2,'match','auto','달의 이름과 모양을 알맞게 이으세요.','{}'::text[],false,'{"seq":7,"concept":"SC4-2-u1-C10","difficulty":2,"kind":"match","stem":"달의 이름과 모양을 알맞게 이으세요.","pairs":[{"l":"초승달","r":"눈썹 모양"},{"l":"상현달","r":"반달 모양"},{"l":"보름달","r":"둥근 모양"}],"mis":"SC4-2-u1-X18","explanation":["차례를 떠올려요.","보름달은 꽉 찼어요.","초승달-눈썹, 상현달-반달, 보름달-둥근 모양이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_sci_u1_L03_basic#8','sci',4,2,'u1','L03','g4_2_sci_u1_L03_basic','lesson_basic','SC4-2-u1-C11',2,'ox','auto','여러 날 동안 보이는 달의 모양은 늘 같아요.',ARRAY['SC4-2-u1-X19']::text[],false,'{"seq":8,"concept":"SC4-2-u1-C11","difficulty":2,"kind":"ox","stem":"여러 날 동안 보이는 달의 모양은 늘 같아요.","answer":"X","reason_options":[{"t":"여러 날 동안 관찰하면 보이는 달의 모양이 조금씩 달라지기 때문에","correct":true},{"t":"달은 언제나 둥근 모양으로만 보이기 때문에","mis":"SC4-2-u1-X19"}],"mis":"SC4-2-u1-X19","explanation":["관찰 기록을 떠올려요.","모양이 달라졌어요.","그래서 X예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_sci_u1_L03_basic#9','sci',4,2,'u1','L03','g4_2_sci_u1_L03_basic','lesson_basic','SC4-2-u1-C9',2,'mc','auto','달을 관찰할 때 지켜야 할 것으로 알맞은 것은 무엇인가요?',ARRAY['SC4-2-u1-X16']::text[],false,'{"seq":9,"concept":"SC4-2-u1-C9","difficulty":2,"kind":"mc","stem":"달을 관찰할 때 지켜야 할 것으로 알맞은 것은 무엇인가요?","options":[{"t":"너무 늦은 밤이나 새벽 시간에는 관찰하지 않는다","correct":true},{"t":"어른에게 말하지 않고 혼자 나간다","mis":"SC4-2-u1-X16"},{"t":"새벽에 몰래 나가 관찰한다","mis":"SC4-2-u1-X16"},{"t":"어른 없이 아주 늦은 밤에 나간다","mis":"SC4-2-u1-X16"}],"explanation":["안전을 떠올려요.","시간도 중요해요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_sci_u1_L03_basic#10','sci',4,2,'u1','L03','g4_2_sci_u1_L03_basic','lesson_basic','SC4-2-u1-C11',3,'mc','auto','오늘 초승달을 관찰했다면 약 30일 뒤에는 어떤 달을 볼 수 있나요?',ARRAY['SC4-2-u1-X20','SC4-2-u1-X22']::text[],false,'{"seq":10,"concept":"SC4-2-u1-C11","difficulty":3,"kind":"mc","stem":"오늘 초승달을 관찰했다면 약 30일 뒤에는 어떤 달을 볼 수 있나요?","options":[{"t":"다시 초승달","correct":true},{"t":"보름달","mis":"SC4-2-u1-X20"},{"t":"하현달","mis":"SC4-2-u1-X20"},{"t":"더 이상 달을 볼 수 없다","mis":"SC4-2-u1-X22"}],"explanation":["약 30일을 떠올려요.","같은 모양이 다시 와요.","다시 초승달이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_sci_u1_L03_challenge#1','sci',4,2,'u1','L03','g4_2_sci_u1_L03_challenge','lesson_challenge','SC4-2-u1-C8',2,'mc','auto','어느 친구의 달 관찰 계획서에서 ㉠에 쓸 내용으로 알맞은 것은 무엇인가요?',ARRAY['SC4-2-u1-X14','SC4-2-u1-X15','SC4-2-u1-X16']::text[],false,'{"seq":1,"concept":"SC4-2-u1-C8","difficulty":2,"kind":"mc","stem":"어느 친구의 달 관찰 계획서에서 ㉠에 쓸 내용으로 알맞은 것은 무엇인가요?","options":[{"t":"초승달이 보일 무렵부터 여러 날 동안","correct":true},{"t":"오늘 저녁 한 번","mis":"SC4-2-u1-X14"},{"t":"비 오는 날에만","mis":"SC4-2-u1-X15"},{"t":"새벽 시간에만","mis":"SC4-2-u1-X16"}],"explanation":["여러 날 동안 관찰해요.","2일~3일마다 봐요.","첫 번째예요."],"asset":{"type":"passage","lines":["관찰 기간 — ㉠","관찰 장소 — 주변이 어둡고 탁 트인 넓은 곳","관찰 간격 — 2일~3일마다","기록 — 관찰한 날짜를 쓰고 같은 모양의 붙임딱지를 붙여요."],"title":"어느 친구의 달 관찰 계획서"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_sci_u1_L03_challenge#2','sci',4,2,'u1','L03','g4_2_sci_u1_L03_challenge','lesson_challenge','SC4-2-u1-C8',2,'ox','auto','관찰한 달과 똑같은 모양의 붙임딱지가 없으면 붙이지 않고 비워 두어요.',ARRAY['SC4-2-u1-X14']::text[],false,'{"seq":2,"concept":"SC4-2-u1-C8","difficulty":2,"kind":"ox","stem":"관찰한 달과 똑같은 모양의 붙임딱지가 없으면 붙이지 않고 비워 두어요.","answer":"X","reason_options":[{"t":"가장 비슷한 모양의 붙임딱지를 붙이면 되기 때문에","correct":true},{"t":"똑같은 모양이 아니면 관찰한 것이 아니기 때문에","mis":"SC4-2-u1-X14"}],"mis":"SC4-2-u1-X14","explanation":["붙임딱지를 떠올려요.","비슷한 것을 골라요.","그래서 X예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_sci_u1_L03_challenge#3','sci',4,2,'u1','L03','g4_2_sci_u1_L03_challenge','lesson_challenge','SC4-2-u1-C11',3,'error','auto','달을 관찰한 뒤 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SC4-2-u1-X21','SC4-2-u1-X19','SC4-2-u1-X22']::text[],false,'{"seq":3,"concept":"SC4-2-u1-C11","difficulty":3,"kind":"error","stem":"달을 관찰한 뒤 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"친구 다 — 「달의 모양이 실제로 변해서 다르게 보이는 거야.」","correct":true,"mis_target":"SC4-2-u1-X21"},{"t":"친구 가 — 「보이는 달의 모양이 며칠마다 조금씩 달라졌어.」","mis":"SC4-2-u1-X19"},{"t":"친구 나 — 「그믐달을 보고 며칠 뒤 다시 초승달을 봤어.」","mis":"SC4-2-u1-X22"}],"explanation":["실제 달의 모양을 떠올려요.","실제 모양은 그대로예요.","친구 다가 잘못 말했어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_sci_u1_L03_challenge#4','sci',4,2,'u1','L03','g4_2_sci_u1_L03_challenge','lesson_challenge','SC4-2-u1-C10',3,'mc','auto','달의 모양이 달라지는 차례로 알맞은 것은 무엇인가요?',ARRAY['SC4-2-u1-X17','SC4-2-u1-X19']::text[],false,'{"seq":4,"concept":"SC4-2-u1-C10","difficulty":3,"kind":"mc","stem":"달의 모양이 달라지는 차례로 알맞은 것은 무엇인가요?","options":[{"t":"초승달 → 상현달 → 보름달 → 하현달 → 그믐달","correct":true},{"t":"초승달 → 하현달 → 보름달 → 상현달 → 그믐달","mis":"SC4-2-u1-X17"},{"t":"보름달 → 초승달 → 그믐달 → 상현달 → 하현달","mis":"SC4-2-u1-X19"},{"t":"그믐달 → 하현달 → 보름달 → 초승달 → 상현달","mis":"SC4-2-u1-X17"}],"explanation":["초승달부터 시작해요.","보름달은 가운데예요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_sci_u1_L03_challenge#5','sci',4,2,'u1','L03','g4_2_sci_u1_L03_challenge','lesson_challenge','SC4-2-u1-C8',3,'mc','auto','흐린 날이 이어져 달이 보이지 않았어요. 알맞은 행동은 무엇인가요?',ARRAY['SC4-2-u1-X15','SC4-2-u1-X14']::text[],false,'{"seq":5,"concept":"SC4-2-u1-C8","difficulty":3,"kind":"mc","stem":"흐린 날이 이어져 달이 보이지 않았어요. 알맞은 행동은 무엇인가요?","options":[{"t":"관찰 시기나 날씨에 따라 보이지 않을 수 있으니 스마트 기기로 달의 모양을 알아본다","correct":true},{"t":"달이 없어졌다고 기록한다","mis":"SC4-2-u1-X15"},{"t":"관찰을 그만두고 계획서를 버린다","mis":"SC4-2-u1-X15"},{"t":"보이지 않았지만 보름달 붙임딱지를 붙인다","mis":"SC4-2-u1-X14"}],"explanation":["달이 사라진 것이 아니에요.","다른 방법이 있어요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_sci_u1_L03_challenge#6','sci',4,2,'u1','L03','g4_2_sci_u1_L03_challenge','lesson_challenge','SC4-2-u1-C11',3,'mc','auto','붙임딱지를 여섯 장 붙이는 동안 「실제 달의 모양」 칸이 한 번도 바뀌지 않았어요. 이것으로 알 수 있는 것은 무엇인가요?',ARRAY['SC4-2-u1-X21','SC4-2-u1-X19','SC4-2-u1-X22']::text[],false,'{"seq":6,"concept":"SC4-2-u1-C11","difficulty":3,"kind":"mc","stem":"붙임딱지를 여섯 장 붙이는 동안 「실제 달의 모양」 칸이 한 번도 바뀌지 않았어요. 이것으로 알 수 있는 것은 무엇인가요?","options":[{"t":"보이는 달의 모양은 달라져도 실제 달의 모양은 변하지 않는다","correct":true},{"t":"실제 달의 모양도 날마다 바뀐다","mis":"SC4-2-u1-X21"},{"t":"보이는 달의 모양도 바뀌지 않는다","mis":"SC4-2-u1-X19"},{"t":"그믐달 뒤에는 달이 사라진다","mis":"SC4-2-u1-X22"}],"explanation":["두 칸을 견줘요.","실제 칸은 그대로예요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_sci_u1_L03_challenge#7','sci',4,2,'u1','L03','g4_2_sci_u1_L03_challenge','lesson_challenge','SC4-2-u1-C9',3,'mc','auto','달 관찰 안전을 지킨 친구는 누구인가요?',ARRAY['SC4-2-u1-X16']::text[],false,'{"seq":7,"concept":"SC4-2-u1-C9","difficulty":3,"kind":"mc","stem":"달 관찰 안전을 지킨 친구는 누구인가요?","options":[{"t":"친구 가 — 저녁에 어른과 함께 집 앞 공터에서 관찰했다","correct":true},{"t":"친구 나 — 새벽에 혼자 몰래 나갔다","mis":"SC4-2-u1-X16"},{"t":"친구 다 — 아주 늦은 밤에 혼자 놀이터에 갔다","mis":"SC4-2-u1-X16"},{"t":"친구 라 — 어른에게 말하지 않고 밤에 나갔다","mis":"SC4-2-u1-X16"}],"explanation":["어른과 함께예요.","시간도 봐요.","친구 가예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_sci_u1_L03_challenge#8','sci',4,2,'u1','L03','g4_2_sci_u1_L03_challenge','lesson_challenge','SC4-2-u1-C11',4,'mc','auto','친구가 「오늘 상현달을 봤으니 내일도 상현달을 볼 수 있어.」라고 했어요. 바르게 고친 것은 무엇인가요?',ARRAY['SC4-2-u1-X20','SC4-2-u1-X22','SC4-2-u1-X19']::text[],false,'{"seq":8,"concept":"SC4-2-u1-C11","difficulty":4,"kind":"mc","stem":"친구가 「오늘 상현달을 봤으니 내일도 상현달을 볼 수 있어.」라고 했어요. 바르게 고친 것은 무엇인가요?","options":[{"t":"「달의 모양은 조금씩 달라지고, 같은 모양의 달을 다시 보려면 약 30일이 걸려.」","correct":true},{"t":"「다음 상현달은 약 15일 뒤에 볼 수 있어.」","mis":"SC4-2-u1-X20"},{"t":"「상현달은 한 번 보면 다시 볼 수 없어.」","mis":"SC4-2-u1-X22"},{"t":"「내일은 바로 그믐달이 될 거야.」","mis":"SC4-2-u1-X19"}],"explanation":["모양은 조금씩 바뀌어요.","다시 같은 모양은 약 30일 뒤예요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_sci_u1_L03_challenge#9','sci',4,2,'u1','L03','g4_2_sci_u1_L03_challenge','lesson_challenge','SC4-2-u1-C10',4,'mc','auto','여러 날 동안 관찰한 달에서 첫째 날 본 달과 마지막 날 본 달의 이름을 차례대로 쓴 것은 무엇인가요?',ARRAY['SC4-2-u1-X17','SC4-2-u1-X18']::text[],false,'{"seq":9,"concept":"SC4-2-u1-C10","difficulty":4,"kind":"mc","stem":"여러 날 동안 관찰한 달에서 첫째 날 본 달과 마지막 날 본 달의 이름을 차례대로 쓴 것은 무엇인가요?","options":[{"t":"초승달, 그믐달","correct":true},{"t":"그믐달, 초승달","mis":"SC4-2-u1-X17"},{"t":"상현달, 하현달","mis":"SC4-2-u1-X18"},{"t":"보름달, 초승달","mis":"SC4-2-u1-X18"}],"explanation":["둘 다 눈썹 모양이에요.","처음과 끝이 달라요.","초승달, 그믐달이에요."],"asset":{"type":"passage","lines":["첫째 날 — 눈썹 모양의 달","며칠 뒤 — 반달","또 며칠 뒤 — 둥근 달","또 며칠 뒤 — 다시 반달 ㉠","또 며칠 뒤 — 다시 눈썹 모양의 달"],"title":"여러 날 동안 관찰한 달"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_sci_u1_L03_challenge#10','sci',4,2,'u1','L03','g4_2_sci_u1_L03_challenge','lesson_challenge','SC4-2-u1-C10',4,'essay','teacher','여러 날 동안 달을 관찰하는 계획을 세울 때 정할 것 두 가지와 지킬 안전 수칙 한 가지를 쓰고, 초승달부터 관찰했을 때 달의 모양이 달라지는 차례를 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"SC4-2-u1-C10","difficulty":4,"kind":"essay","stem":"여러 날 동안 달을 관찰하는 계획을 세울 때 정할 것 두 가지와 지킬 안전 수칙 한 가지를 쓰고, 초승달부터 관찰했을 때 달의 모양이 달라지는 차례를 쓰세요.","answer_guide":{"answer":"예: 관찰할 기간과 장소(주변이 어둡고 탁 트인 넓은 곳)를 정한다. 어른과 함께 외출하고 너무 늦은 밤이나 새벽에는 관찰하지 않는다. 달의 모양은 초승달, 상현달, 보름달, 하현달, 그믐달 차례로 달라진다.","scoring_points":["관찰 계획에서 정할 것 두 가지를 썼는가","안전 수칙을 썼는가","달의 모양이 달라지는 차례를 바르게 썼는가"]},"explanation":["계획을 써요.","안전을 써요.","차례를 써요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_sci_u1_L04_basic#1','sci',4,2,'u1','L04','g4_2_sci_u1_L04_basic','lesson_basic','SC4-2-u1-C12',1,'mc','auto','태양은 태양계의 어디에 있나요?',ARRAY['SC4-2-u1-X25']::text[],false,'{"seq":1,"concept":"SC4-2-u1-C12","difficulty":1,"kind":"mc","stem":"태양은 태양계의 어디에 있나요?","options":[{"t":"중심","correct":true},{"t":"가장 바깥쪽","mis":"SC4-2-u1-X25"},{"t":"지구 바로 옆","mis":"SC4-2-u1-X25"},{"t":"토성 주위","mis":"SC4-2-u1-X25"}],"explanation":["태양계를 떠올려요.","행성이 태양 주위를 돌아요.","중심이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_sci_u1_L04_basic#2','sci',4,2,'u1','L04','g4_2_sci_u1_L04_basic','lesson_basic','SC4-2-u1-C14',1,'sa','auto','행성 카드 네 장에서 ㉡은 어느 행성인가요? 두 글자로 쓰세요.','{}'::text[],false,'{"seq":2,"concept":"SC4-2-u1-C14","difficulty":1,"kind":"sa","stem":"행성 카드 네 장에서 ㉡은 어느 행성인가요? 두 글자로 쓰세요.","answer":["토성"],"explanation":["㉡을 읽어요.","크고 뚜렷한 고리예요.","토성이에요."],"asset":{"type":"passage","lines":["㉠ — 붉은색으로 보이고, 표면에 단단한 땅이 있어요.","㉡ — 연한 노란색이고, 크고 뚜렷한 고리가 있어요.","㉢ — 회색으로 보이고, 표면의 모습이 달과 비슷해요.","㉣ — 파란색이고, 표면에 검은 점이 있어요."],"title":"행성 카드 네 장"},"mis":"SC4-2-u1-X29"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_sci_u1_L04_basic#3','sci',4,2,'u1','L04','g4_2_sci_u1_L04_basic','lesson_basic','SC4-2-u1-C13',1,'ox','auto','달은 태양계의 여덟 행성 가운데 하나예요.',ARRAY['SC4-2-u1-X26']::text[],false,'{"seq":3,"concept":"SC4-2-u1-C13","difficulty":1,"kind":"ox","stem":"달은 태양계의 여덟 행성 가운데 하나예요.","answer":"X","reason_options":[{"t":"여덟 행성은 수성, 금성, 지구, 화성, 목성, 토성, 천왕성, 해왕성이기 때문에","correct":true},{"t":"밤하늘에서 밝게 보이는 것은 모두 행성이기 때문에","mis":"SC4-2-u1-X26"}],"mis":"SC4-2-u1-X26","explanation":["여덟 행성을 떠올려요.","달은 없어요.","그래서 X예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_sci_u1_L04_basic#4','sci',4,2,'u1','L04','g4_2_sci_u1_L04_basic','lesson_basic','SC4-2-u1-C13',1,'mc','auto','태양에서 가장 가까이 있는 행성은 무엇인가요?',ARRAY['SC4-2-u1-X26']::text[],false,'{"seq":4,"concept":"SC4-2-u1-C13","difficulty":1,"kind":"mc","stem":"태양에서 가장 가까이 있는 행성은 무엇인가요?","options":[{"t":"수성","correct":true},{"t":"해왕성","mis":"SC4-2-u1-X26"},{"t":"지구","mis":"SC4-2-u1-X26"},{"t":"목성","mis":"SC4-2-u1-X26"}],"explanation":["차례를 떠올려요.","수·금·지·화예요.","수성이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_sci_u1_L04_basic#5','sci',4,2,'u1','L04','g4_2_sci_u1_L04_basic','lesson_basic','SC4-2-u1-C12',2,'mc','auto','태양계의 뜻으로 알맞은 것은 무엇인가요?',ARRAY['SC4-2-u1-X23','SC4-2-u1-X24','SC4-2-u1-X25']::text[],false,'{"seq":5,"concept":"SC4-2-u1-C12","difficulty":2,"kind":"mc","stem":"태양계의 뜻으로 알맞은 것은 무엇인가요?","options":[{"t":"태양을 비롯하여 태양의 영향을 받는 천체들과 그 공간","correct":true},{"t":"태양과 여덟 행성만을 묶어 부르는 말","mis":"SC4-2-u1-X23"},{"t":"태양계의 천체들만 가리키고 공간은 빼는 말","mis":"SC4-2-u1-X24"},{"t":"지구를 중심으로 도는 천체들","mis":"SC4-2-u1-X25"}],"explanation":["천체만일까요?","공간도 들어가요.","첫 번째예요."],"asset":{"type":"passage","lines":["뜻 — 태양을 비롯하여 태양의 영향을 받는 천체들과 그 공간","태양 — 태양계의 ㉠에 있어요.","행성 — 태양 주위를 돌고 있어요.","그 밖 — 여덟 행성 말고도 여러 가지 천체가 있어요."],"title":"태양계 알아보기"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_sci_u1_L04_basic#6','sci',4,2,'u1','L04','g4_2_sci_u1_L04_basic','lesson_basic','SC4-2-u1-C14',2,'mc','auto','표면에 단단한 땅이 있는 행성끼리 묶은 것은 무엇인가요?',ARRAY['SC4-2-u1-X27']::text[],false,'{"seq":6,"concept":"SC4-2-u1-C14","difficulty":2,"kind":"mc","stem":"표면에 단단한 땅이 있는 행성끼리 묶은 것은 무엇인가요?","options":[{"t":"수성, 금성, 지구, 화성","correct":true},{"t":"목성, 토성, 천왕성, 해왕성","mis":"SC4-2-u1-X27"},{"t":"수성, 목성, 토성, 화성","mis":"SC4-2-u1-X27"},{"t":"금성, 지구, 천왕성, 해왕성","mis":"SC4-2-u1-X27"}],"explanation":["태양에서 가까운 네 행성이에요.","고리가 없어요.","수성, 금성, 지구, 화성이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_sci_u1_L04_basic#7','sci',4,2,'u1','L04','g4_2_sci_u1_L04_basic','lesson_basic','SC4-2-u1-C14',2,'match','auto','특징과 행성을 알맞게 이으세요.','{}'::text[],false,'{"seq":7,"concept":"SC4-2-u1-C14","difficulty":2,"kind":"match","stem":"특징과 행성을 알맞게 이으세요.","pairs":[{"l":"회색이고 표면의 모습이 달과 비슷해요","r":"수성"},{"l":"붉은색이고 단단한 땅이 있어요","r":"화성"},{"l":"표면에 줄무늬와 붉은 점이 보여요","r":"목성"}],"mis":"SC4-2-u1-X29","explanation":["색깔을 떠올려요.","붉은 점은 목성이에요.","회색-수성, 붉은색-화성, 붉은 점-목성이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_sci_u1_L04_basic#8','sci',4,2,'u1','L04','g4_2_sci_u1_L04_basic','lesson_basic','SC4-2-u1-C14',2,'ox','auto','고리를 가진 행성은 토성 하나뿐이에요.',ARRAY['SC4-2-u1-X28']::text[],false,'{"seq":8,"concept":"SC4-2-u1-C14","difficulty":2,"kind":"ox","stem":"고리를 가진 행성은 토성 하나뿐이에요.","answer":"X","reason_options":[{"t":"목성, 천왕성, 해왕성에도 희미한 고리가 있기 때문에","correct":true},{"t":"그림에서 고리가 뚜렷하게 보이는 행성은 토성뿐이기 때문에","mis":"SC4-2-u1-X28"}],"mis":"SC4-2-u1-X28","explanation":["희미한 고리를 떠올려요.","고리가 있는 행성은 넷이에요.","그래서 X예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_sci_u1_L04_basic#9','sci',4,2,'u1','L04','g4_2_sci_u1_L04_basic','lesson_basic','SC4-2-u1-C15',2,'mc','auto','행성 모형을 만들 때의 행동으로 알맞은 것은 무엇인가요?',ARRAY['SC4-2-u1-X30','SC4-2-u1-X31']::text[],false,'{"seq":9,"concept":"SC4-2-u1-C15","difficulty":2,"kind":"mc","stem":"행성 모형을 만들 때의 행동으로 알맞은 것은 무엇인가요?","options":[{"t":"그림 도구의 뾰족한 곳에 찔리지 않도록 조심한다","correct":true},{"t":"그림 도구를 던지며 장난친다","mis":"SC4-2-u1-X30"},{"t":"뾰족한 곳을 친구 쪽으로 향하게 든다","mis":"SC4-2-u1-X30"},{"t":"친구가 만든 모형을 보고 놀린다","mis":"SC4-2-u1-X31"}],"explanation":["안전을 떠올려요.","뾰족한 곳을 조심해요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_sci_u1_L04_basic#10','sci',4,2,'u1','L04','g4_2_sci_u1_L04_basic','lesson_basic','SC4-2-u1-C14',3,'mc','auto','행성 카드 네 장에서 표면이 기체로 이루어진 행성끼리 묶은 것은 무엇인가요?',ARRAY['SC4-2-u1-X27']::text[],false,'{"seq":10,"concept":"SC4-2-u1-C14","difficulty":3,"kind":"mc","stem":"행성 카드 네 장에서 표면이 기체로 이루어진 행성끼리 묶은 것은 무엇인가요?","options":[{"t":"㉡, ㉣","correct":true},{"t":"㉠, ㉢","mis":"SC4-2-u1-X27"},{"t":"㉠, ㉡","mis":"SC4-2-u1-X27"},{"t":"㉢, ㉣","mis":"SC4-2-u1-X27"}],"explanation":["㉡은 토성, ㉣은 해왕성이에요.","고리가 있는 행성들이에요.","㉡, ㉣이에요."],"asset":{"type":"passage","lines":["㉠ — 붉은색으로 보이고, 표면에 단단한 땅이 있어요.","㉡ — 연한 노란색이고, 크고 뚜렷한 고리가 있어요.","㉢ — 회색으로 보이고, 표면의 모습이 달과 비슷해요.","㉣ — 파란색이고, 표면에 검은 점이 있어요."],"title":"행성 카드 네 장"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_sci_u1_L04_challenge#1','sci',4,2,'u1','L04','g4_2_sci_u1_L04_challenge','lesson_challenge','SC4-2-u1-C12',2,'blank','auto','「태양계에는 여덟 개의 행성이 있으며, 이 외에도 (    )이/가 있어요.」 빈칸에 알맞은 말은 무엇인가요?',ARRAY['SC4-2-u1-X23','SC4-2-u1-X26','SC4-2-u1-X25']::text[],false,'{"seq":1,"concept":"SC4-2-u1-C12","difficulty":2,"kind":"blank","stem":"「태양계에는 여덟 개의 행성이 있으며, 이 외에도 (    )이/가 있어요.」 빈칸에 알맞은 말은 무엇인가요?","options":[{"t":"여러 가지 천체","correct":true},{"t":"아무것도 없음","mis":"SC4-2-u1-X23"},{"t":"태양 주위를 도는 달 하나","mis":"SC4-2-u1-X26"},{"t":"또 다른 태양 여러 개","mis":"SC4-2-u1-X25"}],"explanation":["태양과 행성만일까요?","다른 천체도 있어요.","여러 가지 천체예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_sci_u1_L04_challenge#2','sci',4,2,'u1','L04','g4_2_sci_u1_L04_challenge','lesson_challenge','SC4-2-u1-C13',2,'mc','auto','태양에서 가까운 차례로 행성을 바르게 늘어놓은 것은 무엇인가요?',ARRAY['SC4-2-u1-X26']::text[],false,'{"seq":2,"concept":"SC4-2-u1-C13","difficulty":2,"kind":"mc","stem":"태양에서 가까운 차례로 행성을 바르게 늘어놓은 것은 무엇인가요?","options":[{"t":"수성, 금성, 지구, 화성, 목성, 토성, 천왕성, 해왕성","correct":true},{"t":"수성, 지구, 금성, 화성, 토성, 목성, 해왕성, 천왕성","mis":"SC4-2-u1-X26"},{"t":"지구, 수성, 금성, 화성, 목성, 토성, 천왕성, 해왕성","mis":"SC4-2-u1-X26"},{"t":"수성, 금성, 지구, 달, 화성, 목성, 토성, 천왕성","mis":"SC4-2-u1-X26"}],"explanation":["수성부터예요.","달은 행성이 아니에요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_sci_u1_L04_challenge#3','sci',4,2,'u1','L04','g4_2_sci_u1_L04_challenge','lesson_challenge','SC4-2-u1-C12',3,'error','auto','태양계에 대해 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SC4-2-u1-X23','SC4-2-u1-X24','SC4-2-u1-X25']::text[],false,'{"seq":3,"concept":"SC4-2-u1-C12","difficulty":3,"kind":"error","stem":"태양계에 대해 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"친구 나 — 「태양계에는 태양과 행성만 있어.」","correct":true,"mis_target":"SC4-2-u1-X23"},{"t":"친구 가 — 「태양계는 천체들과 그 공간까지 함께 가리켜.」","mis":"SC4-2-u1-X24"},{"t":"친구 다 — 「행성은 태양 주위를 돌고 있어.」","mis":"SC4-2-u1-X25"}],"explanation":["태양계의 뜻을 떠올려요.","여러 가지 천체가 있어요.","친구 나가 잘못 말했어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_sci_u1_L04_challenge#4','sci',4,2,'u1','L04','g4_2_sci_u1_L04_challenge','lesson_challenge','SC4-2-u1-C14',3,'mc','auto','고리가 있는 행성과 없는 행성으로 바르게 나눈 것은 무엇인가요?',ARRAY['SC4-2-u1-X28','SC4-2-u1-X27','SC4-2-u1-X29']::text[],false,'{"seq":4,"concept":"SC4-2-u1-C14","difficulty":3,"kind":"mc","stem":"고리가 있는 행성과 없는 행성으로 바르게 나눈 것은 무엇인가요?","options":[{"t":"있는 행성 — 목성, 토성, 천왕성, 해왕성 / 없는 행성 — 수성, 금성, 지구, 화성","correct":true},{"t":"있는 행성 — 토성 / 없는 행성 — 나머지 일곱 행성","mis":"SC4-2-u1-X28"},{"t":"있는 행성 — 수성, 금성, 지구, 화성 / 없는 행성 — 목성, 토성, 천왕성, 해왕성","mis":"SC4-2-u1-X27"},{"t":"여덟 행성 모두 고리가 있다","mis":"SC4-2-u1-X29"}],"explanation":["희미한 고리도 고리예요.","기체로 된 행성들이에요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_sci_u1_L04_challenge#5','sci',4,2,'u1','L04','g4_2_sci_u1_L04_challenge','lesson_challenge','SC4-2-u1-C14',3,'mc','auto','「노란색으로 보이고, 표면에 단단한 땅이 있으며, 지구에서 가장 밝게 보이는 행성」은 무엇인가요?',ARRAY['SC4-2-u1-X25','SC4-2-u1-X26','SC4-2-u1-X27']::text[],false,'{"seq":5,"concept":"SC4-2-u1-C14","difficulty":3,"kind":"mc","stem":"「노란색으로 보이고, 표면에 단단한 땅이 있으며, 지구에서 가장 밝게 보이는 행성」은 무엇인가요?","options":[{"t":"금성","correct":true},{"t":"태양","mis":"SC4-2-u1-X25"},{"t":"달","mis":"SC4-2-u1-X26"},{"t":"목성","mis":"SC4-2-u1-X27"}],"explanation":["행성을 찾아요.","단단한 땅이 있어요.","금성이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_sci_u1_L04_challenge#6','sci',4,2,'u1','L04','g4_2_sci_u1_L04_challenge','lesson_challenge','SC4-2-u1-C12',3,'ox','auto','천체는 우주에 있는 별, 행성 등을 모두 가리키는 말이에요.',ARRAY['SC4-2-u1-X23']::text[],false,'{"seq":6,"concept":"SC4-2-u1-C12","difficulty":3,"kind":"ox","stem":"천체는 우주에 있는 별, 행성 등을 모두 가리키는 말이에요.","answer":"O","reason_options":[{"t":"우주에 있는 것을 모두 천체라고 부르기 때문에","correct":true},{"t":"행성만 천체라고 부르기 때문에","mis":"SC4-2-u1-X23"}],"mis":"SC4-2-u1-X23","explanation":["천체의 뜻을 떠올려요.","모두 가리켜요.","그래서 O예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_sci_u1_L04_challenge#7','sci',4,2,'u1','L04','g4_2_sci_u1_L04_challenge','lesson_challenge','SC4-2-u1-C15',3,'mc','auto','모둠에서 행성 모형을 만들 때 먼저 할 일로 알맞은 것은 무엇인가요?',ARRAY['SC4-2-u1-X31','SC4-2-u1-X30']::text[],false,'{"seq":7,"concept":"SC4-2-u1-C15","difficulty":3,"kind":"mc","stem":"모둠에서 행성 모형을 만들 때 먼저 할 일로 알맞은 것은 무엇인가요?","options":[{"t":"주의할 점을 확인하고, 각자 만들 행성을 정해 빠뜨린 행성이 없는지 살핀다","correct":true},{"t":"한 사람이 여덟 행성을 모두 만든다","mis":"SC4-2-u1-X31"},{"t":"뾰족한 도구를 친구에게 던져 나눈다","mis":"SC4-2-u1-X30"},{"t":"특징은 신경 쓰지 않고 예쁜 색부터 고른다","mis":"SC4-2-u1-X31"}],"explanation":["만들기 전에 정해요.","안전부터예요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_sci_u1_L04_challenge#8','sci',4,2,'u1','L04','g4_2_sci_u1_L04_challenge','lesson_challenge','SC4-2-u1-C14',4,'mc','auto','행성 카드 ㉠~㉣을 「표면에 단단한 땅이 있는가?」로 나눌 때 ⭕ 쪽 행성의 이름을 차례대로 쓴 것은 무엇인가요?',ARRAY['SC4-2-u1-X27']::text[],false,'{"seq":8,"concept":"SC4-2-u1-C14","difficulty":4,"kind":"mc","stem":"행성 카드 ㉠~㉣을 「표면에 단단한 땅이 있는가?」로 나눌 때 ⭕ 쪽 행성의 이름을 차례대로 쓴 것은 무엇인가요?","options":[{"t":"화성, 수성","correct":true},{"t":"토성, 해왕성","mis":"SC4-2-u1-X27"},{"t":"화성, 토성","mis":"SC4-2-u1-X27"},{"t":"수성, 해왕성","mis":"SC4-2-u1-X27"}],"explanation":["㉠과 ㉢을 읽어요.","붉은색과 회색이에요.","화성, 수성이에요."],"asset":{"type":"passage","lines":["㉠ — 붉은색으로 보이고, 표면에 단단한 땅이 있어요.","㉡ — 연한 노란색이고, 크고 뚜렷한 고리가 있어요.","㉢ — 회색으로 보이고, 표면의 모습이 달과 비슷해요.","㉣ — 파란색이고, 표면에 검은 점이 있어요."],"title":"행성 카드 네 장"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_sci_u1_L04_challenge#9','sci',4,2,'u1','L04','g4_2_sci_u1_L04_challenge','lesson_challenge','SC4-2-u1-C15',4,'mc','auto','토성 모형을 만든 친구에게 해 줄 말로 가장 알맞은 것은 무엇인가요?',ARRAY['SC4-2-u1-X31','SC4-2-u1-X29']::text[],false,'{"seq":9,"concept":"SC4-2-u1-C15","difficulty":4,"kind":"mc","stem":"토성 모형을 만든 친구에게 해 줄 말로 가장 알맞은 것은 무엇인가요?","options":[{"t":"「연한 노란색에 크고 뚜렷한 고리와 줄무늬를 잘 나타냈구나.」","correct":true},{"t":"「색칠이 예쁘니 특징은 없어도 돼.」","mis":"SC4-2-u1-X31"},{"t":"「토성에는 고리가 없으니 떼어 내.」","mis":"SC4-2-u1-X29"},{"t":"「네 모형은 엉망이야.」","mis":"SC4-2-u1-X31"}],"explanation":["특징을 잘 나타냈는지 봐요.","잘한 점을 말해요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_sci_u1_L04_challenge#10','sci',4,2,'u1','L04','g4_2_sci_u1_L04_challenge','lesson_challenge','SC4-2-u1-C12',4,'essay','teacher','태양계의 뜻을 쓰고, 태양과 행성이 태양계의 어디에 있는지 쓰세요. 그리고 여덟 행성을 표면에 단단한 땅이 있는 행성과 표면이 기체로 이루어진 행성으로 나누어 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"SC4-2-u1-C12","difficulty":4,"kind":"essay","stem":"태양계의 뜻을 쓰고, 태양과 행성이 태양계의 어디에 있는지 쓰세요. 그리고 여덟 행성을 표면에 단단한 땅이 있는 행성과 표면이 기체로 이루어진 행성으로 나누어 쓰세요.","answer_guide":{"answer":"예: 태양계는 태양을 비롯하여 태양의 영향을 받는 천체들과 그 공간이다. 태양은 태양계 중심에 있고 행성은 태양 주위를 돌고 있다. 수성, 금성, 지구, 화성은 표면에 단단한 땅이 있고, 목성, 토성, 천왕성, 해왕성은 표면이 기체로 이루어져 있다.","scoring_points":["태양계의 뜻을 썼는가","태양과 행성의 자리를 썼는가","여덟 행성을 바르게 나누었는가"]},"explanation":["뜻부터 써요.","자리를 써요.","행성을 나눠요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_sci_u1_L05_basic#1','sci',4,2,'u1','L05','g4_2_sci_u1_L05_basic','lesson_basic','SC4-2-u1-C16',1,'mc','auto','스스로 빛을 내는 천체를 무엇이라고 하나요?',ARRAY['SC4-2-u1-X32']::text[],false,'{"seq":1,"concept":"SC4-2-u1-C16","difficulty":1,"kind":"mc","stem":"스스로 빛을 내는 천체를 무엇이라고 하나요?","options":[{"t":"별","correct":true},{"t":"행성","mis":"SC4-2-u1-X32"},{"t":"달","mis":"SC4-2-u1-X32"},{"t":"구름","mis":"SC4-2-u1-X32"}],"explanation":["빛을 스스로 내요.","북극성 같은 천체예요.","별이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_sci_u1_L05_basic#2','sci',4,2,'u1','L05','g4_2_sci_u1_L05_basic','lesson_basic','SC4-2-u1-C18',1,'sa','auto','북극성 주변 관찰 기록에서 ㉡에 알맞은 별의 이름을 쓰세요.','{}'::text[],false,'{"seq":2,"concept":"SC4-2-u1-C18","difficulty":1,"kind":"sa","stem":"북극성 주변 관찰 기록에서 ㉡에 알맞은 별의 이름을 쓰세요.","answer":["북극성"],"explanation":["작은곰자리 줄을 읽어요.","북쪽을 알려 주는 별이에요.","북극성이에요."],"asset":{"type":"passage","lines":["큰곰자리 — 꼬리 부분에 일곱 개의 별 ㉠이 있어요.","작은곰자리 — 꼬리 부분에 ㉡이 있어요.","카시오페이아자리 — 북쪽 밤하늘의 대표적인 별자리예요.","천체 관측 프로그램 — 이 밖에도 여러 별자리가 보였어요."],"title":"북극성 주변 관찰 기록"},"mis":"SC4-2-u1-X35"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_sci_u1_L05_basic#3','sci',4,2,'u1','L05','g4_2_sci_u1_L05_basic','lesson_basic','SC4-2-u1-C16',1,'ox','auto','태양은 태양계의 유일한 별이에요.',ARRAY['SC4-2-u1-X33']::text[],false,'{"seq":3,"concept":"SC4-2-u1-C16","difficulty":1,"kind":"ox","stem":"태양은 태양계의 유일한 별이에요.","answer":"O","reason_options":[{"t":"태양계에서 스스로 빛을 내는 천체는 태양뿐이기 때문에","correct":true},{"t":"태양은 행성 가운데 하나이기 때문에","mis":"SC4-2-u1-X33"}],"mis":"SC4-2-u1-X33","explanation":["스스로 빛을 내는 천체를 떠올려요.","태양계에는 하나예요.","그래서 O예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_sci_u1_L05_basic#4','sci',4,2,'u1','L05','g4_2_sci_u1_L05_basic','lesson_basic','SC4-2-u1-C18',1,'mc','auto','북극성과 북극성 주변의 별자리는 어느 쪽 밤하늘에서 볼 수 있나요?',ARRAY['SC4-2-u1-X38']::text[],false,'{"seq":4,"concept":"SC4-2-u1-C18","difficulty":1,"kind":"mc","stem":"북극성과 북극성 주변의 별자리는 어느 쪽 밤하늘에서 볼 수 있나요?","options":[{"t":"북쪽","correct":true},{"t":"남쪽","mis":"SC4-2-u1-X38"},{"t":"동쪽","mis":"SC4-2-u1-X38"},{"t":"서쪽","mis":"SC4-2-u1-X38"}],"explanation":["이름을 떠올려요.","북극성이에요.","북쪽이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_sci_u1_L05_basic#5','sci',4,2,'u1','L05','g4_2_sci_u1_L05_basic','lesson_basic','SC4-2-u1-C16',2,'mc','auto','만화 속 이야기를 보고 북극성과 목성의 다른 점을 바르게 쓴 것은 무엇인가요?',ARRAY['SC4-2-u1-X32']::text[],false,'{"seq":5,"concept":"SC4-2-u1-C16","difficulty":2,"kind":"mc","stem":"만화 속 이야기를 보고 북극성과 목성의 다른 점을 바르게 쓴 것은 무엇인가요?","options":[{"t":"북극성은 스스로 빛을 내지만 목성은 스스로 빛을 내지 않는다","correct":true},{"t":"목성은 스스로 빛을 내지만 북극성은 내지 않는다","mis":"SC4-2-u1-X32"},{"t":"둘 다 스스로 빛을 낸다","mis":"SC4-2-u1-X32"},{"t":"둘 다 스스로 빛을 내지 않는다","mis":"SC4-2-u1-X32"}],"explanation":["친구 라의 말을 읽어요.","목성은 행성이에요.","첫 번째예요."],"asset":{"type":"speech","turns":[{"who":"친구 가","text":"저기 북극성이 보여. 밤하늘에서 위치가 거의 변하지 않아."},{"who":"친구 나","text":"그래서 방향을 찾는 데 이용하기도 해."},{"who":"친구 다","text":"저기 목성도 보인다. 별처럼 빛나지만 별은 아니야."},{"who":"친구 라","text":"목성은 스스로 빛을 내지 않아."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_sci_u1_L05_basic#6','sci',4,2,'u1','L05','g4_2_sci_u1_L05_basic','lesson_basic','SC4-2-u1-C19',2,'mc','auto','스마트 기기로 별을 조사할 때 알맞은 행동은 무엇인가요?',ARRAY['SC4-2-u1-X13']::text[],false,'{"seq":6,"concept":"SC4-2-u1-C19","difficulty":2,"kind":"mc","stem":"스마트 기기로 별을 조사할 때 알맞은 행동은 무엇인가요?","options":[{"t":"옳은 정보와 거짓 정보를 구분한다","correct":true},{"t":"출처를 확인하지 않고 그대로 옮겨 쓴다","mis":"SC4-2-u1-X13"},{"t":"거짓 정보인지 살펴보지 않고 믿는다","mis":"SC4-2-u1-X13"},{"t":"친구가 찾은 글을 출처 없이 베낀다","mis":"SC4-2-u1-X13"}],"explanation":["정보를 살펴요.","거짓 정보도 있어요.","구분해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_sci_u1_L05_basic#7','sci',4,2,'u1','L05','g4_2_sci_u1_L05_basic','lesson_basic','SC4-2-u1-C17',2,'match','auto','설명과 알맞은 말을 이으세요.','{}'::text[],false,'{"seq":7,"concept":"SC4-2-u1-C17","difficulty":2,"kind":"match","stem":"설명과 알맞은 말을 이으세요.","pairs":[{"l":"스스로 빛을 내는 천체","r":"별"},{"l":"별들을 연결해 이름을 붙인 것","r":"별자리"},{"l":"큰곰자리 꼬리 부분의 일곱 개의 별","r":"북두칠성"}],"mis":"SC4-2-u1-X34","explanation":["하나씩 떠올려요.","별을 이은 것은 별자리예요.","천체-별, 이은 것-별자리, 일곱 별-북두칠성이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_sci_u1_L05_basic#8','sci',4,2,'u1','L05','g4_2_sci_u1_L05_basic','lesson_basic','SC4-2-u1-C18',2,'ox','auto','북극성은 정확한 북쪽 부근에서 위치가 거의 변하지 않아요.',ARRAY['SC4-2-u1-X38']::text[],false,'{"seq":8,"concept":"SC4-2-u1-C18","difficulty":2,"kind":"ox","stem":"북극성은 정확한 북쪽 부근에서 위치가 거의 변하지 않아요.","answer":"O","reason_options":[{"t":"그래서 밤에 방향을 찾는 데 이용하기도 하기 때문에","correct":true},{"t":"북극성은 밤마다 자리가 크게 바뀌기 때문에","mis":"SC4-2-u1-X38"}],"mis":"SC4-2-u1-X38","explanation":["만화를 떠올려요.","위치가 거의 그대로예요.","그래서 O예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_sci_u1_L05_basic#9','sci',4,2,'u1','L05','g4_2_sci_u1_L05_basic','lesson_basic','SC4-2-u1-C18',2,'mc','auto','북극성을 포함하고 있는 별자리는 무엇인가요?',ARRAY['SC4-2-u1-X35']::text[],false,'{"seq":9,"concept":"SC4-2-u1-C18","difficulty":2,"kind":"mc","stem":"북극성을 포함하고 있는 별자리는 무엇인가요?","options":[{"t":"작은곰자리","correct":true},{"t":"큰곰자리","mis":"SC4-2-u1-X35"},{"t":"카시오페이아자리","mis":"SC4-2-u1-X35"},{"t":"북두칠성","mis":"SC4-2-u1-X35"}],"explanation":["꼬리 부분을 떠올려요.","작은 곰이에요.","작은곰자리예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_sci_u1_L05_basic#10','sci',4,2,'u1','L05','g4_2_sci_u1_L05_basic','lesson_basic','SC4-2-u1-C17',3,'mc','auto','옛날과 지금의 별자리를 읽고 알 수 있는 것은 무엇인가요?',ARRAY['SC4-2-u1-X34']::text[],false,'{"seq":10,"concept":"SC4-2-u1-C17","difficulty":3,"kind":"mc","stem":"옛날과 지금의 별자리를 읽고 알 수 있는 것은 무엇인가요?","options":[{"t":"별자리는 사람들이 별을 연결해 이름을 붙인 것이어서 지역과 때에 따라 달랐다","correct":true},{"t":"별자리는 별들이 스스로 그린 그림이다","mis":"SC4-2-u1-X34"},{"t":"별자리의 이름과 모양은 한 번도 바뀌지 않았다","mis":"SC4-2-u1-X34"},{"t":"별자리는 행성을 연결한 것이다","mis":"SC4-2-u1-X34"}],"explanation":["옛날 별자리를 읽어요.","지역마다 달랐어요.","첫 번째예요."],"asset":{"type":"passage","lines":["옛날에는 별자리의 모습이나 이름이 지역에 따라 달랐어요.","시간이 지나면서 바뀌기도 했어요.","그래서 천문학자들이 공통으로 쓸 이름과 모양을 정했어요."],"title":"옛날과 지금의 별자리"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_sci_u1_L05_challenge#1','sci',4,2,'u1','L05','g4_2_sci_u1_L05_challenge','lesson_challenge','SC4-2-u1-C19',2,'mc','auto','천체 관측 프로그램으로 북극성 주변의 별자리를 관찰할 때 알맞은 차례는 무엇인가요?',ARRAY['SC4-2-u1-X39','SC4-2-u1-X38']::text[],false,'{"seq":1,"concept":"SC4-2-u1-C19","difficulty":2,"kind":"mc","stem":"천체 관측 프로그램으로 북극성 주변의 별자리를 관찰할 때 알맞은 차례는 무엇인가요?","options":[{"t":"사용 방법을 미리 확인하고, 먼저 북극성을 찾은 뒤 주변 별자리를 확인한다","correct":true},{"t":"사용 방법을 확인하지 않고 아무 화면이나 누른다","mis":"SC4-2-u1-X39"},{"t":"남쪽 하늘부터 찾는다","mis":"SC4-2-u1-X38"},{"t":"별자리 이름만 외우고 화면은 보지 않는다","mis":"SC4-2-u1-X39"}],"explanation":["북극성이 먼저예요.","그다음 주변을 봐요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_sci_u1_L05_challenge#2','sci',4,2,'u1','L05','g4_2_sci_u1_L05_challenge','lesson_challenge','SC4-2-u1-C18',2,'ox','auto','북두칠성은 작은곰자리의 꼬리 부분에 있어요.',ARRAY['SC4-2-u1-X36']::text[],false,'{"seq":2,"concept":"SC4-2-u1-C18","difficulty":2,"kind":"ox","stem":"북두칠성은 작은곰자리의 꼬리 부분에 있어요.","answer":"X","reason_options":[{"t":"북두칠성은 큰곰자리의 꼬리 부분에 있는 일곱 개의 별이기 때문에","correct":true},{"t":"북극성과 북두칠성은 같은 별자리에 있기 때문에","mis":"SC4-2-u1-X36"}],"mis":"SC4-2-u1-X36","explanation":["국자 모양 별들을 떠올려요.","큰곰자리예요.","그래서 X예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_sci_u1_L05_challenge#3','sci',4,2,'u1','L05','g4_2_sci_u1_L05_challenge','lesson_challenge','SC4-2-u1-C18',3,'error','auto','북극성 주변 관찰 기록을 보고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SC4-2-u1-X37','SC4-2-u1-X35']::text[],false,'{"seq":3,"concept":"SC4-2-u1-C18","difficulty":3,"kind":"error","stem":"북극성 주변 관찰 기록을 보고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"친구 나 — 「북쪽 하늘의 별자리는 이 세 개뿐이야.」","correct":true,"mis_target":"SC4-2-u1-X37"},{"t":"친구 가 — 「큰곰자리, 작은곰자리, 카시오페이아자리를 찾았어.」","mis":"SC4-2-u1-X35"},{"t":"친구 다 — 「프로그램을 켜니 별자리가 더 보였어.」","mis":"SC4-2-u1-X37"}],"explanation":["넷째 줄을 읽어요.","더 있었어요.","친구 나가 잘못 말했어요."],"asset":{"type":"passage","lines":["큰곰자리 — 꼬리 부분에 일곱 개의 별 ㉠이 있어요.","작은곰자리 — 꼬리 부분에 ㉡이 있어요.","카시오페이아자리 — 북쪽 밤하늘의 대표적인 별자리예요.","천체 관측 프로그램 — 이 밖에도 여러 별자리가 보였어요."],"title":"북극성 주변 관찰 기록"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_sci_u1_L05_challenge#4','sci',4,2,'u1','L05','g4_2_sci_u1_L05_challenge','lesson_challenge','SC4-2-u1-C16',3,'mc','auto','만화 속 친구 다가 「목성은 별처럼 빛나지만 별은 아니야.」라고 한 까닭은 무엇인가요?',ARRAY['SC4-2-u1-X32','SC4-2-u1-X33']::text[],false,'{"seq":4,"concept":"SC4-2-u1-C16","difficulty":3,"kind":"mc","stem":"만화 속 친구 다가 「목성은 별처럼 빛나지만 별은 아니야.」라고 한 까닭은 무엇인가요?","options":[{"t":"목성은 행성이라서 스스로 빛을 내지 않기 때문에","correct":true},{"t":"목성은 낮에만 보이기 때문에","mis":"SC4-2-u1-X32"},{"t":"목성은 반짝이지 않기 때문에","mis":"SC4-2-u1-X32"},{"t":"목성이 태양계의 유일한 별이기 때문에","mis":"SC4-2-u1-X33"}],"explanation":["별의 뜻을 떠올려요.","스스로 빛을 낼까요?","첫 번째예요."],"asset":{"type":"speech","turns":[{"who":"친구 가","text":"저기 북극성이 보여. 밤하늘에서 위치가 거의 변하지 않아."},{"who":"친구 나","text":"그래서 방향을 찾는 데 이용하기도 해."},{"who":"친구 다","text":"저기 목성도 보인다. 별처럼 빛나지만 별은 아니야."},{"who":"친구 라","text":"목성은 스스로 빛을 내지 않아."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_sci_u1_L05_challenge#5','sci',4,2,'u1','L05','g4_2_sci_u1_L05_challenge','lesson_challenge','SC4-2-u1-C18',3,'mc','auto','밤에 방향을 확인할 도구가 없을 때 방향을 찾는 방법으로 알맞은 것은 무엇인가요?',ARRAY['SC4-2-u1-X32','SC4-2-u1-X38']::text[],false,'{"seq":5,"concept":"SC4-2-u1-C18","difficulty":3,"kind":"mc","stem":"밤에 방향을 확인할 도구가 없을 때 방향을 찾는 방법으로 알맞은 것은 무엇인가요?","options":[{"t":"밤하늘에서 북극성을 찾으면, 북극성이 있는 쪽이 북쪽이다","correct":true},{"t":"목성을 찾으면 목성이 있는 쪽이 북쪽이다","mis":"SC4-2-u1-X32"},{"t":"북극성을 찾으면 북극성이 있는 쪽이 남쪽이다","mis":"SC4-2-u1-X38"},{"t":"북극성은 밤마다 자리가 크게 달라져 쓸 수 없다","mis":"SC4-2-u1-X38"}],"explanation":["위치가 거의 변하지 않는 별이에요.","북쪽 부근에 있어요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_sci_u1_L05_challenge#6','sci',4,2,'u1','L05','g4_2_sci_u1_L05_challenge','lesson_challenge','SC4-2-u1-C17',3,'mc','auto','별자리에 대한 설명으로 알맞은 것은 무엇인가요?',ARRAY['SC4-2-u1-X34']::text[],false,'{"seq":6,"concept":"SC4-2-u1-C17","difficulty":3,"kind":"mc","stem":"별자리에 대한 설명으로 알맞은 것은 무엇인가요?","options":[{"t":"천문학자들이 공통으로 쓸 별자리의 이름과 모양을 정했다","correct":true},{"t":"별자리는 하늘에 저절로 그려진 그림이다","mis":"SC4-2-u1-X34"},{"t":"별자리는 행성을 연결해 이름을 붙인 것이다","mis":"SC4-2-u1-X34"},{"t":"옛날에도 모든 지역의 별자리가 똑같았다","mis":"SC4-2-u1-X34"}],"explanation":["옛날과 지금을 떠올려요.","공통으로 정했어요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_sci_u1_L05_challenge#7','sci',4,2,'u1','L05','g4_2_sci_u1_L05_challenge','lesson_challenge','SC4-2-u1-C19',3,'mc','auto','밤하늘 그림에 별자리 투명 필름을 대어 별자리를 찾을 때 알맞은 방법은 무엇인가요?',ARRAY['SC4-2-u1-X39','SC4-2-u1-X37']::text[],false,'{"seq":7,"concept":"SC4-2-u1-C19","difficulty":3,"kind":"mc","stem":"밤하늘 그림에 별자리 투명 필름을 대어 별자리를 찾을 때 알맞은 방법은 무엇인가요?","options":[{"t":"필름을 돌려 보면서 밤하늘 그림과 일치하는 별자리를 찾는다","correct":true},{"t":"필름을 대지 않고 이름만 외운다","mis":"SC4-2-u1-X39"},{"t":"필름 한 장만 대고 다 찾았다고 한다","mis":"SC4-2-u1-X37"},{"t":"필름을 그림 위에 아무렇게나 붙여 둔다","mis":"SC4-2-u1-X39"}],"explanation":["필름을 대어 봐요.","돌려 보며 맞춰요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_sci_u1_L05_challenge#8','sci',4,2,'u1','L05','g4_2_sci_u1_L05_challenge','lesson_challenge','SC4-2-u1-C18',4,'mc','auto','북극성 주변 관찰 기록을 보고 바르게 정리한 것은 무엇인가요?',ARRAY['SC4-2-u1-X36','SC4-2-u1-X35','SC4-2-u1-X38']::text[],false,'{"seq":8,"concept":"SC4-2-u1-C18","difficulty":4,"kind":"mc","stem":"북극성 주변 관찰 기록을 보고 바르게 정리한 것은 무엇인가요?","options":[{"t":"㉠은 큰곰자리에, ㉡은 작은곰자리에 있고, 북극성 주변에는 이 밖에도 여러 별자리가 있다","correct":true},{"t":"㉠과 ㉡은 모두 작은곰자리에 있다","mis":"SC4-2-u1-X36"},{"t":"㉡은 큰곰자리에 있고, 별자리는 세 개뿐이다","mis":"SC4-2-u1-X35"},{"t":"㉠은 작은곰자리에 있고, ㉡은 남쪽 하늘에서 보인다","mis":"SC4-2-u1-X38"}],"explanation":["㉠은 북두칠성, ㉡은 북극성이에요.","넷째 줄도 봐요.","첫 번째예요."],"asset":{"type":"passage","lines":["큰곰자리 — 꼬리 부분에 일곱 개의 별 ㉠이 있어요.","작은곰자리 — 꼬리 부분에 ㉡이 있어요.","카시오페이아자리 — 북쪽 밤하늘의 대표적인 별자리예요.","천체 관측 프로그램 — 이 밖에도 여러 별자리가 보였어요."],"title":"북극성 주변 관찰 기록"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_sci_u1_L05_challenge#9','sci',4,2,'u1','L05','g4_2_sci_u1_L05_challenge','lesson_challenge','SC4-2-u1-C16',4,'mc','auto','친구가 「밤하늘에서 반짝이는 것은 모두 별이야.」라고 했어요. 바르게 고친 것은 무엇인가요?',ARRAY['SC4-2-u1-X32','SC4-2-u1-X33']::text[],false,'{"seq":9,"concept":"SC4-2-u1-C16","difficulty":4,"kind":"mc","stem":"친구가 「밤하늘에서 반짝이는 것은 모두 별이야.」라고 했어요. 바르게 고친 것은 무엇인가요?","options":[{"t":"「목성처럼 빛나 보여도 스스로 빛을 내지 않는 행성도 있어. 스스로 빛을 내는 천체가 별이야.」","correct":true},{"t":"「맞아, 반짝이면 모두 스스로 빛을 내.」","mis":"SC4-2-u1-X32"},{"t":"「태양은 별이 아니야.」","mis":"SC4-2-u1-X33"},{"t":"「별은 스스로 빛을 내지 않아.」","mis":"SC4-2-u1-X32"}],"explanation":["목성을 떠올려요.","행성도 빛나 보여요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_sci_u1_L05_challenge#10','sci',4,2,'u1','L05','g4_2_sci_u1_L05_challenge','lesson_challenge','SC4-2-u1-C16',4,'essay','teacher','별과 행성의 다른 점을 쓰고, 북극성 주변에서 볼 수 있는 별자리 두 가지와 북극성의 특징을 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"SC4-2-u1-C16","difficulty":4,"kind":"essay","stem":"별과 행성의 다른 점을 쓰고, 북극성 주변에서 볼 수 있는 별자리 두 가지와 북극성의 특징을 쓰세요.","answer_guide":{"answer":"예: 별은 스스로 빛을 내는 천체이고, 행성은 별과 달리 스스로 빛을 내지 않는다. 북극성 주변에서는 큰곰자리와 카시오페이아자리를 볼 수 있다. 북극성은 작은곰자리의 꼬리 부분에 있고 정확한 북쪽 부근에서 위치가 거의 변하지 않는다.","scoring_points":["별과 행성의 다른 점을 썼는가","북극성 주변의 별자리 두 가지를 썼는가","북극성의 특징을 썼는가"]},"explanation":["다른 점을 써요.","별자리를 써요.","북극성을 써요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_sci_u1_L06_basic#1','sci',4,2,'u1','L06','g4_2_sci_u1_L06_basic','lesson_basic','SC4-2-u1-C21',1,'mc','auto','홍보 자료를 만들 때 가장 먼저 할 일은 무엇인가요?',ARRAY['SC4-2-u1-X41']::text[],false,'{"seq":1,"concept":"SC4-2-u1-C21","difficulty":1,"kind":"mc","stem":"홍보 자료를 만들 때 가장 먼저 할 일은 무엇인가요?","options":[{"t":"홍보할 천체를 정하고 홍보 계획을 세운다","correct":true},{"t":"꾸민 내용을 도화지에 붙인다","mis":"SC4-2-u1-X41"},{"t":"반 친구들에게 홍보 자료를 소개한다","mis":"SC4-2-u1-X41"},{"t":"다른 모둠의 잘한 점을 이야기한다","mis":"SC4-2-u1-X41"}],"explanation":["계획부터 세워요.","무엇을 홍보할지 정해요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_sci_u1_L06_basic#2','sci',4,2,'u1','L06','g4_2_sci_u1_L06_basic','lesson_basic','SC4-2-u1-C21',1,'sa','auto','어느 모둠의 홍보 계획표에서 이 모둠이 홍보할 천체를 한 글자로 쓰세요.','{}'::text[],false,'{"seq":2,"concept":"SC4-2-u1-C21","difficulty":1,"kind":"sa","stem":"어느 모둠의 홍보 계획표에서 이 모둠이 홍보할 천체를 한 글자로 쓰세요.","answer":["달"],"explanation":["첫 줄을 읽어요.","충돌 구덩이가 있어요.","달이에요."],"asset":{"type":"passage","lines":["홍보할 천체 — 달","특징 — 둥근 공 모양, 단단한 땅, 울퉁불퉁한 면과 충돌 구덩이","홍보 내용 — 달 표면 산책하기, 충돌 구덩이 탐험하기","역할 — 모둠원이 각자 한 개의 활동을 맡아요."],"title":"어느 모둠의 홍보 계획표"},"mis":"SC4-2-u1-X41"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_sci_u1_L06_basic#3','sci',4,2,'u1','L06','g4_2_sci_u1_L06_basic','lesson_basic','SC4-2-u1-C21',1,'ox','auto','칼이나 가위를 사용할 때는 다치지 않도록 조심해요.',ARRAY['SC4-2-u1-X41']::text[],false,'{"seq":3,"concept":"SC4-2-u1-C21","difficulty":1,"kind":"ox","stem":"칼이나 가위를 사용할 때는 다치지 않도록 조심해요.","answer":"O","reason_options":[{"t":"종이를 자르다가 손을 다칠 수 있기 때문에","correct":true},{"t":"빨리 자르는 것이 더 중요하기 때문에","mis":"SC4-2-u1-X41"}],"mis":"SC4-2-u1-X41","explanation":["안전을 떠올려요.","날카로워요.","그래서 O예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_sci_u1_L06_basic#4','sci',4,2,'u1','L06','g4_2_sci_u1_L06_basic','lesson_basic','SC4-2-u1-C20',1,'mc','auto','일반인이 우주선을 타고 우주에 갔다가 다시 돌아온 일은 무엇이라고 할 수 있나요?',ARRAY['SC4-2-u1-X40']::text[],false,'{"seq":4,"concept":"SC4-2-u1-C20","difficulty":1,"kind":"mc","stem":"일반인이 우주선을 타고 우주에 갔다가 다시 돌아온 일은 무엇이라고 할 수 있나요?","options":[{"t":"우주여행","correct":true},{"t":"우주여행이 아닌 일","mis":"SC4-2-u1-X40"},{"t":"땅 위의 여행","mis":"SC4-2-u1-X40"},{"t":"바닷속 여행","mis":"SC4-2-u1-X40"}],"explanation":["우주에 다녀왔어요.","다른 천체가 아니어도 돼요.","우주여행이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_sci_u1_L06_basic#5','sci',4,2,'u1','L06','g4_2_sci_u1_L06_basic','lesson_basic','SC4-2-u1-C22',2,'mc','auto','홍보 자료를 만들 때 가장 중요한 것은 무엇인가요?',ARRAY['SC4-2-u1-X42','SC4-2-u1-X43']::text[],false,'{"seq":5,"concept":"SC4-2-u1-C22","difficulty":2,"kind":"mc","stem":"홍보 자료를 만들 때 가장 중요한 것은 무엇인가요?","options":[{"t":"태양계 천체의 특징이 잘 드러나게 만든다","correct":true},{"t":"예쁘게 꾸미기만 한다","mis":"SC4-2-u1-X42"},{"t":"다른 모둠보다 빨리 만든다","mis":"SC4-2-u1-X43"},{"t":"빈 곳이 없도록 글자를 꽉 채운다","mis":"SC4-2-u1-X42"}],"explanation":["살펴보는 기준을 떠올려요.","특징이 먼저예요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_sci_u1_L06_basic#6','sci',4,2,'u1','L06','g4_2_sci_u1_L06_basic','lesson_basic','SC4-2-u1-C22',2,'mc','auto','다른 모둠이 발표할 때 알맞은 태도는 무엇인가요?',ARRAY['SC4-2-u1-X43']::text[],false,'{"seq":6,"concept":"SC4-2-u1-C22","difficulty":2,"kind":"mc","stem":"다른 모둠이 발표할 때 알맞은 태도는 무엇인가요?","options":[{"t":"경청하고 잘한 점을 위주로 찾는다","correct":true},{"t":"발표를 듣고 비난한다","mis":"SC4-2-u1-X43"},{"t":"우리 모둠 자료만 본다","mis":"SC4-2-u1-X43"},{"t":"발표 중에 끼어들어 따진다","mis":"SC4-2-u1-X43"}],"explanation":["발표를 들어요.","잘한 점을 찾아요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_sci_u1_L06_basic#7','sci',4,2,'u1','L06','g4_2_sci_u1_L06_basic','lesson_basic','SC4-2-u1-C21',2,'match','auto','홍보 계획표의 칸과 알맞은 내용을 이으세요.','{}'::text[],false,'{"seq":7,"concept":"SC4-2-u1-C21","difficulty":2,"kind":"match","stem":"홍보 계획표의 칸과 알맞은 내용을 이으세요.","pairs":[{"l":"홍보할 천체","r":"달"},{"l":"선택한 천체의 특징","r":"충돌 구덩이가 많다"},{"l":"홍보 내용","r":"달 표면 산책하기"}],"mis":"SC4-2-u1-X41","explanation":["계획표를 읽어요.","특징과 내용을 구별해요.","천체-달, 특징-충돌 구덩이, 내용-산책이에요."],"asset":{"type":"passage","lines":["홍보할 천체 — 달","특징 — 둥근 공 모양, 단단한 땅, 울퉁불퉁한 면과 충돌 구덩이","홍보 내용 — 달 표면 산책하기, 충돌 구덩이 탐험하기","역할 — 모둠원이 각자 한 개의 활동을 맡아요."],"title":"어느 모둠의 홍보 계획표"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_sci_u1_L06_basic#8','sci',4,2,'u1','L06','g4_2_sci_u1_L06_basic','lesson_basic','SC4-2-u1-C23',2,'ox','auto','「같은 모양의 달을 보려면 약 15일이 걸린다.」가 쓰인 풍선은 가져갈 수 있어요.',ARRAY['SC4-2-u1-X44']::text[],false,'{"seq":8,"concept":"SC4-2-u1-C23","difficulty":2,"kind":"ox","stem":"「같은 모양의 달을 보려면 약 15일이 걸린다.」가 쓰인 풍선은 가져갈 수 있어요.","answer":"X","reason_options":[{"t":"같은 모양의 달을 다시 보려면 약 30일이 걸리기 때문에","correct":true},{"t":"달의 모양은 보름마다 같아지기 때문에","mis":"SC4-2-u1-X44"}],"mis":"SC4-2-u1-X44","explanation":["달의 모양 변화를 떠올려요.","약 30일이에요.","그래서 X예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_sci_u1_L06_basic#9','sci',4,2,'u1','L06','g4_2_sci_u1_L06_basic','lesson_basic','SC4-2-u1-C23',2,'mc','auto','풍선에 쓰인 내용에서 옳은 문장은 무엇인가요?',ARRAY['SC4-2-u1-X44']::text[],false,'{"seq":9,"concept":"SC4-2-u1-C23","difficulty":2,"kind":"mc","stem":"풍선에 쓰인 내용에서 옳은 문장은 무엇인가요?","options":[{"t":"④","correct":true},{"t":"①","mis":"SC4-2-u1-X44"},{"t":"③","mis":"SC4-2-u1-X44"},{"t":"⑤","mis":"SC4-2-u1-X44"}],"explanation":["하나씩 확인해요.","태양의 자리예요.","④예요."],"asset":{"type":"passage","lines":["① 달의 바다는 달 표면의 밝은 부분이다.","② 달의 모양은 매일 조금씩 달라진다.","③ 같은 모양의 달을 보려면 약 15일이 걸린다.","④ 태양은 태양계의 중심에 있다.","⑤ 화성은 크고 뚜렷한 고리가 있다.","⑥ 별은 스스로 빛을 낸다.","⑦ 북극성은 북쪽 하늘에서 볼 수 있다.","⑧ 북두칠성은 작은곰자리의 꼬리 부분에 있다."],"title":"풍선에 쓰인 내용"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_sci_u1_L06_basic#10','sci',4,2,'u1','L06','g4_2_sci_u1_L06_basic','lesson_basic','SC4-2-u1-C20',3,'mc','auto','우주여행에 대해 바르게 말한 것은 무엇인가요?',ARRAY['SC4-2-u1-X40']::text[],false,'{"seq":10,"concept":"SC4-2-u1-C20","difficulty":3,"kind":"mc","stem":"우주여행에 대해 바르게 말한 것은 무엇인가요?","options":[{"t":"관광객을 태운 우주선이 우주에 갔다가 돌아오는 것도 우주여행이다","correct":true},{"t":"지구 밖의 다른 천체로 가는 것만 우주여행이다","mis":"SC4-2-u1-X40"},{"t":"우주 비행사가 아니면 우주에 갈 수 없다","mis":"SC4-2-u1-X40"},{"t":"우주선이 다른 천체를 향하지 않으면 우주여행이 아니다","mis":"SC4-2-u1-X40"}],"explanation":["우주는 공간이에요.","다녀오는 것도 돼요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_sci_u1_L06_challenge#1','sci',4,2,'u1','L06','g4_2_sci_u1_L06_challenge','lesson_challenge','SC4-2-u1-C21',2,'mc','auto','홍보 자료를 만드는 차례로 알맞은 것은 무엇인가요?',ARRAY['SC4-2-u1-X41']::text[],false,'{"seq":1,"concept":"SC4-2-u1-C21","difficulty":2,"kind":"mc","stem":"홍보 자료를 만드는 차례로 알맞은 것은 무엇인가요?","options":[{"t":"계획 세우기 → 도화지 접기 → 역할을 나누어 꾸미기 → 도화지에 붙여 완성하기","correct":true},{"t":"꾸미기 → 계획 세우기 → 도화지 접기 → 붙이기","mis":"SC4-2-u1-X41"},{"t":"붙이기 → 꾸미기 → 계획 세우기 → 도화지 접기","mis":"SC4-2-u1-X41"},{"t":"도화지 접기 → 붙이기 → 꾸미기 → 계획 세우기","mis":"SC4-2-u1-X41"}],"explanation":["계획이 먼저예요.","붙이기가 마지막이에요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_sci_u1_L06_challenge#2','sci',4,2,'u1','L06','g4_2_sci_u1_L06_challenge','lesson_challenge','SC4-2-u1-C22',2,'ox','auto','가장 예쁘게 꾸민 모둠이 가장 좋은 홍보 자료를 만든 거예요.',ARRAY['SC4-2-u1-X42']::text[],false,'{"seq":2,"concept":"SC4-2-u1-C22","difficulty":2,"kind":"ox","stem":"가장 예쁘게 꾸민 모둠이 가장 좋은 홍보 자료를 만든 거예요.","answer":"X","reason_options":[{"t":"천체의 특징을 잘 나타내고 홍보 내용을 잘 표현했는지가 중요하기 때문에","correct":true},{"t":"색을 많이 칠할수록 천체의 특징이 잘 드러나기 때문에","mis":"SC4-2-u1-X42"}],"mis":"SC4-2-u1-X42","explanation":["살펴보는 기준을 떠올려요.","꾸밈은 기준이 아니에요.","그래서 X예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_sci_u1_L06_challenge#3','sci',4,2,'u1','L06','g4_2_sci_u1_L06_challenge','lesson_challenge','SC4-2-u1-C22',3,'error','auto','홍보 자료를 살펴본 뒤 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SC4-2-u1-X43','SC4-2-u1-X42']::text[],false,'{"seq":3,"concept":"SC4-2-u1-C22","difficulty":3,"kind":"error","stem":"홍보 자료를 살펴본 뒤 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"친구 다 — 「다른 모둠 자료를 그대로 따라 만들면 돼.」","correct":true,"mis_target":"SC4-2-u1-X43"},{"t":"친구 가 — 「천체의 특징을 잘 나타냈는지 보자.」","mis":"SC4-2-u1-X42"},{"t":"친구 나 — 「다른 모둠의 잘한 점을 보고 우리 모둠의 보완할 점을 찾자.」","mis":"SC4-2-u1-X43"}],"explanation":["보완하는 방법을 떠올려요.","따라 하기는 아니에요.","친구 다가 잘못 말했어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_sci_u1_L06_challenge#4','sci',4,2,'u1','L06','g4_2_sci_u1_L06_challenge','lesson_challenge','SC4-2-u1-C22',3,'mc','auto','달을 홍보한 모둠이 살펴보는 기준 ①에 맞게 자료를 보완하려고 해요. 가장 알맞은 것은 무엇인가요?',ARRAY['SC4-2-u1-X42','SC4-2-u1-X43']::text[],false,'{"seq":4,"concept":"SC4-2-u1-C22","difficulty":3,"kind":"mc","stem":"달을 홍보한 모둠이 살펴보는 기준 ①에 맞게 자료를 보완하려고 해요. 가장 알맞은 것은 무엇인가요?","options":[{"t":"달은 지구에서 가장 가까운 천체이니 달에서 지구의 모습을 관찰하는 활동을 넣는다","correct":true},{"t":"색을 더 많이 칠해 예쁘게 만든다","mis":"SC4-2-u1-X42"},{"t":"빈 곳이 없도록 글자를 더 채운다","mis":"SC4-2-u1-X42"},{"t":"다른 모둠 자료를 그대로 따라 만든다","mis":"SC4-2-u1-X43"}],"explanation":["기준 ①을 읽어요.","천체의 특징이에요.","첫 번째예요."],"asset":{"type":"passage","lines":["① 태양계 천체의 특징을 잘 나타냈나요?","② 홍보하려는 내용을 잘 표현했나요?","③ 창의적으로 만들었나요?"],"title":"홍보 자료를 살펴보는 기준"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_sci_u1_L06_challenge#5','sci',4,2,'u1','L06','g4_2_sci_u1_L06_challenge','lesson_challenge','SC4-2-u1-C23',3,'mc','auto','풍선에 쓰인 내용에서 옳은 문장끼리 묶은 것은 무엇인가요?',ARRAY['SC4-2-u1-X44']::text[],false,'{"seq":5,"concept":"SC4-2-u1-C23","difficulty":3,"kind":"mc","stem":"풍선에 쓰인 내용에서 옳은 문장끼리 묶은 것은 무엇인가요?","options":[{"t":"②, ④, ⑥, ⑦","correct":true},{"t":"①, ③, ⑤, ⑧","mis":"SC4-2-u1-X44"},{"t":"②, ③, ⑥, ⑧","mis":"SC4-2-u1-X44"},{"t":"①, ④, ⑤, ⑦","mis":"SC4-2-u1-X44"}],"explanation":["배운 내용으로 확인해요.","옳은 것은 넷이에요.","②, ④, ⑥, ⑦이에요."],"asset":{"type":"passage","lines":["① 달의 바다는 달 표면의 밝은 부분이다.","② 달의 모양은 매일 조금씩 달라진다.","③ 같은 모양의 달을 보려면 약 15일이 걸린다.","④ 태양은 태양계의 중심에 있다.","⑤ 화성은 크고 뚜렷한 고리가 있다.","⑥ 별은 스스로 빛을 낸다.","⑦ 북극성은 북쪽 하늘에서 볼 수 있다.","⑧ 북두칠성은 작은곰자리의 꼬리 부분에 있다."],"title":"풍선에 쓰인 내용"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_sci_u1_L06_challenge#6','sci',4,2,'u1','L06','g4_2_sci_u1_L06_challenge','lesson_challenge','SC4-2-u1-C23',3,'mc','auto','풍선 ⑤를 바르게 고친 문장은 무엇인가요?',ARRAY['SC4-2-u1-X29','SC4-2-u1-X28']::text[],false,'{"seq":6,"concept":"SC4-2-u1-C23","difficulty":3,"kind":"mc","stem":"풍선 ⑤를 바르게 고친 문장은 무엇인가요?","options":[{"t":"토성은 크고 뚜렷한 고리가 있다","correct":true},{"t":"화성은 희미한 고리만 있다","mis":"SC4-2-u1-X29"},{"t":"수성은 크고 뚜렷한 고리가 있다","mis":"SC4-2-u1-X29"},{"t":"고리가 있는 행성은 하나도 없다","mis":"SC4-2-u1-X28"}],"explanation":["크고 뚜렷한 고리를 떠올려요.","연한 노란색 행성이에요.","토성이에요."],"asset":{"type":"passage","lines":["① 달의 바다는 달 표면의 밝은 부분이다.","② 달의 모양은 매일 조금씩 달라진다.","③ 같은 모양의 달을 보려면 약 15일이 걸린다.","④ 태양은 태양계의 중심에 있다.","⑤ 화성은 크고 뚜렷한 고리가 있다.","⑥ 별은 스스로 빛을 낸다.","⑦ 북극성은 북쪽 하늘에서 볼 수 있다.","⑧ 북두칠성은 작은곰자리의 꼬리 부분에 있다."],"title":"풍선에 쓰인 내용"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_sci_u1_L06_challenge#7','sci',4,2,'u1','L06','g4_2_sci_u1_L06_challenge','lesson_challenge','SC4-2-u1-C21',3,'mc','auto','태양을 홍보하는 모둠이 홍보 내용으로 넣기에 가장 알맞은 것은 무엇인가요?',ARRAY['SC4-2-u1-X42','SC4-2-u1-X43']::text[],false,'{"seq":7,"concept":"SC4-2-u1-C21","difficulty":3,"kind":"mc","stem":"태양을 홍보하는 모둠이 홍보 내용으로 넣기에 가장 알맞은 것은 무엇인가요?","options":[{"t":"태양이 태양계 중심에 있다는 특징을 살려 태양에서 여러 행성을 바라보는 활동","correct":true},{"t":"특징과 상관없이 좋아하는 놀이공원 그림 붙이기","mis":"SC4-2-u1-X42"},{"t":"빈칸 없이 아무 글자나 가득 쓰기","mis":"SC4-2-u1-X42"},{"t":"다른 모둠의 달 여행 내용을 그대로 옮기기","mis":"SC4-2-u1-X43"}],"explanation":["태양의 특징을 떠올려요.","중심에 있어요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_sci_u1_L06_challenge#8','sci',4,2,'u1','L06','g4_2_sci_u1_L06_challenge','lesson_challenge','SC4-2-u1-C23',4,'mc','auto','풍선 ①과 ⑧을 바르게 고친 것끼리 묶은 것은 무엇인가요?',ARRAY['SC4-2-u1-X11','SC4-2-u1-X35','SC4-2-u1-X12']::text[],false,'{"seq":8,"concept":"SC4-2-u1-C23","difficulty":4,"kind":"mc","stem":"풍선 ①과 ⑧을 바르게 고친 것끼리 묶은 것은 무엇인가요?","options":[{"t":"① 달의 바다는 달 표면의 어두운 부분이다 · ⑧ 북두칠성은 큰곰자리의 꼬리 부분에 있다","correct":true},{"t":"① 달의 바다에는 물이 있다 · ⑧ 북두칠성은 큰곰자리에 있다","mis":"SC4-2-u1-X11"},{"t":"① 달의 바다는 어두운 부분이다 · ⑧ 북극성은 큰곰자리에 있다","mis":"SC4-2-u1-X35"},{"t":"① 달의 바다는 밝은 부분이다 · ⑧ 북두칠성은 북쪽 하늘에 없다","mis":"SC4-2-u1-X12"}],"explanation":["두 풍선을 읽어요.","어두운 곳 · 큰곰자리예요.","첫 번째예요."],"asset":{"type":"passage","lines":["① 달의 바다는 달 표면의 밝은 부분이다.","② 달의 모양은 매일 조금씩 달라진다.","③ 같은 모양의 달을 보려면 약 15일이 걸린다.","④ 태양은 태양계의 중심에 있다.","⑤ 화성은 크고 뚜렷한 고리가 있다.","⑥ 별은 스스로 빛을 낸다.","⑦ 북극성은 북쪽 하늘에서 볼 수 있다.","⑧ 북두칠성은 작은곰자리의 꼬리 부분에 있다."],"title":"풍선에 쓰인 내용"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_sci_u1_L06_challenge#9','sci',4,2,'u1','L06','g4_2_sci_u1_L06_challenge','lesson_challenge','SC4-2-u1-C20',4,'mc','auto','친구가 「우리는 다른 천체에 내려 보지 못하니 우주여행은 꿈도 못 꿔.」라고 했어요. 가장 알맞게 답한 것은 무엇인가요?',ARRAY['SC4-2-u1-X40']::text[],false,'{"seq":9,"concept":"SC4-2-u1-C20","difficulty":4,"kind":"mc","stem":"친구가 「우리는 다른 천체에 내려 보지 못하니 우주여행은 꿈도 못 꿔.」라고 했어요. 가장 알맞게 답한 것은 무엇인가요?","options":[{"t":"「일반인이 우주선을 타고 우주에 갔다가 돌아온 것도 우주여행이야. 이미 우주를 체험한 사람들이 있어.」","correct":true},{"t":"「맞아, 다른 천체에 가야만 우주여행이야.」","mis":"SC4-2-u1-X40"},{"t":"「우주여행은 우주 비행사만 할 수 있어.」","mis":"SC4-2-u1-X40"},{"t":"「우주선을 타도 우주에는 갈 수 없어.」","mis":"SC4-2-u1-X40"}],"explanation":["우주여행의 뜻을 떠올려요.","다녀오는 것도 돼요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_sci_u1_L06_challenge#10','sci',4,2,'u1','L06','g4_2_sci_u1_L06_challenge','lesson_challenge','SC4-2-u1-C21',4,'essay','teacher','태양계 천체 하나를 골라 그 천체의 특징 두 가지를 쓰고, 그 특징을 살린 여행 홍보 내용을 한 가지 쓰세요. 그리고 다른 모둠의 홍보 자료를 볼 때 지킬 점을 한 가지 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"SC4-2-u1-C21","difficulty":4,"kind":"essay","stem":"태양계 천체 하나를 골라 그 천체의 특징 두 가지를 쓰고, 그 특징을 살린 여행 홍보 내용을 한 가지 쓰세요. 그리고 다른 모둠의 홍보 자료를 볼 때 지킬 점을 한 가지 쓰세요.","answer_guide":{"answer":"예: 토성을 고른다. 토성은 연한 노란색이고 크고 뚜렷한 고리가 있다. 「토성의 고리를 가까이에서 바라보는 여행」을 홍보한다. 다른 모둠이 발표할 때에는 경청하고 비난하지 않으며 잘한 점 위주로 찾는다.","scoring_points":["천체의 특징 두 가지를 바르게 썼는가","특징을 살린 홍보 내용을 썼는가","다른 모둠 자료를 볼 때 지킬 점을 썼는가"]},"explanation":["천체를 골라요.","특징을 살려요.","지킬 점을 써요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_sci_u1_L07_basic#1','sci',4,2,'u1','L07','g4_2_sci_u1_L07_basic','lesson_basic','SC4-2-u1-C24',1,'mc','auto','망원경이 없던 때에는 밤하늘을 어떻게 관찰했나요?',ARRAY['SC4-2-u1-X45','SC4-2-u1-X47']::text[],false,'{"seq":1,"concept":"SC4-2-u1-C24","difficulty":1,"kind":"mc","stem":"망원경이 없던 때에는 밤하늘을 어떻게 관찰했나요?","options":[{"t":"맨눈으로 관찰했다","correct":true},{"t":"지구 밖으로 보낸 망원경으로 관찰했다","mis":"SC4-2-u1-X45"},{"t":"달 탐사선을 보내 관찰했다","mis":"SC4-2-u1-X47"},{"t":"사진으로만 관찰했다","mis":"SC4-2-u1-X45"}],"explanation":["망원경이 없었어요.","눈으로 보았어요.","맨눈이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_sci_u1_L07_basic#2','sci',4,2,'u1','L07','g4_2_sci_u1_L07_basic','lesson_basic','SC4-2-u1-C24',1,'sa','auto','망원경이 바꾼 밤하늘 관찰에서 ㉠에 알맞은 행성의 이름을 쓰세요.','{}'::text[],false,'{"seq":2,"concept":"SC4-2-u1-C24","difficulty":1,"kind":"sa","stem":"망원경이 바꾼 밤하늘 관찰에서 ㉠에 알맞은 행성의 이름을 쓰세요.","answer":["천왕성"],"explanation":["셋째 줄을 읽어요.","해왕성과 함께 발견했어요.","천왕성이에요."],"asset":{"type":"passage","lines":["없던 때 — 맨눈으로 보아 행성의 모습을 자세히 알기 어려웠어요.","발명된 뒤 — 달의 표면이 울퉁불퉁하다는 것을 알아냈어요.","발명된 뒤 — 맨눈으로 보기 어려운 ㉠과 해왕성을 발견했어요.","오늘날 — 지구 밖으로 보낸 망원경이 날씨에 상관없이 우주를 관찰해요."],"title":"망원경이 바꾼 밤하늘 관찰"},"mis":"SC4-2-u1-X45"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_sci_u1_L07_basic#3','sci',4,2,'u1','L07','g4_2_sci_u1_L07_basic','lesson_basic','SC4-2-u1-C25',1,'ox','auto','지구 밖으로 보낸 망원경은 날씨에 상관없이 우주를 관찰할 수 있어요.',ARRAY['SC4-2-u1-X46']::text[],false,'{"seq":3,"concept":"SC4-2-u1-C25","difficulty":1,"kind":"ox","stem":"지구 밖으로 보낸 망원경은 날씨에 상관없이 우주를 관찰할 수 있어요.","answer":"O","reason_options":[{"t":"지구 밖에 있어 날씨의 영향을 받지 않기 때문에","correct":true},{"t":"지구 밖 망원경도 맑은 날에만 쓸 수 있기 때문에","mis":"SC4-2-u1-X46"}],"mis":"SC4-2-u1-X46","explanation":["넷째 줄을 떠올려요.","날씨에 상관없어요.","그래서 O예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_sci_u1_L07_basic#4','sci',4,2,'u1','L07','g4_2_sci_u1_L07_basic','lesson_basic','SC4-2-u1-C26',1,'mc','auto','우리나라 최초의 달 탐사선은 무엇인가요?',ARRAY['SC4-2-u1-X47']::text[],false,'{"seq":4,"concept":"SC4-2-u1-C26","difficulty":1,"kind":"mc","stem":"우리나라 최초의 달 탐사선은 무엇인가요?","options":[{"t":"다누리호","correct":true},{"t":"제임스 웹 우주 망원경","mis":"SC4-2-u1-X47"},{"t":"지상 망원경","mis":"SC4-2-u1-X47"},{"t":"달 기지","mis":"SC4-2-u1-X47"}],"explanation":["달 탐사선이에요.","우리나라 최초예요.","다누리호예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_sci_u1_L07_basic#5','sci',4,2,'u1','L07','g4_2_sci_u1_L07_basic','lesson_basic','SC4-2-u1-C24',2,'mc','auto','망원경이 발명되면서 알아낸 것은 무엇인가요?',ARRAY['SC4-2-u1-X11','SC4-2-u1-X07','SC4-2-u1-X32']::text[],false,'{"seq":5,"concept":"SC4-2-u1-C24","difficulty":2,"kind":"mc","stem":"망원경이 발명되면서 알아낸 것은 무엇인가요?","options":[{"t":"달의 표면이 울퉁불퉁하다는 것","correct":true},{"t":"달의 바다에 물이 있다는 것","mis":"SC4-2-u1-X11"},{"t":"달이 납작한 원 모양이라는 것","mis":"SC4-2-u1-X07"},{"t":"행성이 스스로 빛을 낸다는 것","mis":"SC4-2-u1-X32"}],"explanation":["둘째 줄을 떠올려요.","달 표면이에요.","울퉁불퉁하다는 것이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_sci_u1_L07_basic#6','sci',4,2,'u1','L07','g4_2_sci_u1_L07_basic','lesson_basic','SC4-2-u1-C25',2,'mc','auto','망원경이 주는 도움으로 알맞은 것은 무엇인가요?',ARRAY['SC4-2-u1-X46']::text[],false,'{"seq":6,"concept":"SC4-2-u1-C25","difficulty":2,"kind":"mc","stem":"망원경이 주는 도움으로 알맞은 것은 무엇인가요?","options":[{"t":"태양계 천체의 모습이나 표면의 상태를 연구한다","correct":true},{"t":"망원경이 있으면 밤하늘을 관찰할 필요가 없다","mis":"SC4-2-u1-X46"},{"t":"망원경으로는 달의 표면을 볼 수 없다","mis":"SC4-2-u1-X46"},{"t":"망원경은 맑은 날 낮에만 쓸 수 있다","mis":"SC4-2-u1-X46"}],"explanation":["망원경이 하는 일을 떠올려요.","자세히 연구해요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_sci_u1_L07_basic#7','sci',4,2,'u1','L07','g4_2_sci_u1_L07_basic','lesson_basic','SC4-2-u1-C26',2,'match','auto','관찰 방법과 알맞은 것을 이으세요.','{}'::text[],false,'{"seq":7,"concept":"SC4-2-u1-C26","difficulty":2,"kind":"match","stem":"관찰 방법과 알맞은 것을 이으세요.","pairs":[{"l":"맨눈으로 관찰","r":"망원경이 없던 때"},{"l":"날씨에 상관없이 우주를 관찰","r":"지구 밖으로 보낸 망원경"},{"l":"달 주위를 돌며 달 표면을 탐사","r":"다누리호"}],"mis":"SC4-2-u1-X47","explanation":["때와 방법을 떠올려요.","다누리호는 탐사선이에요.","맨눈-없던 때, 날씨-지구 밖 망원경, 달 주위-다누리호예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_sci_u1_L07_basic#8','sci',4,2,'u1','L07','g4_2_sci_u1_L07_basic','lesson_basic','SC4-2-u1-C24',2,'ox','auto','망원경이 없던 때에도 태양계 행성의 모습을 자세히 알 수 있었어요.',ARRAY['SC4-2-u1-X45']::text[],false,'{"seq":8,"concept":"SC4-2-u1-C24","difficulty":2,"kind":"ox","stem":"망원경이 없던 때에도 태양계 행성의 모습을 자세히 알 수 있었어요.","answer":"X","reason_options":[{"t":"맨눈으로만 보아서 행성의 모습을 자세히 알기 어려웠기 때문에","correct":true},{"t":"옛날 사람들은 눈이 아주 좋았기 때문에","mis":"SC4-2-u1-X45"}],"mis":"SC4-2-u1-X45","explanation":["첫 줄을 떠올려요.","알기 어려웠어요.","그래서 X예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_sci_u1_L07_basic#9','sci',4,2,'u1','L07','g4_2_sci_u1_L07_basic','lesson_basic','SC4-2-u1-C26',2,'mc','auto','달 탐사선 다누리호가 하는 일로 알맞은 것은 무엇인가요?',ARRAY['SC4-2-u1-X47','SC4-2-u1-X45']::text[],false,'{"seq":9,"concept":"SC4-2-u1-C26","difficulty":2,"kind":"mc","stem":"달 탐사선 다누리호가 하는 일로 알맞은 것은 무엇인가요?","options":[{"t":"달 기지를 만들기 적당한 곳을 찾는다","correct":true},{"t":"지구의 날씨를 알려 준다","mis":"SC4-2-u1-X47"},{"t":"땅 위에서 하늘을 올려다본다","mis":"SC4-2-u1-X47"},{"t":"천왕성을 처음 발견했다","mis":"SC4-2-u1-X45"}],"explanation":["셋째 줄을 읽어요.","달 기지예요.","첫 번째예요."],"asset":{"type":"passage","lines":["우리나라 최초의 달 탐사선이에요.","달 주위를 돌면서 달 표면을 탐사해요.","달 기지를 만들기 적당한 곳을 찾아요."],"title":"달 탐사선 다누리호"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_sci_u1_L07_basic#10','sci',4,2,'u1','L07','g4_2_sci_u1_L07_basic','lesson_basic','SC4-2-u1-C24',3,'mc','auto','망원경이 없던 때에 천왕성과 해왕성을 발견하지 못한 까닭은 무엇인가요?',ARRAY['SC4-2-u1-X45','SC4-2-u1-X26']::text[],false,'{"seq":10,"concept":"SC4-2-u1-C24","difficulty":3,"kind":"mc","stem":"망원경이 없던 때에 천왕성과 해왕성을 발견하지 못한 까닭은 무엇인가요?","options":[{"t":"맨눈으로는 보기 어려운 천체이기 때문에","correct":true},{"t":"그때에는 천왕성과 해왕성이 아직 없었기 때문에","mis":"SC4-2-u1-X45"},{"t":"천왕성과 해왕성은 낮에만 보이기 때문에","mis":"SC4-2-u1-X45"},{"t":"천왕성과 해왕성은 태양계 밖에 있기 때문에","mis":"SC4-2-u1-X26"}],"explanation":["맨눈을 떠올려요.","보기 어려웠어요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
