INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_sci_u1_L07_challenge#2','sci',4,2,'u1','L07','g4_2_sci_u1_L07_challenge','lesson_challenge','SC4-2-u1-C26',2,'ox','auto','다누리호는 땅 위에서 달을 바라보는 망원경이에요.',ARRAY['SC4-2-u1-X47']::text[],false,'{"seq":2,"concept":"SC4-2-u1-C26","difficulty":2,"kind":"ox","stem":"다누리호는 땅 위에서 달을 바라보는 망원경이에요.","answer":"X","reason_options":[{"t":"다누리호는 직접 달에 가서 달 주위를 돌며 관찰하는 달 탐사선이기 때문에","correct":true},{"t":"달을 관찰하는 것은 모두 망원경이기 때문에","mis":"SC4-2-u1-X47"}],"mis":"SC4-2-u1-X47","explanation":["다누리호를 떠올려요.","달 주위를 돌아요.","그래서 X예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_sci_u1_L07_challenge#3','sci',4,2,'u1','L07','g4_2_sci_u1_L07_challenge','lesson_challenge','SC4-2-u1-C25',3,'error','auto','망원경에 대해 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SC4-2-u1-X46','SC4-2-u1-X47']::text[],false,'{"seq":3,"concept":"SC4-2-u1-C25","difficulty":3,"kind":"error","stem":"망원경에 대해 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"친구 가 — 「망원경이 있으니 이제 밤하늘을 관찰할 필요가 없어.」","correct":true,"mis_target":"SC4-2-u1-X46"},{"t":"친구 나 — 「망원경으로 태양계 밖의 천체도 자세히 관찰해.」","mis":"SC4-2-u1-X46"},{"t":"친구 다 — 「망원경으로 관찰하기도 하고 직접 천체에 가기도 해.」","mis":"SC4-2-u1-X47"}],"explanation":["망원경은 관찰을 돕는 도구예요.","관찰은 계속해요.","친구 가가 잘못 말했어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_sci_u1_L07_challenge#4','sci',4,2,'u1','L07','g4_2_sci_u1_L07_challenge','lesson_challenge','SC4-2-u1-C26',3,'mc','auto','「망원경으로 관찰하기」와 「직접 천체에 가서 관찰하기」로 나눌 때, 직접 가서 관찰하는 쪽에 들어가는 것은 무엇인가요?',ARRAY['SC4-2-u1-X47']::text[],false,'{"seq":4,"concept":"SC4-2-u1-C26","difficulty":3,"kind":"mc","stem":"「망원경으로 관찰하기」와 「직접 천체에 가서 관찰하기」로 나눌 때, 직접 가서 관찰하는 쪽에 들어가는 것은 무엇인가요?","options":[{"t":"달 주위를 돌면서 달 표면을 탐사한다","correct":true},{"t":"지상 망원경으로 행성의 모습을 살펴본다","mis":"SC4-2-u1-X47"},{"t":"지구 밖으로 보낸 망원경으로 우주를 관찰한다","mis":"SC4-2-u1-X47"},{"t":"망원경으로 달의 울퉁불퉁한 표면을 본다","mis":"SC4-2-u1-X47"}],"explanation":["직접 가는 것을 찾아요.","다누리호예요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_sci_u1_L07_challenge#5','sci',4,2,'u1','L07','g4_2_sci_u1_L07_challenge','lesson_challenge','SC4-2-u1-C24',3,'mc','auto','망원경이 바꾼 밤하늘 관찰을 바르게 정리한 것은 무엇인가요?',ARRAY['SC4-2-u1-X45','SC4-2-u1-X46']::text[],false,'{"seq":5,"concept":"SC4-2-u1-C24","difficulty":3,"kind":"mc","stem":"망원경이 바꾼 밤하늘 관찰을 바르게 정리한 것은 무엇인가요?","options":[{"t":"맨눈으로는 알기 어렵던 행성의 모습을 망원경으로 더 자세히 알게 되었다","correct":true},{"t":"망원경이 발명된 뒤에도 관찰 방법은 달라지지 않았다","mis":"SC4-2-u1-X45"},{"t":"망원경이 생기면서 천왕성과 해왕성이 새로 생겨났다","mis":"SC4-2-u1-X45"},{"t":"망원경으로는 달을 볼 수 없다","mis":"SC4-2-u1-X46"}],"explanation":["없던 때와 뒤를 견줘요.","자세히 알게 되었어요.","첫 번째예요."],"asset":{"type":"passage","lines":["없던 때 — 맨눈으로 보아 행성의 모습을 자세히 알기 어려웠어요.","발명된 뒤 — 달의 표면이 울퉁불퉁하다는 것을 알아냈어요.","발명된 뒤 — 맨눈으로 보기 어려운 ㉠과 해왕성을 발견했어요.","오늘날 — 지구 밖으로 보낸 망원경이 날씨에 상관없이 우주를 관찰해요."],"title":"망원경이 바꾼 밤하늘 관찰"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_sci_u1_L07_challenge#6','sci',4,2,'u1','L07','g4_2_sci_u1_L07_challenge','lesson_challenge','SC4-2-u1-C25',3,'mc','auto','망원경을 지구 밖으로 보내면 좋은 점으로 가장 알맞은 것은 무엇인가요?',ARRAY['SC4-2-u1-X46','SC4-2-u1-X47']::text[],false,'{"seq":6,"concept":"SC4-2-u1-C25","difficulty":3,"kind":"mc","stem":"망원경을 지구 밖으로 보내면 좋은 점으로 가장 알맞은 것은 무엇인가요?","options":[{"t":"날씨에 상관없이 우주를 관찰할 수 있다","correct":true},{"t":"지구에서는 망원경을 쓸 수 없어서 보낸다","mis":"SC4-2-u1-X46"},{"t":"날씨가 맑은 날에만 쓸 수 있다","mis":"SC4-2-u1-X46"},{"t":"달 기지를 만들 수 있다","mis":"SC4-2-u1-X47"}],"explanation":["넷째 줄을 떠올려요.","날씨예요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_sci_u1_L07_challenge#7','sci',4,2,'u1','L07','g4_2_sci_u1_L07_challenge','lesson_challenge','SC4-2-u1-C26',3,'mc','auto','다누리호를 발사하면서 달라진 점으로 알맞은 것은 무엇인가요?',ARRAY['SC4-2-u1-X21','SC4-2-u1-X46','SC4-2-u1-X11']::text[],false,'{"seq":7,"concept":"SC4-2-u1-C26","difficulty":3,"kind":"mc","stem":"다누리호를 발사하면서 달라진 점으로 알맞은 것은 무엇인가요?","options":[{"t":"우리나라가 예전보다 달의 모습을 더욱 자세히 관찰할 수 있게 되었다","correct":true},{"t":"달의 모양이 실제로 바뀌었다","mis":"SC4-2-u1-X21"},{"t":"망원경이 필요 없어졌다","mis":"SC4-2-u1-X46"},{"t":"달에 바다가 생겼다","mis":"SC4-2-u1-X11"}],"explanation":["탐사선이 하는 일을 떠올려요.","더 자세히 보아요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_sci_u1_L07_challenge#8','sci',4,2,'u1','L07','g4_2_sci_u1_L07_challenge','lesson_challenge','SC4-2-u1-C24',4,'mc','auto','친구가 「옛날 사람들은 천왕성과 해왕성을 몰랐으니 그때는 그 행성이 없었던 거야.」라고 했어요. 바르게 고친 것은 무엇인가요?',ARRAY['SC4-2-u1-X45','SC4-2-u1-X26']::text[],false,'{"seq":8,"concept":"SC4-2-u1-C24","difficulty":4,"kind":"mc","stem":"친구가 「옛날 사람들은 천왕성과 해왕성을 몰랐으니 그때는 그 행성이 없었던 거야.」라고 했어요. 바르게 고친 것은 무엇인가요?","options":[{"t":"「두 행성은 그때도 있었지만 맨눈으로는 보기 어려워서 망원경이 발명된 뒤에야 발견했어.」","correct":true},{"t":"「맞아, 망원경이 두 행성을 만들었어.」","mis":"SC4-2-u1-X45"},{"t":"「두 행성은 태양계 밖에 있어서 그래.」","mis":"SC4-2-u1-X26"},{"t":"「두 행성은 낮에만 보여서 그래.」","mis":"SC4-2-u1-X45"}],"explanation":["몰랐던 까닭을 떠올려요.","맨눈으로는 어려웠어요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_sci_u1_L07_challenge#9','sci',4,2,'u1','L07','g4_2_sci_u1_L07_challenge','lesson_challenge','SC4-2-u1-C25',4,'mc','auto','화성의 붉은색 표면을 자세히 관찰하고 싶은 친구에게 해 줄 말로 가장 알맞은 것은 무엇인가요?',ARRAY['SC4-2-u1-X45','SC4-2-u1-X46','SC4-2-u1-X47']::text[],false,'{"seq":9,"concept":"SC4-2-u1-C25","difficulty":4,"kind":"mc","stem":"화성의 붉은색 표면을 자세히 관찰하고 싶은 친구에게 해 줄 말로 가장 알맞은 것은 무엇인가요?","options":[{"t":"「망원경으로 보면 맨눈보다 행성의 모습을 더 자세히 볼 수 있어.」","correct":true},{"t":"「맨눈으로 보아도 표면까지 자세히 다 보여.」","mis":"SC4-2-u1-X45"},{"t":"「망원경으로는 행성을 볼 수 없어.」","mis":"SC4-2-u1-X46"},{"t":"「다누리호는 땅 위의 망원경이니 그걸로 보면 돼.」","mis":"SC4-2-u1-X47"}],"explanation":["자세히 보려면요?","망원경이 도와요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_sci_u1_L07_challenge#10','sci',4,2,'u1','L07','g4_2_sci_u1_L07_challenge','lesson_challenge','SC4-2-u1-C25',4,'essay','teacher','망원경이 없던 때와 망원경이 발명된 뒤의 밤하늘 관찰을 견주어 쓰고, 오늘날 망원경이 주는 도움 한 가지와 직접 천체에 가서 관찰하는 예를 한 가지 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"SC4-2-u1-C25","difficulty":4,"kind":"essay","stem":"망원경이 없던 때와 망원경이 발명된 뒤의 밤하늘 관찰을 견주어 쓰고, 오늘날 망원경이 주는 도움 한 가지와 직접 천체에 가서 관찰하는 예를 한 가지 쓰세요.","answer_guide":{"answer":"예: 망원경이 없던 때에는 맨눈으로 관찰해 행성의 모습을 자세히 알기 어려웠다. 망원경이 발명되면서 달의 표면이 울퉁불퉁하다는 것을 알아내고 천왕성과 해왕성을 발견했다. 오늘날 지구 밖으로 보낸 망원경은 날씨에 상관없이 우주를 관찰한다. 다누리호는 달 주위를 돌며 달 표면을 탐사한다.","scoring_points":["망원경이 없던 때와 발명된 뒤를 견주었는가","오늘날 망원경이 주는 도움을 썼는가","직접 천체에 가서 관찰하는 예를 썼는가"]},"explanation":["견주어 써요.","도움을 써요.","예를 써요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_sci_u1_review_a#1','sci',4,2,'u1','','g4_2_sci_u1_review_a','unit_review','SC4-2-u1-C2',1,'mc','auto','별빛반 일지 ①에서 모둠원이 종이에 적은 단어는 몇 개씩인가요?',ARRAY['SC4-2-u1-X02']::text[],false,'{"seq":1,"concept":"SC4-2-u1-C2","difficulty":1,"kind":"mc","stem":"별빛반 일지 ①에서 모둠원이 종이에 적은 단어는 몇 개씩인가요?","options":[{"t":"다섯 개","correct":true},{"t":"한 개","mis":"SC4-2-u1-X02"},{"t":"세 개","mis":"SC4-2-u1-X02"},{"t":"열 개","mis":"SC4-2-u1-X02"}],"explanation":["첫 줄을 읽어요.","놀이 방법 ①이에요.","다섯 개예요."],"asset":{"type":"passage","lines":["모둠원이 밤하늘에 대해 들어 본 단어 다섯 개씩을 종이에 적었다.","친구 가 — 「나는 저녁에 반달을 본 적이 있어.」","친구 나도 「반달」 종이가 있어 함께 내려놓으며 말했다.","다짐 — 겨루지 않고 서로의 이야기를 존중하기"],"title":"별빛반 일지 ① 밤하늘 단어 놀이"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_sci_u1_review_a#2','sci',4,2,'u1','','g4_2_sci_u1_review_a','unit_review','SC4-2-u1-C4',1,'mc','auto','별빛반 일지 ②에서 달과 같았던 모형은 어떤 모양인가요?',ARRAY['SC4-2-u1-X07']::text[],false,'{"seq":2,"concept":"SC4-2-u1-C4","difficulty":1,"kind":"mc","stem":"별빛반 일지 ②에서 달과 같았던 모형은 어떤 모양인가요?","options":[{"t":"둥근 공 모양","correct":true},{"t":"납작한 원 모양","mis":"SC4-2-u1-X07"},{"t":"네모 모양","mis":"SC4-2-u1-X07"},{"t":"세모 모양","mis":"SC4-2-u1-X07"}],"explanation":["첫 줄을 읽어요.","옆에서도 둥글어요.","둥근 공 모양이에요."],"asset":{"type":"passage","lines":["모양 — 앞에서 보아도 옆에서 보아도 둥근 모형이 달과 같았다.","표면 — 단단한 땅이고 울퉁불퉁하며 움푹 파인 곳이 많다.","어두운 곳 — 주변보다 어둡고 매끈매끈해 보인다.","조사 — 스마트 기기로 찾은 자료의 출처를 적었다."],"title":"별빛반 일지 ② 달 사진 관찰"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_sci_u1_review_a#3','sci',4,2,'u1','','g4_2_sci_u1_review_a','unit_review','SC4-2-u1-C9',1,'mc','auto','별빛반 일지 ③에서 달을 관찰할 때 누구와 함께했나요?',ARRAY['SC4-2-u1-X16']::text[],false,'{"seq":3,"concept":"SC4-2-u1-C9","difficulty":1,"kind":"mc","stem":"별빛반 일지 ③에서 달을 관찰할 때 누구와 함께했나요?","options":[{"t":"어른","correct":true},{"t":"혼자","mis":"SC4-2-u1-X16"},{"t":"동생과 둘이서","mis":"SC4-2-u1-X16"},{"t":"친구와 둘이서","mis":"SC4-2-u1-X16"}],"explanation":["첫 줄을 읽어요.","안전을 지켰어요.","어른과 함께했어요."],"asset":{"type":"passage","lines":["관찰 — 어른과 함께 저녁에 탁 트인 운동장에서 했다.","기록 — 눈썹 모양 → 반달 → 둥근 달 → 반달 → 눈썹 모양","흐린 날 — 달이 보이지 않아 스마트 기기로 확인했다.","첫날과 같은 모양의 달을 약 30일 뒤에 다시 보았다."],"title":"별빛반 일지 ③ 여러 날 달 관찰"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_sci_u1_review_a#4','sci',4,2,'u1','','g4_2_sci_u1_review_a','unit_review','SC4-2-u1-C14',1,'mc','auto','별빛반 일지 ④에서 ㉡은 어느 행성인가요?',ARRAY['SC4-2-u1-X29']::text[],false,'{"seq":4,"concept":"SC4-2-u1-C14","difficulty":1,"kind":"mc","stem":"별빛반 일지 ④에서 ㉡은 어느 행성인가요?","options":[{"t":"토성","correct":true},{"t":"화성","mis":"SC4-2-u1-X29"},{"t":"목성","mis":"SC4-2-u1-X29"},{"t":"천왕성","mis":"SC4-2-u1-X29"}],"explanation":["㉡을 읽어요.","크고 뚜렷한 고리예요.","토성이에요."],"asset":{"type":"passage","lines":["㉠ 붉은색, 표면에 단단한 땅","㉡ 연한 노란색, 크고 뚜렷한 고리","㉢ 갈색·흰색, 줄무늬와 붉은 점, 희미한 고리","㉣ 청록색, 표면이 기체, 희미한 고리","전시 — 태양 모형을 가운데에 두고 행성 모형을 놓았다."],"title":"별빛반 일지 ④ 행성 모형 전시"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_sci_u1_review_a#5','sci',4,2,'u1','','g4_2_sci_u1_review_a','unit_review','SC4-2-u1-C16',1,'mc','auto','별빛반 일지 ⑤에서 스스로 빛을 내지 않는 것은 무엇인가요?',ARRAY['SC4-2-u1-X32','SC4-2-u1-X33']::text[],false,'{"seq":5,"concept":"SC4-2-u1-C16","difficulty":1,"kind":"mc","stem":"별빛반 일지 ⑤에서 스스로 빛을 내지 않는 것은 무엇인가요?","options":[{"t":"목성","correct":true},{"t":"북극성","mis":"SC4-2-u1-X32"},{"t":"태양","mis":"SC4-2-u1-X33"},{"t":"별","mis":"SC4-2-u1-X32"}],"explanation":["둘째 줄을 읽어요.","행성이에요.","목성이에요."],"asset":{"type":"passage","lines":["북극성 — 스스로 빛을 내는 별이다.","목성 — 별처럼 빛나 보이지만 스스로 빛을 내지 않는다.","태양 — 태양계의 하나뿐인 별이다.","친구 가 — 「별자리는 별들을 연결해 이름을 붙인 것이야.」"],"title":"별빛반 일지 ⑤ 별과 행성"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_sci_u1_review_a#6','sci',4,2,'u1','','g4_2_sci_u1_review_a','unit_review','SC4-2-u1-C18',1,'mc','auto','별빛반 일지 ⑥에서 북극성이 있는 별자리는 무엇인가요?',ARRAY['SC4-2-u1-X35']::text[],false,'{"seq":6,"concept":"SC4-2-u1-C18","difficulty":1,"kind":"mc","stem":"별빛반 일지 ⑥에서 북극성이 있는 별자리는 무엇인가요?","options":[{"t":"작은곰자리","correct":true},{"t":"큰곰자리","mis":"SC4-2-u1-X35"},{"t":"카시오페이아자리","mis":"SC4-2-u1-X35"},{"t":"북두칠성","mis":"SC4-2-u1-X35"}],"explanation":["둘째 줄을 읽어요.","꼬리 부분이에요.","작은곰자리예요."],"asset":{"type":"passage","lines":["필름으로 큰곰자리, 작은곰자리, 카시오페이아자리를 찾았다.","작은곰자리 꼬리 부분의 북극성은 위치가 거의 변하지 않았다.","큰곰자리 꼬리 부분에서 국자 모양의 일곱 별을 보았다.","프로그램을 켜니 북극성 주변에 별자리가 더 있었다."],"title":"별빛반 일지 ⑥ 북쪽 하늘 관찰"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_sci_u1_review_a#7','sci',4,2,'u1','','g4_2_sci_u1_review_a','unit_review','SC4-2-u1-C21',1,'mc','auto','별빛반 일지 ⑦에서 홍보할 천체는 무엇인가요?',ARRAY['SC4-2-u1-X41']::text[],false,'{"seq":7,"concept":"SC4-2-u1-C21","difficulty":1,"kind":"mc","stem":"별빛반 일지 ⑦에서 홍보할 천체는 무엇인가요?","options":[{"t":"태양","correct":true},{"t":"달","mis":"SC4-2-u1-X41"},{"t":"토성","mis":"SC4-2-u1-X41"},{"t":"북극성","mis":"SC4-2-u1-X41"}],"explanation":["첫 줄을 읽어요.","태양계 중심에 있어요.","태양이에요."],"asset":{"type":"passage","lines":["홍보할 천체 — 태양","특징 — 태양계의 중심에 있다.","홍보 내용 — 태양에서 여러 행성을 바라보는 여행","친구 나 — 「색만 더 칠하면 최고의 자료가 될 거야.」"],"title":"별빛반 일지 ⑦ 태양계 여행 홍보 자료"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_sci_u1_review_a#8','sci',4,2,'u1','','g4_2_sci_u1_review_a','unit_review','SC4-2-u1-C24',1,'mc','auto','별빛반 일지 ⑧에서 망원경으로 알아낸 것은 무엇인가요?',ARRAY['SC4-2-u1-X11','SC4-2-u1-X07','SC4-2-u1-X32']::text[],false,'{"seq":8,"concept":"SC4-2-u1-C24","difficulty":1,"kind":"mc","stem":"별빛반 일지 ⑧에서 망원경으로 알아낸 것은 무엇인가요?","options":[{"t":"달의 울퉁불퉁한 표면","correct":true},{"t":"달의 바다에 있는 물","mis":"SC4-2-u1-X11"},{"t":"달이 납작하다는 것","mis":"SC4-2-u1-X07"},{"t":"행성이 스스로 빛을 낸다는 것","mis":"SC4-2-u1-X32"}],"explanation":["둘째 줄을 읽어요.","달 표면이에요.","울퉁불퉁한 표면이에요."],"asset":{"type":"passage","lines":["맨눈으로 보던 때에는 행성의 모습을 자세히 알기 어려웠다.","망원경으로 달의 울퉁불퉁한 표면을 알아냈다.","지구 밖으로 보낸 망원경은 날씨에 상관없이 관찰한다.","다누리호는 달 주위를 돌며 달 표면을 탐사한다."],"title":"별빛반 일지 ⑧ 망원경과 탐사선"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_sci_u1_review_a#9','sci',4,2,'u1','','g4_2_sci_u1_review_a','unit_review','SC4-2-u1-C1',2,'match','auto','밤하늘에서 본 모습이나 들어 본 내용과 알맞은 것을 이으세요.','{}'::text[],false,'{"seq":9,"concept":"SC4-2-u1-C1","difficulty":2,"kind":"match","stem":"밤하늘에서 본 모습이나 들어 본 내용과 알맞은 것을 이으세요.","pairs":[{"l":"둥근 달을 보았어요","r":"달"},{"l":"반짝이는 것을 보았어요","r":"별"},{"l":"지구, 목성 같은 단어를 적었어요","r":"행성"}],"mis":"SC4-2-u1-X01","explanation":["세 가지를 떠올려요.","지구와 목성은 행성이에요.","둥근 달-달, 반짝-별, 지구·목성-행성이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_sci_u1_review_a#10','sci',4,2,'u1','','g4_2_sci_u1_review_a','unit_review','SC4-2-u1-C5',2,'match','auto','달 표면의 모습과 이름을 알맞게 이으세요.','{}'::text[],false,'{"seq":10,"concept":"SC4-2-u1-C5","difficulty":2,"kind":"match","stem":"달 표면의 모습과 이름을 알맞게 이으세요.","pairs":[{"l":"움푹 파인 크고 작은 곳","r":"충돌 구덩이"},{"l":"주변보다 어둡게 보이는 곳","r":"달의 바다"},{"l":"달 표면을 이루는 것","r":"단단한 땅"}],"mis":"SC4-2-u1-X10","explanation":["하나씩 떠올려요.","어두운 곳은 바다예요.","움푹-충돌 구덩이, 어두운 곳-달의 바다, 이루는 것-단단한 땅이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_sci_u1_review_a#11','sci',4,2,'u1','','g4_2_sci_u1_review_a','unit_review','SC4-2-u1-C10',2,'match','auto','관찰한 달의 모양과 이름을 알맞게 이으세요.','{}'::text[],false,'{"seq":11,"concept":"SC4-2-u1-C10","difficulty":2,"kind":"match","stem":"관찰한 달의 모양과 이름을 알맞게 이으세요.","pairs":[{"l":"눈썹 모양으로 가장 먼저 보이는 달","r":"초승달"},{"l":"보름달 다음에 보이는 반달","r":"하현달"},{"l":"하현달 다음에 보이는 눈썹 모양의 달","r":"그믐달"}],"mis":"SC4-2-u1-X17","explanation":["차례를 떠올려요.","보름달 다음은 하현달이에요.","첫 달-초승달, 보름달 다음-하현달, 마지막-그믐달이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_sci_u1_review_a#12','sci',4,2,'u1','','g4_2_sci_u1_review_a','unit_review','SC4-2-u1-C12',2,'mc','auto','태양계에 대해 바르게 말한 것은 무엇인가요?',ARRAY['SC4-2-u1-X23','SC4-2-u1-X24','SC4-2-u1-X25']::text[],false,'{"seq":12,"concept":"SC4-2-u1-C12","difficulty":2,"kind":"mc","stem":"태양계에 대해 바르게 말한 것은 무엇인가요?","options":[{"t":"태양계에는 태양과 행성 외에도 여러 가지 천체가 있다","correct":true},{"t":"태양계에는 태양과 행성만 있다","mis":"SC4-2-u1-X23"},{"t":"태양계는 천체만 가리키고 공간은 뺀다","mis":"SC4-2-u1-X24"},{"t":"태양계의 중심에는 지구가 있다","mis":"SC4-2-u1-X25"}],"explanation":["태양계의 뜻을 떠올려요.","여러 가지 천체가 있어요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_sci_u1_review_a#13','sci',4,2,'u1','','g4_2_sci_u1_review_a','unit_review','SC4-2-u1-C14',2,'match','auto','행성과 특징을 알맞게 이으세요.','{}'::text[],false,'{"seq":13,"concept":"SC4-2-u1-C14","difficulty":2,"kind":"match","stem":"행성과 특징을 알맞게 이으세요.","pairs":[{"l":"금성","r":"노란색이고 지구에서 가장 밝게 보여요"},{"l":"해왕성","r":"파란색이고 표면에 검은 점이 있어요"},{"l":"천왕성","r":"청록색이고 희미한 고리가 있어요"}],"mis":"SC4-2-u1-X29","explanation":["색깔을 떠올려요.","청록색은 천왕성이에요.","금성-노란색, 해왕성-파란색, 천왕성-청록색이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_sci_u1_review_a#14','sci',4,2,'u1','','g4_2_sci_u1_review_a','unit_review','SC4-2-u1-C16',2,'match','auto','천체와 알맞은 설명을 이으세요.','{}'::text[],false,'{"seq":14,"concept":"SC4-2-u1-C16","difficulty":2,"kind":"match","stem":"천체와 알맞은 설명을 이으세요.","pairs":[{"l":"북극성","r":"스스로 빛을 내는 별"},{"l":"목성","r":"스스로 빛을 내지 않는 행성"},{"l":"태양","r":"태양계의 유일한 별"}],"mis":"SC4-2-u1-X32","explanation":["스스로 빛을 내는지 봐요.","목성은 행성이에요.","북극성-별, 목성-행성, 태양-유일한 별이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_sci_u1_review_a#15','sci',4,2,'u1','','g4_2_sci_u1_review_a','unit_review','SC4-2-u1-C18',2,'match','auto','별과 별자리를 알맞게 이으세요.','{}'::text[],false,'{"seq":15,"concept":"SC4-2-u1-C18","difficulty":2,"kind":"match","stem":"별과 별자리를 알맞게 이으세요.","pairs":[{"l":"북극성","r":"작은곰자리의 꼬리 부분"},{"l":"북두칠성","r":"큰곰자리의 꼬리 부분"},{"l":"카시오페이아자리","r":"북쪽 밤하늘의 대표적인 별자리"}],"mis":"SC4-2-u1-X36","explanation":["꼬리 부분을 떠올려요.","북두칠성은 큰곰자리예요.","북극성-작은곰, 북두칠성-큰곰, 카시오페이아-대표 별자리예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_sci_u1_review_a#16','sci',4,2,'u1','','g4_2_sci_u1_review_a','unit_review','SC4-2-u1-C20',2,'mc','auto','우주여행에 대해 알맞지 않게 말한 것은 무엇인가요?',ARRAY['SC4-2-u1-X40']::text[],false,'{"seq":16,"concept":"SC4-2-u1-C20","difficulty":2,"kind":"mc","stem":"우주여행에 대해 알맞지 않게 말한 것은 무엇인가요?","options":[{"t":"다른 천체에 내려야만 우주여행이다","correct":true},{"t":"일반인도 우주선을 타고 우주에 다녀왔다","mis":"SC4-2-u1-X40"},{"t":"우주여행 상품으로 우주를 체험할 수 있다","mis":"SC4-2-u1-X40"},{"t":"관광객을 태운 우주선이 발사되었다","mis":"SC4-2-u1-X40"}],"explanation":["우주는 공간이에요.","다녀오는 것도 돼요.","첫 번째가 알맞지 않아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_sci_u1_review_a#17','sci',4,2,'u1','','g4_2_sci_u1_review_a','unit_review','SC4-2-u1-C4',3,'error','auto','별빛반 일지 ②를 보고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SC4-2-u1-X07','SC4-2-u1-X08','SC4-2-u1-X10']::text[],false,'{"seq":17,"concept":"SC4-2-u1-C4","difficulty":3,"kind":"error","stem":"별빛반 일지 ②를 보고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"친구 다 — 「사진에서 둥그니까 달은 동전처럼 납작해.」","correct":true,"mis_target":"SC4-2-u1-X07"},{"t":"친구 가 — 「옆에서 보아도 둥근 모형이 달과 같았어.」","mis":"SC4-2-u1-X08"},{"t":"친구 나 — 「표면에 움푹 파인 곳이 많아.」","mis":"SC4-2-u1-X10"}],"explanation":["첫 줄을 읽어요.","달은 공 모양이에요.","친구 다가 잘못 말했어요."],"asset":{"type":"passage","lines":["모양 — 앞에서 보아도 옆에서 보아도 둥근 모형이 달과 같았다.","표면 — 단단한 땅이고 울퉁불퉁하며 움푹 파인 곳이 많다.","어두운 곳 — 주변보다 어둡고 매끈매끈해 보인다.","조사 — 스마트 기기로 찾은 자료의 출처를 적었다."],"title":"별빛반 일지 ② 달 사진 관찰"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_sci_u1_review_a#18','sci',4,2,'u1','','g4_2_sci_u1_review_a','unit_review','SC4-2-u1-C11',3,'error','auto','별빛반 일지 ③을 보고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SC4-2-u1-X21','SC4-2-u1-X19','SC4-2-u1-X20']::text[],false,'{"seq":18,"concept":"SC4-2-u1-C11","difficulty":3,"kind":"error","stem":"별빛반 일지 ③을 보고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"친구 나 — 「달의 모양이 실제로 바뀌었으니 다르게 보였지.」","correct":true,"mis_target":"SC4-2-u1-X21"},{"t":"친구 가 — 「보이는 달의 모양이 차례로 달라졌어.」","mis":"SC4-2-u1-X19"},{"t":"친구 다 — 「약 30일 뒤 같은 모양을 다시 봤어.」","mis":"SC4-2-u1-X20"}],"explanation":["실제 달의 모양을 떠올려요.","실제 모양은 그대로예요.","친구 나가 잘못 말했어요."],"asset":{"type":"passage","lines":["관찰 — 어른과 함께 저녁에 탁 트인 운동장에서 했다.","기록 — 눈썹 모양 → 반달 → 둥근 달 → 반달 → 눈썹 모양","흐린 날 — 달이 보이지 않아 스마트 기기로 확인했다.","첫날과 같은 모양의 달을 약 30일 뒤에 다시 보았다."],"title":"별빛반 일지 ③ 여러 날 달 관찰"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_sci_u1_review_a#19','sci',4,2,'u1','','g4_2_sci_u1_review_a','unit_review','SC4-2-u1-C14',3,'error','auto','별빛반 일지 ④를 보고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SC4-2-u1-X28','SC4-2-u1-X27']::text[],false,'{"seq":19,"concept":"SC4-2-u1-C14","difficulty":3,"kind":"error","stem":"별빛반 일지 ④를 보고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"친구 가 — 「고리가 있는 행성은 ㉡ 하나뿐이야.」","correct":true,"mis_target":"SC4-2-u1-X28"},{"t":"친구 나 — 「㉢과 ㉣에도 희미한 고리가 있어.」","mis":"SC4-2-u1-X28"},{"t":"친구 다 — 「㉠은 표면에 단단한 땅이 있어.」","mis":"SC4-2-u1-X27"}],"explanation":["희미한 고리를 찾아요.","㉢, ㉣에도 있어요.","친구 가가 잘못 말했어요."],"asset":{"type":"passage","lines":["㉠ 붉은색, 표면에 단단한 땅","㉡ 연한 노란색, 크고 뚜렷한 고리","㉢ 갈색·흰색, 줄무늬와 붉은 점, 희미한 고리","㉣ 청록색, 표면이 기체, 희미한 고리","전시 — 태양 모형을 가운데에 두고 행성 모형을 놓았다."],"title":"별빛반 일지 ④ 행성 모형 전시"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_sci_u1_review_a#20','sci',4,2,'u1','','g4_2_sci_u1_review_a','unit_review','SC4-2-u1-C16',3,'error','auto','별빛반 일지 ⑤를 보고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SC4-2-u1-X32','SC4-2-u1-X33']::text[],false,'{"seq":20,"concept":"SC4-2-u1-C16","difficulty":3,"kind":"error","stem":"별빛반 일지 ⑤를 보고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"친구 다 — 「목성도 빛나 보이니 별이야.」","correct":true,"mis_target":"SC4-2-u1-X32"},{"t":"친구 가 — 「북극성은 스스로 빛을 내.」","mis":"SC4-2-u1-X32"},{"t":"친구 나 — 「태양은 태양계의 유일한 별이야.」","mis":"SC4-2-u1-X33"}],"explanation":["둘째 줄을 읽어요.","목성은 행성이에요.","친구 다가 잘못 말했어요."],"asset":{"type":"passage","lines":["북극성 — 스스로 빛을 내는 별이다.","목성 — 별처럼 빛나 보이지만 스스로 빛을 내지 않는다.","태양 — 태양계의 하나뿐인 별이다.","친구 가 — 「별자리는 별들을 연결해 이름을 붙인 것이야.」"],"title":"별빛반 일지 ⑤ 별과 행성"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_sci_u1_review_a#21','sci',4,2,'u1','','g4_2_sci_u1_review_a','unit_review','SC4-2-u1-C22',3,'error','auto','별빛반 일지 ⑦을 보고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SC4-2-u1-X42','SC4-2-u1-X43']::text[],false,'{"seq":21,"concept":"SC4-2-u1-C22","difficulty":3,"kind":"error","stem":"별빛반 일지 ⑦을 보고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"친구 나 — 「색만 더 칠하면 최고의 자료가 될 거야.」","correct":true,"mis_target":"SC4-2-u1-X42"},{"t":"친구 가 — 「태양이 중심에 있다는 특징을 잘 살렸어.」","mis":"SC4-2-u1-X42"},{"t":"친구 다 — 「다른 모둠 발표도 경청하자.」","mis":"SC4-2-u1-X43"}],"explanation":["살펴보는 기준을 떠올려요.","특징이 먼저예요.","친구 나가 잘못 말했어요."],"asset":{"type":"passage","lines":["홍보할 천체 — 태양","특징 — 태양계의 중심에 있다.","홍보 내용 — 태양에서 여러 행성을 바라보는 여행","친구 나 — 「색만 더 칠하면 최고의 자료가 될 거야.」"],"title":"별빛반 일지 ⑦ 태양계 여행 홍보 자료"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_sci_u1_review_a#22','sci',4,2,'u1','','g4_2_sci_u1_review_a','unit_review','SC4-2-u1-C26',3,'error','auto','별빛반 일지 ⑧을 보고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SC4-2-u1-X47','SC4-2-u1-X45','SC4-2-u1-X46']::text[],false,'{"seq":22,"concept":"SC4-2-u1-C26","difficulty":3,"kind":"error","stem":"별빛반 일지 ⑧을 보고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"친구 다 — 「다누리호는 땅 위에서 달을 보는 망원경이야.」","correct":true,"mis_target":"SC4-2-u1-X47"},{"t":"친구 가 — 「망원경 덕분에 달 표면을 알게 됐어.」","mis":"SC4-2-u1-X45"},{"t":"친구 나 — 「지구 밖 망원경은 날씨와 상관없어.」","mis":"SC4-2-u1-X46"}],"explanation":["넷째 줄을 읽어요.","다누리호는 탐사선이에요.","친구 다가 잘못 말했어요."],"asset":{"type":"passage","lines":["맨눈으로 보던 때에는 행성의 모습을 자세히 알기 어려웠다.","망원경으로 달의 울퉁불퉁한 표면을 알아냈다.","지구 밖으로 보낸 망원경은 날씨에 상관없이 관찰한다.","다누리호는 달 주위를 돌며 달 표면을 탐사한다."],"title":"별빛반 일지 ⑧ 망원경과 탐사선"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_sci_u1_review_a#23','sci',4,2,'u1','','g4_2_sci_u1_review_a','unit_review','SC4-2-u1-C2',4,'essay','teacher','별빛반 일지 ①을 보고 밤하늘 단어 놀이 하는 방법을 차례대로 쓰고, 일지의 다짐처럼 놀이할 때 지킬 점을 한 가지 쓰세요.','{}'::text[],false,'{"seq":23,"concept":"SC4-2-u1-C2","difficulty":4,"kind":"essay","stem":"별빛반 일지 ①을 보고 밤하늘 단어 놀이 하는 방법을 차례대로 쓰고, 일지의 다짐처럼 놀이할 때 지킬 점을 한 가지 쓰세요.","answer_guide":{"answer":"예: 들어 본 단어 다섯 개를 종이에 하나씩 적는다. 첫 친구가 들어 본 내용을 말하며 종이를 내려놓고, 같은 단어를 가진 친구도 함께 내려놓으며 말한다. 종이를 모두 내려놓을 때까지 되풀이한다. 놀이할 때에는 겨루지 않고 친구의 이야기를 존중한다.","scoring_points":["단어를 적고 말하며 내려놓는 차례를 썼는가","같은 단어를 함께 내려놓는 것과 되풀이를 썼는가","놀이할 때 지킬 점을 썼는가"]},"explanation":["일지를 읽어요.","차례를 써요.","지킬 점을 써요."],"asset":{"type":"passage","lines":["모둠원이 밤하늘에 대해 들어 본 단어 다섯 개씩을 종이에 적었다.","친구 가 — 「나는 저녁에 반달을 본 적이 있어.」","친구 나도 「반달」 종이가 있어 함께 내려놓으며 말했다.","다짐 — 겨루지 않고 서로의 이야기를 존중하기"],"title":"별빛반 일지 ① 밤하늘 단어 놀이"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_sci_u1_review_a#24','sci',4,2,'u1','','g4_2_sci_u1_review_a','unit_review','SC4-2-u1-C11',4,'mc','auto','친구가 「달의 모양이 바뀌는 건 달이 실제로 줄었다 커졌다 하기 때문이야.」라고 했어요. 가장 알맞게 답한 것은 무엇인가요?',ARRAY['SC4-2-u1-X21','SC4-2-u1-X19','SC4-2-u1-X22']::text[],false,'{"seq":24,"concept":"SC4-2-u1-C11","difficulty":4,"kind":"mc","stem":"친구가 「달의 모양이 바뀌는 건 달이 실제로 줄었다 커졌다 하기 때문이야.」라고 했어요. 가장 알맞게 답한 것은 무엇인가요?","options":[{"t":"「보이는 모양이 달라질 뿐 실제 달의 모양은 변하지 않아. 여러 날 관찰하면 차례로 달라지다가 약 30일마다 되풀이돼.」","correct":true},{"t":"「맞아, 달은 실제로 작아졌다 커져.」","mis":"SC4-2-u1-X21"},{"t":"「달은 하루 만에 모양이 다 바뀌어.」","mis":"SC4-2-u1-X19"},{"t":"「그믐달 뒤에는 달이 사라져.」","mis":"SC4-2-u1-X22"}],"explanation":["실제 달의 모양을 떠올려요.","보이는 모양만 달라요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_sci_u1_review_a#25','sci',4,2,'u1','','g4_2_sci_u1_review_a','unit_review','SC4-2-u1-C16',4,'essay','teacher','별빛반 일지 ⑤를 보고 북극성과 목성이 어떻게 다른지 별의 뜻과 이어 쓰고, 태양이 어떤 천체인지 쓰세요.','{}'::text[],false,'{"seq":25,"concept":"SC4-2-u1-C16","difficulty":4,"kind":"essay","stem":"별빛반 일지 ⑤를 보고 북극성과 목성이 어떻게 다른지 별의 뜻과 이어 쓰고, 태양이 어떤 천체인지 쓰세요.","answer_guide":{"answer":"예: 별은 스스로 빛을 내는 천체이다. 북극성은 스스로 빛을 내는 별이고, 목성은 별처럼 빛나 보이지만 스스로 빛을 내지 않는 행성이다. 태양은 태양계의 유일한 별이다.","scoring_points":["별의 뜻을 썼는가","북극성과 목성의 다른 점을 썼는가","태양이 태양계의 유일한 별임을 썼는가"]},"explanation":["일지를 읽어요.","별의 뜻을 써요.","태양을 써요."],"asset":{"type":"passage","lines":["북극성 — 스스로 빛을 내는 별이다.","목성 — 별처럼 빛나 보이지만 스스로 빛을 내지 않는다.","태양 — 태양계의 하나뿐인 별이다.","친구 가 — 「별자리는 별들을 연결해 이름을 붙인 것이야.」"],"title":"별빛반 일지 ⑤ 별과 행성"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_sci_u1_review_b#1','sci',4,2,'u1','','g4_2_sci_u1_review_b','unit_review','SC4-2-u1-C1',1,'sa','auto','별빛반 일지 ①에서 친구 가가 저녁에 본 적이 있다고 말한 것을 두 글자로 쓰세요.','{}'::text[],false,'{"seq":1,"concept":"SC4-2-u1-C1","difficulty":1,"kind":"sa","stem":"별빛반 일지 ①에서 친구 가가 저녁에 본 적이 있다고 말한 것을 두 글자로 쓰세요.","answer":["반달"],"explanation":["둘째 줄을 읽어요.","달의 모습이에요.","반달이에요."],"asset":{"type":"passage","lines":["모둠원이 밤하늘에 대해 들어 본 단어 다섯 개씩을 종이에 적었다.","친구 가 — 「나는 저녁에 반달을 본 적이 있어.」","친구 나도 「반달」 종이가 있어 함께 내려놓으며 말했다.","다짐 — 겨루지 않고 서로의 이야기를 존중하기"],"title":"별빛반 일지 ① 밤하늘 단어 놀이"},"mis":"SC4-2-u1-X01"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_sci_u1_review_b#2','sci',4,2,'u1','','g4_2_sci_u1_review_b','unit_review','SC4-2-u1-C6',1,'sa','auto','별빛반 일지 ②에서 「주변보다 어둡고 매끈매끈해 보이는」 곳의 이름을 쓰세요.','{}'::text[],false,'{"seq":2,"concept":"SC4-2-u1-C6","difficulty":1,"kind":"sa","stem":"별빛반 일지 ②에서 「주변보다 어둡고 매끈매끈해 보이는」 곳의 이름을 쓰세요.","answer":["달의 바다","달의바다"],"explanation":["셋째 줄을 읽어요.","바다처럼 보여요.","달의 바다예요."],"asset":{"type":"passage","lines":["모양 — 앞에서 보아도 옆에서 보아도 둥근 모형이 달과 같았다.","표면 — 단단한 땅이고 울퉁불퉁하며 움푹 파인 곳이 많다.","어두운 곳 — 주변보다 어둡고 매끈매끈해 보인다.","조사 — 스마트 기기로 찾은 자료의 출처를 적었다."],"title":"별빛반 일지 ② 달 사진 관찰"},"mis":"SC4-2-u1-X12"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_sci_u1_review_b#3','sci',4,2,'u1','','g4_2_sci_u1_review_b','unit_review','SC4-2-u1-C11',1,'sa','auto','별빛반 일지 ③에서 첫날과 같은 모양의 달을 다시 본 것은 약 며칠 뒤인가요? 수만 쓰세요.','{}'::text[],false,'{"seq":3,"concept":"SC4-2-u1-C11","difficulty":1,"kind":"sa","stem":"별빛반 일지 ③에서 첫날과 같은 모양의 달을 다시 본 것은 약 며칠 뒤인가요? 수만 쓰세요.","answer":["30"],"explanation":["넷째 줄을 읽어요.","약 ○○일이에요.","30이에요."],"asset":{"type":"passage","lines":["관찰 — 어른과 함께 저녁에 탁 트인 운동장에서 했다.","기록 — 눈썹 모양 → 반달 → 둥근 달 → 반달 → 눈썹 모양","흐린 날 — 달이 보이지 않아 스마트 기기로 확인했다.","첫날과 같은 모양의 달을 약 30일 뒤에 다시 보았다."],"title":"별빛반 일지 ③ 여러 날 달 관찰"},"mis":"SC4-2-u1-X20"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_sci_u1_review_b#4','sci',4,2,'u1','','g4_2_sci_u1_review_b','unit_review','SC4-2-u1-C14',1,'sa','auto','별빛반 일지 ④에서 ㉠은 어느 행성인가요? 두 글자로 쓰세요.','{}'::text[],false,'{"seq":4,"concept":"SC4-2-u1-C14","difficulty":1,"kind":"sa","stem":"별빛반 일지 ④에서 ㉠은 어느 행성인가요? 두 글자로 쓰세요.","answer":["화성"],"explanation":["㉠을 읽어요.","붉은색이에요.","화성이에요."],"asset":{"type":"passage","lines":["㉠ 붉은색, 표면에 단단한 땅","㉡ 연한 노란색, 크고 뚜렷한 고리","㉢ 갈색·흰색, 줄무늬와 붉은 점, 희미한 고리","㉣ 청록색, 표면이 기체, 희미한 고리","전시 — 태양 모형을 가운데에 두고 행성 모형을 놓았다."],"title":"별빛반 일지 ④ 행성 모형 전시"},"mis":"SC4-2-u1-X29"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_sci_u1_review_b#5','sci',4,2,'u1','','g4_2_sci_u1_review_b','unit_review','SC4-2-u1-C17',1,'sa','auto','별빛반 일지 ⑤에서 친구 가가 「별들을 연결해 이름을 붙인 것」이라고 말한 것을 쓰세요.','{}'::text[],false,'{"seq":5,"concept":"SC4-2-u1-C17","difficulty":1,"kind":"sa","stem":"별빛반 일지 ⑤에서 친구 가가 「별들을 연결해 이름을 붙인 것」이라고 말한 것을 쓰세요.","answer":["별자리"],"explanation":["넷째 줄을 읽어요.","별을 이었어요.","별자리예요."],"asset":{"type":"passage","lines":["북극성 — 스스로 빛을 내는 별이다.","목성 — 별처럼 빛나 보이지만 스스로 빛을 내지 않는다.","태양 — 태양계의 하나뿐인 별이다.","친구 가 — 「별자리는 별들을 연결해 이름을 붙인 것이야.」"],"title":"별빛반 일지 ⑤ 별과 행성"},"mis":"SC4-2-u1-X34"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_sci_u1_review_b#6','sci',4,2,'u1','','g4_2_sci_u1_review_b','unit_review','SC4-2-u1-C18',1,'sa','auto','별빛반 일지 ⑥에서 큰곰자리 꼬리 부분의 국자 모양 일곱 별의 이름을 쓰세요.','{}'::text[],false,'{"seq":6,"concept":"SC4-2-u1-C18","difficulty":1,"kind":"sa","stem":"별빛반 일지 ⑥에서 큰곰자리 꼬리 부분의 국자 모양 일곱 별의 이름을 쓰세요.","answer":["북두칠성"],"explanation":["셋째 줄을 읽어요.","일곱 별이에요.","북두칠성이에요."],"asset":{"type":"passage","lines":["필름으로 큰곰자리, 작은곰자리, 카시오페이아자리를 찾았다.","작은곰자리 꼬리 부분의 북극성은 위치가 거의 변하지 않았다.","큰곰자리 꼬리 부분에서 국자 모양의 일곱 별을 보았다.","프로그램을 켜니 북극성 주변에 별자리가 더 있었다."],"title":"별빛반 일지 ⑥ 북쪽 하늘 관찰"},"mis":"SC4-2-u1-X36"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_sci_u1_review_b#7','sci',4,2,'u1','','g4_2_sci_u1_review_b','unit_review','SC4-2-u1-C21',1,'sa','auto','별빛반 일지 ⑦에서 태양이 태양계의 어디에 있다고 적었나요? 두 글자로 쓰세요.','{}'::text[],false,'{"seq":7,"concept":"SC4-2-u1-C21","difficulty":1,"kind":"sa","stem":"별빛반 일지 ⑦에서 태양이 태양계의 어디에 있다고 적었나요? 두 글자로 쓰세요.","answer":["중심"],"explanation":["둘째 줄을 읽어요.","가운데예요.","중심이에요."],"asset":{"type":"passage","lines":["홍보할 천체 — 태양","특징 — 태양계의 중심에 있다.","홍보 내용 — 태양에서 여러 행성을 바라보는 여행","친구 나 — 「색만 더 칠하면 최고의 자료가 될 거야.」"],"title":"별빛반 일지 ⑦ 태양계 여행 홍보 자료"},"mis":"SC4-2-u1-X25"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_sci_u1_review_b#8','sci',4,2,'u1','','g4_2_sci_u1_review_b','unit_review','SC4-2-u1-C26',1,'sa','auto','별빛반 일지 ⑧에서 달 주위를 돌며 달 표면을 탐사하는 것의 이름을 쓰세요.','{}'::text[],false,'{"seq":8,"concept":"SC4-2-u1-C26","difficulty":1,"kind":"sa","stem":"별빛반 일지 ⑧에서 달 주위를 돌며 달 표면을 탐사하는 것의 이름을 쓰세요.","answer":["다누리호","다누리"],"explanation":["넷째 줄을 읽어요.","달 탐사선이에요.","다누리호예요."],"asset":{"type":"passage","lines":["맨눈으로 보던 때에는 행성의 모습을 자세히 알기 어려웠다.","망원경으로 달의 울퉁불퉁한 표면을 알아냈다.","지구 밖으로 보낸 망원경은 날씨에 상관없이 관찰한다.","다누리호는 달 주위를 돌며 달 표면을 탐사한다."],"title":"별빛반 일지 ⑧ 망원경과 탐사선"},"mis":"SC4-2-u1-X47"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_sci_u1_review_b#9','sci',4,2,'u1','','g4_2_sci_u1_review_b','unit_review','SC4-2-u1-C3',2,'mc','auto','밤하늘 단어 놀이에서 「이 시간에는 하지 않아요」에 들어갈 행동은 무엇인가요?',ARRAY['SC4-2-u1-X05','SC4-2-u1-X06']::text[],false,'{"seq":9,"concept":"SC4-2-u1-C3","difficulty":2,"kind":"mc","stem":"밤하늘 단어 놀이에서 「이 시간에는 하지 않아요」에 들어갈 행동은 무엇인가요?","options":[{"t":"단어의 정확한 뜻을 맞히기","correct":true},{"t":"들어 본 내용을 말하기","mis":"SC4-2-u1-X05"},{"t":"경험한 내용을 말하기","mis":"SC4-2-u1-X05"},{"t":"친구 이야기를 듣기","mis":"SC4-2-u1-X06"}],"explanation":["뜻을 배우는 시간이 아니에요.","들어 본 것을 말해요.","뜻 맞히기예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_sci_u1_review_b#10','sci',4,2,'u1','','g4_2_sci_u1_review_b','unit_review','SC4-2-u1-C6',2,'mc','auto','달의 바다에 대해 알맞게 말한 것은 무엇인가요?',ARRAY['SC4-2-u1-X11','SC4-2-u1-X12','SC4-2-u1-X10']::text[],false,'{"seq":10,"concept":"SC4-2-u1-C6","difficulty":2,"kind":"mc","stem":"달의 바다에 대해 알맞게 말한 것은 무엇인가요?","options":[{"t":"어둡고 매끈해 보여 붙은 이름이고 실제로 물은 없다","correct":true},{"t":"바닷물이 가득해 붙은 이름이다","mis":"SC4-2-u1-X11"},{"t":"달 표면의 밝은 곳이다","mis":"SC4-2-u1-X12"},{"t":"움푹 파인 구덩이의 이름이다","mis":"SC4-2-u1-X10"}],"explanation":["이름에 속지 않아요.","물은 없어요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_sci_u1_review_b#11','sci',4,2,'u1','','g4_2_sci_u1_review_b','unit_review','SC4-2-u1-C8',2,'mc','auto','달 관찰 계획서에 쓸 내용이 아닌 것은 무엇인가요?',ARRAY['SC4-2-u1-X14']::text[],false,'{"seq":11,"concept":"SC4-2-u1-C8","difficulty":2,"kind":"mc","stem":"달 관찰 계획서에 쓸 내용이 아닌 것은 무엇인가요?","options":[{"t":"친구에게 줄 선물","correct":true},{"t":"관찰 기간","mis":"SC4-2-u1-X14"},{"t":"관찰 장소","mis":"SC4-2-u1-X14"},{"t":"관찰한 달의 모양","mis":"SC4-2-u1-X14"}],"explanation":["계획서 칸을 떠올려요.","기간, 장소, 모양이에요.","선물은 아니에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_sci_u1_review_b#12','sci',4,2,'u1','','g4_2_sci_u1_review_b','unit_review','SC4-2-u1-C13',2,'mc','auto','태양에서 가까운 차례로 네 번째와 다섯 번째에 있는 행성을 차례대로 쓴 것은 무엇인가요?',ARRAY['SC4-2-u1-X26']::text[],false,'{"seq":12,"concept":"SC4-2-u1-C13","difficulty":2,"kind":"mc","stem":"태양에서 가까운 차례로 네 번째와 다섯 번째에 있는 행성을 차례대로 쓴 것은 무엇인가요?","options":[{"t":"화성, 목성","correct":true},{"t":"지구, 화성","mis":"SC4-2-u1-X26"},{"t":"목성, 토성","mis":"SC4-2-u1-X26"},{"t":"금성, 지구","mis":"SC4-2-u1-X26"}],"explanation":["수·금·지·화·목이에요.","넷째와 다섯째예요.","화성, 목성이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_sci_u1_review_b#13','sci',4,2,'u1','','g4_2_sci_u1_review_b','unit_review','SC4-2-u1-C14',2,'mc','auto','표면이 기체로 이루어져 있고 고리가 있는 행성끼리 묶은 것은 무엇인가요?',ARRAY['SC4-2-u1-X27','SC4-2-u1-X28']::text[],false,'{"seq":13,"concept":"SC4-2-u1-C14","difficulty":2,"kind":"mc","stem":"표면이 기체로 이루어져 있고 고리가 있는 행성끼리 묶은 것은 무엇인가요?","options":[{"t":"목성, 토성, 천왕성, 해왕성","correct":true},{"t":"수성, 금성, 지구, 화성","mis":"SC4-2-u1-X27"},{"t":"토성 하나","mis":"SC4-2-u1-X28"},{"t":"지구, 목성, 토성, 화성","mis":"SC4-2-u1-X27"}],"explanation":["태양에서 먼 네 행성이에요.","희미한 고리도 고리예요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_sci_u1_review_b#14','sci',4,2,'u1','','g4_2_sci_u1_review_b','unit_review','SC4-2-u1-C17',2,'mc','auto','별자리에 대한 설명으로 알맞지 않은 것은 무엇인가요?',ARRAY['SC4-2-u1-X34']::text[],false,'{"seq":14,"concept":"SC4-2-u1-C17","difficulty":2,"kind":"mc","stem":"별자리에 대한 설명으로 알맞지 않은 것은 무엇인가요?","options":[{"t":"별자리의 이름과 모양은 옛날부터 지금까지 한 번도 바뀌지 않았다","correct":true},{"t":"별자리는 별들을 연결해 이름을 붙인 것이다","mis":"SC4-2-u1-X34"},{"t":"옛날에는 지역에 따라 별자리가 달랐다","mis":"SC4-2-u1-X34"},{"t":"천문학자들이 공통으로 쓸 별자리를 정했다","mis":"SC4-2-u1-X34"}],"explanation":["옛날과 지금을 떠올려요.","바뀌기도 했어요.","첫 번째가 알맞지 않아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_sci_u1_review_b#15','sci',4,2,'u1','','g4_2_sci_u1_review_b','unit_review','SC4-2-u1-C19',2,'mc','auto','천체 관측 프로그램으로 북쪽 하늘을 관찰할 때 가장 먼저 찾을 것은 무엇인가요?',ARRAY['SC4-2-u1-X39','SC4-2-u1-X38']::text[],false,'{"seq":15,"concept":"SC4-2-u1-C19","difficulty":2,"kind":"mc","stem":"천체 관측 프로그램으로 북쪽 하늘을 관찰할 때 가장 먼저 찾을 것은 무엇인가요?","options":[{"t":"북극성","correct":true},{"t":"목성","mis":"SC4-2-u1-X39"},{"t":"남쪽 하늘의 별","mis":"SC4-2-u1-X38"},{"t":"가장 밝은 행성","mis":"SC4-2-u1-X39"}],"explanation":["관찰 차례를 떠올려요.","먼저 찾는 별이 있어요.","북극성이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_sci_u1_review_b#16','sci',4,2,'u1','','g4_2_sci_u1_review_b','unit_review','SC4-2-u1-C22',2,'mc','auto','다른 모둠의 홍보 자료를 평가할 때 알맞은 방법은 무엇인가요?',ARRAY['SC4-2-u1-X43','SC4-2-u1-X42']::text[],false,'{"seq":16,"concept":"SC4-2-u1-C22","difficulty":2,"kind":"mc","stem":"다른 모둠의 홍보 자료를 평가할 때 알맞은 방법은 무엇인가요?","options":[{"t":"잘한 점을 위주로 찾는다","correct":true},{"t":"못한 점만 골라 놀린다","mis":"SC4-2-u1-X43"},{"t":"꾸밈만 본다","mis":"SC4-2-u1-X42"},{"t":"우리 모둠과 같은지만 본다","mis":"SC4-2-u1-X43"}],"explanation":["평가할 때를 떠올려요.","잘한 점이에요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_sci_u1_review_b#17','sci',4,2,'u1','','g4_2_sci_u1_review_b','unit_review','SC4-2-u1-C6',3,'mc','auto','별빛반 일지 ②의 「어두운 곳」을 바르게 설명한 것은 무엇인가요?',ARRAY['SC4-2-u1-X11','SC4-2-u1-X10','SC4-2-u1-X12']::text[],false,'{"seq":17,"concept":"SC4-2-u1-C6","difficulty":3,"kind":"mc","stem":"별빛반 일지 ②의 「어두운 곳」을 바르게 설명한 것은 무엇인가요?","options":[{"t":"달의 바다라고 하며, 바다처럼 보일 뿐 실제로 물은 없다","correct":true},{"t":"달의 바다라고 하며 물이 가득하다","mis":"SC4-2-u1-X11"},{"t":"충돌 구덩이라고 하며 움푹 파였다","mis":"SC4-2-u1-X10"},{"t":"밝은 곳이라고 하며 빛이 난다","mis":"SC4-2-u1-X12"}],"explanation":["셋째 줄을 읽어요.","바다처럼 보여요.","첫 번째예요."],"asset":{"type":"passage","lines":["모양 — 앞에서 보아도 옆에서 보아도 둥근 모형이 달과 같았다.","표면 — 단단한 땅이고 울퉁불퉁하며 움푹 파인 곳이 많다.","어두운 곳 — 주변보다 어둡고 매끈매끈해 보인다.","조사 — 스마트 기기로 찾은 자료의 출처를 적었다."],"title":"별빛반 일지 ② 달 사진 관찰"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_sci_u1_review_b#18','sci',4,2,'u1','','g4_2_sci_u1_review_b','unit_review','SC4-2-u1-C10',3,'mc','auto','별빛반 일지 ③의 기록에 달의 이름을 차례대로 붙인 것은 무엇인가요?',ARRAY['SC4-2-u1-X17','SC4-2-u1-X18']::text[],false,'{"seq":18,"concept":"SC4-2-u1-C10","difficulty":3,"kind":"mc","stem":"별빛반 일지 ③의 기록에 달의 이름을 차례대로 붙인 것은 무엇인가요?","options":[{"t":"초승달 → 상현달 → 보름달 → 하현달 → 그믐달","correct":true},{"t":"그믐달 → 하현달 → 보름달 → 상현달 → 초승달","mis":"SC4-2-u1-X17"},{"t":"초승달 → 하현달 → 보름달 → 상현달 → 그믐달","mis":"SC4-2-u1-X17"},{"t":"보름달 → 상현달 → 초승달 → 그믐달 → 하현달","mis":"SC4-2-u1-X18"}],"explanation":["눈썹 모양부터예요.","둥근 달은 보름달이에요.","첫 번째예요."],"asset":{"type":"passage","lines":["관찰 — 어른과 함께 저녁에 탁 트인 운동장에서 했다.","기록 — 눈썹 모양 → 반달 → 둥근 달 → 반달 → 눈썹 모양","흐린 날 — 달이 보이지 않아 스마트 기기로 확인했다.","첫날과 같은 모양의 달을 약 30일 뒤에 다시 보았다."],"title":"별빛반 일지 ③ 여러 날 달 관찰"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_sci_u1_review_b#19','sci',4,2,'u1','','g4_2_sci_u1_review_b','unit_review','SC4-2-u1-C14',3,'mc','auto','별빛반 일지 ④의 ㉢과 ㉣을 차례대로 바르게 쓴 것은 무엇인가요?',ARRAY['SC4-2-u1-X29','SC4-2-u1-X27']::text[],false,'{"seq":19,"concept":"SC4-2-u1-C14","difficulty":3,"kind":"mc","stem":"별빛반 일지 ④의 ㉢과 ㉣을 차례대로 바르게 쓴 것은 무엇인가요?","options":[{"t":"목성, 천왕성","correct":true},{"t":"토성, 해왕성","mis":"SC4-2-u1-X29"},{"t":"천왕성, 목성","mis":"SC4-2-u1-X29"},{"t":"화성, 금성","mis":"SC4-2-u1-X27"}],"explanation":["줄무늬와 붉은 점, 청록색이에요.","㉢은 목성이에요.","목성, 천왕성이에요."],"asset":{"type":"passage","lines":["㉠ 붉은색, 표면에 단단한 땅","㉡ 연한 노란색, 크고 뚜렷한 고리","㉢ 갈색·흰색, 줄무늬와 붉은 점, 희미한 고리","㉣ 청록색, 표면이 기체, 희미한 고리","전시 — 태양 모형을 가운데에 두고 행성 모형을 놓았다."],"title":"별빛반 일지 ④ 행성 모형 전시"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_sci_u1_review_b#20','sci',4,2,'u1','','g4_2_sci_u1_review_b','unit_review','SC4-2-u1-C18',3,'mc','auto','별빛반 일지 ⑥을 보고 바르게 정리한 것은 무엇인가요?',ARRAY['SC4-2-u1-X35','SC4-2-u1-X36','SC4-2-u1-X38']::text[],false,'{"seq":20,"concept":"SC4-2-u1-C18","difficulty":3,"kind":"mc","stem":"별빛반 일지 ⑥을 보고 바르게 정리한 것은 무엇인가요?","options":[{"t":"북극성은 작은곰자리에, 국자 모양의 일곱 별은 큰곰자리에 있다","correct":true},{"t":"북극성은 큰곰자리에 있다","mis":"SC4-2-u1-X35"},{"t":"국자 모양의 일곱 별은 작은곰자리에 있다","mis":"SC4-2-u1-X36"},{"t":"북극성의 위치는 밤마다 크게 바뀐다","mis":"SC4-2-u1-X38"}],"explanation":["둘째·셋째 줄을 읽어요.","꼬리 부분을 봐요.","첫 번째예요."],"asset":{"type":"passage","lines":["필름으로 큰곰자리, 작은곰자리, 카시오페이아자리를 찾았다.","작은곰자리 꼬리 부분의 북극성은 위치가 거의 변하지 않았다.","큰곰자리 꼬리 부분에서 국자 모양의 일곱 별을 보았다.","프로그램을 켜니 북극성 주변에 별자리가 더 있었다."],"title":"별빛반 일지 ⑥ 북쪽 하늘 관찰"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_sci_u1_review_b#21','sci',4,2,'u1','','g4_2_sci_u1_review_b','unit_review','SC4-2-u1-C21',3,'mc','auto','별빛반 일지 ⑦의 홍보 내용이 잘된 까닭은 무엇인가요?',ARRAY['SC4-2-u1-X42','SC4-2-u1-X43']::text[],false,'{"seq":21,"concept":"SC4-2-u1-C21","difficulty":3,"kind":"mc","stem":"별빛반 일지 ⑦의 홍보 내용이 잘된 까닭은 무엇인가요?","options":[{"t":"태양이 태양계 중심에 있다는 특징을 살렸기 때문에","correct":true},{"t":"색을 많이 칠했기 때문에","mis":"SC4-2-u1-X42"},{"t":"글자를 꽉 채웠기 때문에","mis":"SC4-2-u1-X42"},{"t":"다른 모둠 내용을 따라 했기 때문에","mis":"SC4-2-u1-X43"}],"explanation":["셋째 줄을 읽어요.","특징을 살렸어요.","첫 번째예요."],"asset":{"type":"passage","lines":["홍보할 천체 — 태양","특징 — 태양계의 중심에 있다.","홍보 내용 — 태양에서 여러 행성을 바라보는 여행","친구 나 — 「색만 더 칠하면 최고의 자료가 될 거야.」"],"title":"별빛반 일지 ⑦ 태양계 여행 홍보 자료"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_sci_u1_review_b#22','sci',4,2,'u1','','g4_2_sci_u1_review_b','unit_review','SC4-2-u1-C24',3,'mc','auto','별빛반 일지 ⑧의 첫 줄과 둘째 줄을 견주어 알 수 있는 것은 무엇인가요?',ARRAY['SC4-2-u1-X45','SC4-2-u1-X46']::text[],false,'{"seq":22,"concept":"SC4-2-u1-C24","difficulty":3,"kind":"mc","stem":"별빛반 일지 ⑧의 첫 줄과 둘째 줄을 견주어 알 수 있는 것은 무엇인가요?","options":[{"t":"망원경이 발명되면서 맨눈으로는 알기 어려웠던 천체의 모습을 더 자세히 알게 되었다","correct":true},{"t":"맨눈과 망원경은 보이는 것이 똑같다","mis":"SC4-2-u1-X45"},{"t":"망원경이 생기자 달 표면이 울퉁불퉁해졌다","mis":"SC4-2-u1-X45"},{"t":"망원경으로는 달을 볼 수 없다","mis":"SC4-2-u1-X46"}],"explanation":["두 줄을 견줘요.","자세히 알게 되었어요.","첫 번째예요."],"asset":{"type":"passage","lines":["맨눈으로 보던 때에는 행성의 모습을 자세히 알기 어려웠다.","망원경으로 달의 울퉁불퉁한 표면을 알아냈다.","지구 밖으로 보낸 망원경은 날씨에 상관없이 관찰한다.","다누리호는 달 주위를 돌며 달 표면을 탐사한다."],"title":"별빛반 일지 ⑧ 망원경과 탐사선"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_sci_u1_review_b#23','sci',4,2,'u1','','g4_2_sci_u1_review_b','unit_review','SC4-2-u1-C4',4,'essay','teacher','별빛반 일지 ②를 보고 달의 모양을 알아내려고 모형을 옆에서도 본 까닭을 쓰고, 달 표면의 특징 두 가지를 쓰세요.','{}'::text[],false,'{"seq":23,"concept":"SC4-2-u1-C4","difficulty":4,"kind":"essay","stem":"별빛반 일지 ②를 보고 달의 모양을 알아내려고 모형을 옆에서도 본 까닭을 쓰고, 달 표면의 특징 두 가지를 쓰세요.","answer_guide":{"answer":"예: 사진처럼 앞에서만 보면 납작한 원과 둥근 공이 똑같이 보여서 옆에서도 보아야 달이 둥근 공 모양인지 알 수 있다. 달 표면은 단단한 땅으로 되어 있고 울퉁불퉁하며, 움푹 파인 충돌 구덩이가 많다.","scoring_points":["옆에서도 본 까닭을 썼는가","달이 둥근 공 모양임을 썼는가","표면의 특징 두 가지를 썼는가"]},"explanation":["첫 줄을 읽어요.","까닭을 써요.","표면을 써요."],"asset":{"type":"passage","lines":["모양 — 앞에서 보아도 옆에서 보아도 둥근 모형이 달과 같았다.","표면 — 단단한 땅이고 울퉁불퉁하며 움푹 파인 곳이 많다.","어두운 곳 — 주변보다 어둡고 매끈매끈해 보인다.","조사 — 스마트 기기로 찾은 자료의 출처를 적었다."],"title":"별빛반 일지 ② 달 사진 관찰"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_sci_u1_review_b#24','sci',4,2,'u1','','g4_2_sci_u1_review_b','unit_review','SC4-2-u1-C12',4,'mc','auto','친구가 「태양계는 태양과 여덟 행성을 줄 세운 그림이야.」라고 했어요. 가장 알맞게 답한 것은 무엇인가요?',ARRAY['SC4-2-u1-X23','SC4-2-u1-X24','SC4-2-u1-X25']::text[],false,'{"seq":24,"concept":"SC4-2-u1-C12","difficulty":4,"kind":"mc","stem":"친구가 「태양계는 태양과 여덟 행성을 줄 세운 그림이야.」라고 했어요. 가장 알맞게 답한 것은 무엇인가요?","options":[{"t":"「태양계는 태양을 비롯하여 태양의 영향을 받는 여러 천체들과 그 공간까지 말해.」","correct":true},{"t":"「맞아, 태양과 행성만 있어.」","mis":"SC4-2-u1-X23"},{"t":"「공간은 빼고 천체만 말해.」","mis":"SC4-2-u1-X24"},{"t":"「지구가 중심이야.」","mis":"SC4-2-u1-X25"}],"explanation":["태양계의 뜻을 떠올려요.","천체와 공간이에요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_sci_u1_review_b#25','sci',4,2,'u1','','g4_2_sci_u1_review_b','unit_review','SC4-2-u1-C18',4,'essay','teacher','별빛반 일지 ⑥을 보고 북극성 주변의 별자리 세 가지와 북극성·북두칠성이 있는 자리를 쓰고, 프로그램으로 새로 알게 된 점을 쓰세요.','{}'::text[],false,'{"seq":25,"concept":"SC4-2-u1-C18","difficulty":4,"kind":"essay","stem":"별빛반 일지 ⑥을 보고 북극성 주변의 별자리 세 가지와 북극성·북두칠성이 있는 자리를 쓰고, 프로그램으로 새로 알게 된 점을 쓰세요.","answer_guide":{"answer":"예: 북극성 주변에는 큰곰자리, 작은곰자리, 카시오페이아자리가 있다. 북극성은 작은곰자리의 꼬리 부분에, 북두칠성은 큰곰자리의 꼬리 부분에 있다. 프로그램을 켜니 북극성 주변에 별자리가 더 있다는 것을 알게 되었다.","scoring_points":["별자리 세 가지를 썼는가","북극성과 북두칠성의 자리를 바르게 썼는가","별자리가 더 있다는 것을 썼는가"]},"explanation":["일지를 읽어요.","자리를 써요.","새로 안 점을 써요."],"asset":{"type":"passage","lines":["필름으로 큰곰자리, 작은곰자리, 카시오페이아자리를 찾았다.","작은곰자리 꼬리 부분의 북극성은 위치가 거의 변하지 않았다.","큰곰자리 꼬리 부분에서 국자 모양의 일곱 별을 보았다.","프로그램을 켜니 북극성 주변에 별자리가 더 있었다."],"title":"별빛반 일지 ⑥ 북쪽 하늘 관찰"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_sci_u1_review_c#1','sci',4,2,'u1','','g4_2_sci_u1_review_c','unit_review','SC4-2-u1-C2',1,'ox','auto','별빛반 일지 ①의 친구 나처럼 같은 단어의 종이가 있으면 함께 내려놓으며 말해요.',ARRAY['SC4-2-u1-X02']::text[],false,'{"seq":1,"concept":"SC4-2-u1-C2","difficulty":1,"kind":"ox","stem":"별빛반 일지 ①의 친구 나처럼 같은 단어의 종이가 있으면 함께 내려놓으며 말해요.","answer":"O","reason_options":[{"t":"같은 단어를 가진 모둠원은 함께 내려놓으며 들어 본 내용을 말하기 때문에","correct":true},{"t":"같은 단어는 먼저 낸 친구만 말할 수 있기 때문에","mis":"SC4-2-u1-X02"}],"mis":"SC4-2-u1-X02","explanation":["셋째 줄을 읽어요.","함께 내려놓았어요.","그래서 O예요."],"asset":{"type":"passage","lines":["모둠원이 밤하늘에 대해 들어 본 단어 다섯 개씩을 종이에 적었다.","친구 가 — 「나는 저녁에 반달을 본 적이 있어.」","친구 나도 「반달」 종이가 있어 함께 내려놓으며 말했다.","다짐 — 겨루지 않고 서로의 이야기를 존중하기"],"title":"별빛반 일지 ① 밤하늘 단어 놀이"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_sci_u1_review_c#2','sci',4,2,'u1','','g4_2_sci_u1_review_c','unit_review','SC4-2-u1-C7',1,'ox','auto','별빛반 일지 ②처럼 조사한 자료는 출처를 확인하고 적어요.',ARRAY['SC4-2-u1-X13']::text[],false,'{"seq":2,"concept":"SC4-2-u1-C7","difficulty":1,"kind":"ox","stem":"별빛반 일지 ②처럼 조사한 자료는 출처를 확인하고 적어요.","answer":"O","reason_options":[{"t":"옳은 정보인지 확인할 수 있기 때문에","correct":true},{"t":"출처를 적으면 글이 길어져 좋지 않기 때문에","mis":"SC4-2-u1-X13"}],"mis":"SC4-2-u1-X13","explanation":["넷째 줄을 읽어요.","출처를 적었어요.","그래서 O예요."],"asset":{"type":"passage","lines":["모양 — 앞에서 보아도 옆에서 보아도 둥근 모형이 달과 같았다.","표면 — 단단한 땅이고 울퉁불퉁하며 움푹 파인 곳이 많다.","어두운 곳 — 주변보다 어둡고 매끈매끈해 보인다.","조사 — 스마트 기기로 찾은 자료의 출처를 적었다."],"title":"별빛반 일지 ② 달 사진 관찰"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_sci_u1_review_c#3','sci',4,2,'u1','','g4_2_sci_u1_review_c','unit_review','SC4-2-u1-C8',1,'ox','auto','별빛반 일지 ③처럼 달이 보이지 않는 날에는 스마트 기기로 확인할 수 있어요.',ARRAY['SC4-2-u1-X15']::text[],false,'{"seq":3,"concept":"SC4-2-u1-C8","difficulty":1,"kind":"ox","stem":"별빛반 일지 ③처럼 달이 보이지 않는 날에는 스마트 기기로 확인할 수 있어요.","answer":"O","reason_options":[{"t":"관찰 시기나 날씨에 따라 달이 보이지 않을 수도 있기 때문에","correct":true},{"t":"달이 보이지 않으면 달이 없어진 것이기 때문에","mis":"SC4-2-u1-X15"}],"mis":"SC4-2-u1-X15","explanation":["셋째 줄을 읽어요.","흐린 날이었어요.","그래서 O예요."],"asset":{"type":"passage","lines":["관찰 — 어른과 함께 저녁에 탁 트인 운동장에서 했다.","기록 — 눈썹 모양 → 반달 → 둥근 달 → 반달 → 눈썹 모양","흐린 날 — 달이 보이지 않아 스마트 기기로 확인했다.","첫날과 같은 모양의 달을 약 30일 뒤에 다시 보았다."],"title":"별빛반 일지 ③ 여러 날 달 관찰"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_sci_u1_review_c#4','sci',4,2,'u1','','g4_2_sci_u1_review_c','unit_review','SC4-2-u1-C12',1,'ox','auto','별빛반 일지 ④처럼 태양은 태양계의 중심에 있어요.',ARRAY['SC4-2-u1-X25']::text[],false,'{"seq":4,"concept":"SC4-2-u1-C12","difficulty":1,"kind":"ox","stem":"별빛반 일지 ④처럼 태양은 태양계의 중심에 있어요.","answer":"O","reason_options":[{"t":"행성들이 태양 주위를 돌고 있기 때문에","correct":true},{"t":"태양은 태양계의 가장 바깥쪽에 있기 때문에","mis":"SC4-2-u1-X25"}],"mis":"SC4-2-u1-X25","explanation":["전시 줄을 읽어요.","가운데에 두었어요.","그래서 O예요."],"asset":{"type":"passage","lines":["㉠ 붉은색, 표면에 단단한 땅","㉡ 연한 노란색, 크고 뚜렷한 고리","㉢ 갈색·흰색, 줄무늬와 붉은 점, 희미한 고리","㉣ 청록색, 표면이 기체, 희미한 고리","전시 — 태양 모형을 가운데에 두고 행성 모형을 놓았다."],"title":"별빛반 일지 ④ 행성 모형 전시"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_sci_u1_review_c#5','sci',4,2,'u1','','g4_2_sci_u1_review_c','unit_review','SC4-2-u1-C16',1,'ox','auto','별빛반 일지 ⑤처럼 태양은 태양계의 하나뿐인 별이에요.',ARRAY['SC4-2-u1-X33']::text[],false,'{"seq":5,"concept":"SC4-2-u1-C16","difficulty":1,"kind":"ox","stem":"별빛반 일지 ⑤처럼 태양은 태양계의 하나뿐인 별이에요.","answer":"O","reason_options":[{"t":"태양계에서 스스로 빛을 내는 천체는 태양뿐이기 때문에","correct":true},{"t":"태양은 행성이기 때문에","mis":"SC4-2-u1-X33"}],"mis":"SC4-2-u1-X33","explanation":["셋째 줄을 읽어요.","하나뿐이에요.","그래서 O예요."],"asset":{"type":"passage","lines":["북극성 — 스스로 빛을 내는 별이다.","목성 — 별처럼 빛나 보이지만 스스로 빛을 내지 않는다.","태양 — 태양계의 하나뿐인 별이다.","친구 가 — 「별자리는 별들을 연결해 이름을 붙인 것이야.」"],"title":"별빛반 일지 ⑤ 별과 행성"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_sci_u1_review_c#6','sci',4,2,'u1','','g4_2_sci_u1_review_c','unit_review','SC4-2-u1-C18',1,'ox','auto','별빛반 일지 ⑥처럼 북극성 주변에는 큰곰자리, 작은곰자리, 카시오페이아자리 말고도 별자리가 더 있어요.',ARRAY['SC4-2-u1-X37']::text[],false,'{"seq":6,"concept":"SC4-2-u1-C18","difficulty":1,"kind":"ox","stem":"별빛반 일지 ⑥처럼 북극성 주변에는 큰곰자리, 작은곰자리, 카시오페이아자리 말고도 별자리가 더 있어요.","answer":"O","reason_options":[{"t":"천체 관측 프로그램으로 보니 여러 별자리가 더 있었기 때문에","correct":true},{"t":"북쪽 하늘의 별자리는 세 개뿐이기 때문에","mis":"SC4-2-u1-X37"}],"mis":"SC4-2-u1-X37","explanation":["넷째 줄을 읽어요.","더 있었어요.","그래서 O예요."],"asset":{"type":"passage","lines":["필름으로 큰곰자리, 작은곰자리, 카시오페이아자리를 찾았다.","작은곰자리 꼬리 부분의 북극성은 위치가 거의 변하지 않았다.","큰곰자리 꼬리 부분에서 국자 모양의 일곱 별을 보았다.","프로그램을 켜니 북극성 주변에 별자리가 더 있었다."],"title":"별빛반 일지 ⑥ 북쪽 하늘 관찰"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_sci_u1_review_c#7','sci',4,2,'u1','','g4_2_sci_u1_review_c','unit_review','SC4-2-u1-C22',1,'ox','auto','별빛반 일지 ⑦의 친구 나처럼 색만 더 칠하면 좋은 홍보 자료가 돼요.',ARRAY['SC4-2-u1-X42']::text[],false,'{"seq":7,"concept":"SC4-2-u1-C22","difficulty":1,"kind":"ox","stem":"별빛반 일지 ⑦의 친구 나처럼 색만 더 칠하면 좋은 홍보 자료가 돼요.","answer":"X","reason_options":[{"t":"천체의 특징을 잘 나타냈는지가 가장 중요하기 때문에","correct":true},{"t":"색을 많이 칠할수록 좋은 자료이기 때문에","mis":"SC4-2-u1-X42"}],"mis":"SC4-2-u1-X42","explanation":["살펴보는 기준을 떠올려요.","특징이 먼저예요.","그래서 X예요."],"asset":{"type":"passage","lines":["홍보할 천체 — 태양","특징 — 태양계의 중심에 있다.","홍보 내용 — 태양에서 여러 행성을 바라보는 여행","친구 나 — 「색만 더 칠하면 최고의 자료가 될 거야.」"],"title":"별빛반 일지 ⑦ 태양계 여행 홍보 자료"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_sci_u1_review_c#8','sci',4,2,'u1','','g4_2_sci_u1_review_c','unit_review','SC4-2-u1-C25',1,'ox','auto','별빛반 일지 ⑧처럼 지구 밖으로 보낸 망원경은 날씨에 상관없이 관찰해요.',ARRAY['SC4-2-u1-X46']::text[],false,'{"seq":8,"concept":"SC4-2-u1-C25","difficulty":1,"kind":"ox","stem":"별빛반 일지 ⑧처럼 지구 밖으로 보낸 망원경은 날씨에 상관없이 관찰해요.","answer":"O","reason_options":[{"t":"지구 밖에 있어 날씨의 영향을 받지 않기 때문에","correct":true},{"t":"맑은 날에만 쓸 수 있기 때문에","mis":"SC4-2-u1-X46"}],"mis":"SC4-2-u1-X46","explanation":["셋째 줄을 읽어요.","날씨에 상관없어요.","그래서 O예요."],"asset":{"type":"passage","lines":["맨눈으로 보던 때에는 행성의 모습을 자세히 알기 어려웠다.","망원경으로 달의 울퉁불퉁한 표면을 알아냈다.","지구 밖으로 보낸 망원경은 날씨에 상관없이 관찰한다.","다누리호는 달 주위를 돌며 달 표면을 탐사한다."],"title":"별빛반 일지 ⑧ 망원경과 탐사선"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_sci_u1_review_c#9','sci',4,2,'u1','','g4_2_sci_u1_review_c','unit_review','SC4-2-u1-C23',2,'ox','auto','「별은 스스로 빛을 낸다.」가 쓰인 풍선은 가져갈 수 있어요.',ARRAY['SC4-2-u1-X44']::text[],false,'{"seq":9,"concept":"SC4-2-u1-C23","difficulty":2,"kind":"ox","stem":"「별은 스스로 빛을 낸다.」가 쓰인 풍선은 가져갈 수 있어요.","answer":"O","reason_options":[{"t":"스스로 빛을 내는 천체를 별이라고 하기 때문에","correct":true},{"t":"별은 행성처럼 빛을 내지 않기 때문에","mis":"SC4-2-u1-X44"}],"mis":"SC4-2-u1-X44","explanation":["별의 뜻을 떠올려요.","옳은 문장이에요.","그래서 O예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_sci_u1_review_c#10','sci',4,2,'u1','','g4_2_sci_u1_review_c','unit_review','SC4-2-u1-C4',2,'ox','auto','달 모형을 옆에서 보았을 때 납작한 선으로 보이는 모형이 실제 달의 모양과 같아요.',ARRAY['SC4-2-u1-X07']::text[],false,'{"seq":10,"concept":"SC4-2-u1-C4","difficulty":2,"kind":"ox","stem":"달 모형을 옆에서 보았을 때 납작한 선으로 보이는 모형이 실제 달의 모양과 같아요.","answer":"X","reason_options":[{"t":"달은 둥근 공 모양이라 옆에서 보아도 둥근 원으로 보이기 때문에","correct":true},{"t":"앞에서 둥글게 보이면 납작해도 달과 같기 때문에","mis":"SC4-2-u1-X07"}],"mis":"SC4-2-u1-X07","explanation":["두 모형을 떠올려요.","달은 공 모양이에요.","그래서 X예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_sci_u1_review_c#11','sci',4,2,'u1','','g4_2_sci_u1_review_c','unit_review','SC4-2-u1-C11',2,'ox','auto','그믐달을 본 뒤에는 다시는 초승달을 볼 수 없어요.',ARRAY['SC4-2-u1-X22']::text[],false,'{"seq":11,"concept":"SC4-2-u1-C11","difficulty":2,"kind":"ox","stem":"그믐달을 본 뒤에는 다시는 초승달을 볼 수 없어요.","answer":"X","reason_options":[{"t":"그믐달을 본 뒤 며칠이 지나면 다시 초승달을 볼 수 있기 때문에","correct":true},{"t":"달은 모양이 한 번 달라지고 나면 사라지기 때문에","mis":"SC4-2-u1-X22"}],"mis":"SC4-2-u1-X22","explanation":["한 바퀴를 떠올려요.","다시 초승달이 와요.","그래서 X예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_sci_u1_review_c#12','sci',4,2,'u1','','g4_2_sci_u1_review_c','unit_review','SC4-2-u1-C12',2,'ox','auto','태양계는 태양의 영향을 받는 천체들뿐 아니라 그 공간까지 함께 가리키는 말이에요.',ARRAY['SC4-2-u1-X24']::text[],false,'{"seq":12,"concept":"SC4-2-u1-C12","difficulty":2,"kind":"ox","stem":"태양계는 태양의 영향을 받는 천체들뿐 아니라 그 공간까지 함께 가리키는 말이에요.","answer":"O","reason_options":[{"t":"태양계는 태양을 비롯한 천체들과 그 공간을 말하기 때문에","correct":true},{"t":"태양계에 공간은 들어가지 않기 때문에","mis":"SC4-2-u1-X24"}],"mis":"SC4-2-u1-X24","explanation":["뜻을 떠올려요.","공간도 들어가요.","그래서 O예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_sci_u1_review_c#13','sci',4,2,'u1','','g4_2_sci_u1_review_c','unit_review','SC4-2-u1-C15',2,'ox','auto','행성 모형은 행성 표면의 특징이 잘 드러나게 만들어요.',ARRAY['SC4-2-u1-X31']::text[],false,'{"seq":13,"concept":"SC4-2-u1-C15","difficulty":2,"kind":"ox","stem":"행성 모형은 행성 표면의 특징이 잘 드러나게 만들어요.","answer":"O","reason_options":[{"t":"모형으로 행성의 특징을 표현하고 친구들과 나누기 때문에","correct":true},{"t":"특징보다 예쁜 색이 더 중요하기 때문에","mis":"SC4-2-u1-X31"}],"mis":"SC4-2-u1-X31","explanation":["모형을 왜 만들까요?","특징을 표현해요.","그래서 O예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_sci_u1_review_c#14','sci',4,2,'u1','','g4_2_sci_u1_review_c','unit_review','SC4-2-u1-C16',2,'ox','auto','행성도 별처럼 스스로 빛을 내요.',ARRAY['SC4-2-u1-X32']::text[],false,'{"seq":14,"concept":"SC4-2-u1-C16","difficulty":2,"kind":"ox","stem":"행성도 별처럼 스스로 빛을 내요.","answer":"X","reason_options":[{"t":"행성은 별과 달리 스스로 빛을 내지 않기 때문에","correct":true},{"t":"밤하늘에서 반짝이는 것은 모두 스스로 빛을 내기 때문에","mis":"SC4-2-u1-X32"}],"mis":"SC4-2-u1-X32","explanation":["별의 뜻을 떠올려요.","행성은 달라요.","그래서 X예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_sci_u1_review_c#15','sci',4,2,'u1','','g4_2_sci_u1_review_c','unit_review','SC4-2-u1-C18',2,'ox','auto','북극성은 밤마다 자리가 크게 바뀌어서 방향을 찾는 데 쓸 수 없어요.',ARRAY['SC4-2-u1-X38']::text[],false,'{"seq":15,"concept":"SC4-2-u1-C18","difficulty":2,"kind":"ox","stem":"북극성은 밤마다 자리가 크게 바뀌어서 방향을 찾는 데 쓸 수 없어요.","answer":"X","reason_options":[{"t":"북극성은 정확한 북쪽 부근에서 위치가 거의 변하지 않기 때문에","correct":true},{"t":"북극성은 남쪽 하늘에 있기 때문에","mis":"SC4-2-u1-X38"}],"mis":"SC4-2-u1-X38","explanation":["북극성을 떠올려요.","거의 그대로예요.","그래서 X예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_sci_u1_review_c#16','sci',4,2,'u1','','g4_2_sci_u1_review_c','unit_review','SC4-2-u1-C26',2,'ox','auto','망원경으로 관찰하기도 하고 직접 천체에 가서 관찰하기도 해요.',ARRAY['SC4-2-u1-X47']::text[],false,'{"seq":16,"concept":"SC4-2-u1-C26","difficulty":2,"kind":"ox","stem":"망원경으로 관찰하기도 하고 직접 천체에 가서 관찰하기도 해요.","answer":"O","reason_options":[{"t":"망원경도 쓰고 다누리호 같은 탐사선을 보내 관찰하기도 하기 때문에","correct":true},{"t":"천체는 망원경으로만 관찰할 수 있기 때문에","mis":"SC4-2-u1-X47"}],"mis":"SC4-2-u1-X47","explanation":["다누리호를 떠올려요.","직접 가기도 해요.","그래서 O예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_sci_u1_review_c#17','sci',4,2,'u1','','g4_2_sci_u1_review_c','unit_review','SC4-2-u1-C5',3,'mc','auto','별빛반 일지 ②의 내용을 바탕으로 달 표면을 바르게 정리한 것은 무엇인가요?',ARRAY['SC4-2-u1-X11','SC4-2-u1-X09','SC4-2-u1-X10']::text[],false,'{"seq":17,"concept":"SC4-2-u1-C5","difficulty":3,"kind":"mc","stem":"별빛반 일지 ②의 내용을 바탕으로 달 표면을 바르게 정리한 것은 무엇인가요?","options":[{"t":"단단한 땅으로 되어 있고 울퉁불퉁하며 충돌 구덩이와 어두운 곳·밝은 곳이 있다","correct":true},{"t":"물로 되어 있고 매끈매끈하다","mis":"SC4-2-u1-X11"},{"t":"어디나 평평하고 밝은 곳만 있다","mis":"SC4-2-u1-X09"},{"t":"충돌 구덩이는 없고 달의 바다만 있다","mis":"SC4-2-u1-X10"}],"explanation":["둘째·셋째 줄을 읽어요.","울퉁불퉁해요.","첫 번째예요."],"asset":{"type":"passage","lines":["모양 — 앞에서 보아도 옆에서 보아도 둥근 모형이 달과 같았다.","표면 — 단단한 땅이고 울퉁불퉁하며 움푹 파인 곳이 많다.","어두운 곳 — 주변보다 어둡고 매끈매끈해 보인다.","조사 — 스마트 기기로 찾은 자료의 출처를 적었다."],"title":"별빛반 일지 ② 달 사진 관찰"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_sci_u1_review_c#18','sci',4,2,'u1','','g4_2_sci_u1_review_c','unit_review','SC4-2-u1-C8',3,'mc','auto','별빛반 일지 ③에서 잘한 점을 바르게 쓴 것은 무엇인가요?',ARRAY['SC4-2-u1-X16','SC4-2-u1-X15','SC4-2-u1-X14']::text[],false,'{"seq":18,"concept":"SC4-2-u1-C8","difficulty":3,"kind":"mc","stem":"별빛반 일지 ③에서 잘한 점을 바르게 쓴 것은 무엇인가요?","options":[{"t":"어른과 함께 탁 트인 곳에서 관찰했고, 달이 안 보이는 날에는 스마트 기기로 확인했다","correct":true},{"t":"혼자 새벽에 나가 관찰했다","mis":"SC4-2-u1-X16"},{"t":"흐린 날 달이 없어졌다고 적었다","mis":"SC4-2-u1-X15"},{"t":"하루만 보고 기록을 끝냈다","mis":"SC4-2-u1-X14"}],"explanation":["일지를 읽어요.","안전과 방법을 봐요.","첫 번째예요."],"asset":{"type":"passage","lines":["관찰 — 어른과 함께 저녁에 탁 트인 운동장에서 했다.","기록 — 눈썹 모양 → 반달 → 둥근 달 → 반달 → 눈썹 모양","흐린 날 — 달이 보이지 않아 스마트 기기로 확인했다.","첫날과 같은 모양의 달을 약 30일 뒤에 다시 보았다."],"title":"별빛반 일지 ③ 여러 날 달 관찰"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_sci_u1_review_c#19','sci',4,2,'u1','','g4_2_sci_u1_review_c','unit_review','SC4-2-u1-C12',3,'mc','auto','별빛반 일지 ④의 전시를 태양계에 맞게 보태려면 무엇을 더하면 좋을까요?',ARRAY['SC4-2-u1-X25','SC4-2-u1-X23']::text[],false,'{"seq":19,"concept":"SC4-2-u1-C12","difficulty":3,"kind":"mc","stem":"별빛반 일지 ④의 전시를 태양계에 맞게 보태려면 무엇을 더하면 좋을까요?","options":[{"t":"행성 말고도 태양계에 있는 여러 가지 천체와 그 공간이 있다는 설명","correct":true},{"t":"태양을 행성 줄에 끼워 넣기","mis":"SC4-2-u1-X25"},{"t":"행성만 있으니 아무것도 더하지 않기","mis":"SC4-2-u1-X23"},{"t":"지구를 가운데로 옮기기","mis":"SC4-2-u1-X25"}],"explanation":["태양계의 뜻을 떠올려요.","천체와 공간이에요.","첫 번째예요."],"asset":{"type":"passage","lines":["㉠ 붉은색, 표면에 단단한 땅","㉡ 연한 노란색, 크고 뚜렷한 고리","㉢ 갈색·흰색, 줄무늬와 붉은 점, 희미한 고리","㉣ 청록색, 표면이 기체, 희미한 고리","전시 — 태양 모형을 가운데에 두고 행성 모형을 놓았다."],"title":"별빛반 일지 ④ 행성 모형 전시"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_sci_u1_review_c#20','sci',4,2,'u1','','g4_2_sci_u1_review_c','unit_review','SC4-2-u1-C19',3,'mc','auto','별빛반 일지 ⑥에서 필름으로 세 별자리를 찾은 뒤 프로그램을 켠 것이 좋았던 까닭은 무엇인가요?',ARRAY['SC4-2-u1-X37','SC4-2-u1-X38','SC4-2-u1-X39']::text[],false,'{"seq":20,"concept":"SC4-2-u1-C19","difficulty":3,"kind":"mc","stem":"별빛반 일지 ⑥에서 필름으로 세 별자리를 찾은 뒤 프로그램을 켠 것이 좋았던 까닭은 무엇인가요?","options":[{"t":"필름으로 찾은 것 말고도 북극성 주변에 별자리가 더 있다는 것을 알 수 있었기 때문에","correct":true},{"t":"세 별자리가 전부라는 것을 확인했기 때문에","mis":"SC4-2-u1-X37"},{"t":"프로그램은 남쪽 하늘만 보여 주기 때문에","mis":"SC4-2-u1-X38"},{"t":"필름은 쓸 필요가 없었기 때문에","mis":"SC4-2-u1-X39"}],"explanation":["넷째 줄을 읽어요.","더 있었어요.","첫 번째예요."],"asset":{"type":"passage","lines":["필름으로 큰곰자리, 작은곰자리, 카시오페이아자리를 찾았다.","작은곰자리 꼬리 부분의 북극성은 위치가 거의 변하지 않았다.","큰곰자리 꼬리 부분에서 국자 모양의 일곱 별을 보았다.","프로그램을 켜니 북극성 주변에 별자리가 더 있었다."],"title":"별빛반 일지 ⑥ 북쪽 하늘 관찰"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_sci_u1_review_c#21','sci',4,2,'u1','','g4_2_sci_u1_review_c','unit_review','SC4-2-u1-C23',3,'mc','auto','풍선 놀이에서 「화성은 크고 뚜렷한 고리가 있다.」 풍선을 가져가지 않는 까닭은 무엇인가요?',ARRAY['SC4-2-u1-X27','SC4-2-u1-X28','SC4-2-u1-X26']::text[],false,'{"seq":21,"concept":"SC4-2-u1-C23","difficulty":3,"kind":"mc","stem":"풍선 놀이에서 「화성은 크고 뚜렷한 고리가 있다.」 풍선을 가져가지 않는 까닭은 무엇인가요?","options":[{"t":"크고 뚜렷한 고리가 있는 행성은 토성이기 때문에","correct":true},{"t":"화성에는 단단한 땅이 없기 때문에","mis":"SC4-2-u1-X27"},{"t":"고리가 있는 행성은 없기 때문에","mis":"SC4-2-u1-X28"},{"t":"화성은 행성이 아니기 때문에","mis":"SC4-2-u1-X26"}],"explanation":["고리를 떠올려요.","크고 뚜렷한 고리예요.","토성이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_sci_u1_review_c#22','sci',4,2,'u1','','g4_2_sci_u1_review_c','unit_review','SC4-2-u1-C25',3,'mc','auto','별빛반 일지 ⑧의 셋째 줄처럼 망원경을 지구 밖으로 보내는 까닭은 무엇인가요?',ARRAY['SC4-2-u1-X46','SC4-2-u1-X47']::text[],false,'{"seq":22,"concept":"SC4-2-u1-C25","difficulty":3,"kind":"mc","stem":"별빛반 일지 ⑧의 셋째 줄처럼 망원경을 지구 밖으로 보내는 까닭은 무엇인가요?","options":[{"t":"날씨에 상관없이 우주를 관찰하려고","correct":true},{"t":"맑은 날에만 관찰하려고","mis":"SC4-2-u1-X46"},{"t":"달 기지를 지으려고","mis":"SC4-2-u1-X47"},{"t":"밤하늘을 볼 필요를 없애려고","mis":"SC4-2-u1-X46"}],"explanation":["셋째 줄을 읽어요.","날씨예요.","첫 번째예요."],"asset":{"type":"passage","lines":["맨눈으로 보던 때에는 행성의 모습을 자세히 알기 어려웠다.","망원경으로 달의 울퉁불퉁한 표면을 알아냈다.","지구 밖으로 보낸 망원경은 날씨에 상관없이 관찰한다.","다누리호는 달 주위를 돌며 달 표면을 탐사한다."],"title":"별빛반 일지 ⑧ 망원경과 탐사선"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_sci_u1_review_c#23','sci',4,2,'u1','','g4_2_sci_u1_review_c','unit_review','SC4-2-u1-C10',4,'essay','teacher','별빛반 일지 ③을 보고 기록한 달의 모양에 이름을 붙여 차례대로 쓰고, 같은 모양의 달을 다시 보는 데 걸린 날과 관찰할 때 지킨 안전 수칙을 쓰세요.','{}'::text[],false,'{"seq":23,"concept":"SC4-2-u1-C10","difficulty":4,"kind":"essay","stem":"별빛반 일지 ③을 보고 기록한 달의 모양에 이름을 붙여 차례대로 쓰고, 같은 모양의 달을 다시 보는 데 걸린 날과 관찰할 때 지킨 안전 수칙을 쓰세요.","answer_guide":{"answer":"예: 초승달, 상현달, 보름달, 하현달, 그믐달 차례이다. 같은 모양의 달을 다시 보는 데 약 30일이 걸렸다. 어른과 함께 외출하여 저녁에 관찰했다.","scoring_points":["달의 이름을 차례대로 썼는가","약 30일을 썼는가","지킨 안전 수칙을 썼는가"]},"explanation":["기록 줄을 읽어요.","이름을 붙여요.","날과 안전을 써요."],"asset":{"type":"passage","lines":["관찰 — 어른과 함께 저녁에 탁 트인 운동장에서 했다.","기록 — 눈썹 모양 → 반달 → 둥근 달 → 반달 → 눈썹 모양","흐린 날 — 달이 보이지 않아 스마트 기기로 확인했다.","첫날과 같은 모양의 달을 약 30일 뒤에 다시 보았다."],"title":"별빛반 일지 ③ 여러 날 달 관찰"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_sci_u1_review_c#24','sci',4,2,'u1','','g4_2_sci_u1_review_c','unit_review','SC4-2-u1-C18',4,'mc','auto','밤에 산에서 방향을 잃었어요. 별빛반 일지 ⑥에서 배운 것으로 북쪽을 찾는 방법을 가장 알맞게 말한 것은 무엇인가요?',ARRAY['SC4-2-u1-X32','SC4-2-u1-X38','SC4-2-u1-X36']::text[],false,'{"seq":24,"concept":"SC4-2-u1-C18","difficulty":4,"kind":"mc","stem":"밤에 산에서 방향을 잃었어요. 별빛반 일지 ⑥에서 배운 것으로 북쪽을 찾는 방법을 가장 알맞게 말한 것은 무엇인가요?","options":[{"t":"「작은곰자리 꼬리 부분의 북극성을 찾으면 그쪽이 북쪽이야. 북극성은 위치가 거의 변하지 않아.」","correct":true},{"t":"「목성을 찾으면 그쪽이 북쪽이야.」","mis":"SC4-2-u1-X32"},{"t":"「북극성을 찾으면 그쪽이 남쪽이야.」","mis":"SC4-2-u1-X38"},{"t":"「북두칠성의 일곱 별 가운데 하나가 북극성이야.」","mis":"SC4-2-u1-X36"}],"explanation":["북극성을 떠올려요.","북쪽 부근에 있어요.","첫 번째예요."],"asset":{"type":"passage","lines":["필름으로 큰곰자리, 작은곰자리, 카시오페이아자리를 찾았다.","작은곰자리 꼬리 부분의 북극성은 위치가 거의 변하지 않았다.","큰곰자리 꼬리 부분에서 국자 모양의 일곱 별을 보았다.","프로그램을 켜니 북극성 주변에 별자리가 더 있었다."],"title":"별빛반 일지 ⑥ 북쪽 하늘 관찰"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_sci_u1_review_c#25','sci',4,2,'u1','','g4_2_sci_u1_review_c','unit_review','SC4-2-u1-C22',4,'essay','teacher','별빛반 일지 ⑦을 보고 이 모둠의 홍보 자료에서 잘한 점을 살펴보는 기준과 이어 쓰고, 친구 나의 말을 바르게 고쳐 쓰세요. 그리고 다른 모둠 발표를 들을 때 지킬 점을 쓰세요.','{}'::text[],false,'{"seq":25,"concept":"SC4-2-u1-C22","difficulty":4,"kind":"essay","stem":"별빛반 일지 ⑦을 보고 이 모둠의 홍보 자료에서 잘한 점을 살펴보는 기준과 이어 쓰고, 친구 나의 말을 바르게 고쳐 쓰세요. 그리고 다른 모둠 발표를 들을 때 지킬 점을 쓰세요.","answer_guide":{"answer":"예: 태양이 태양계 중심에 있다는 특징을 살려 홍보 내용을 정해 천체의 특징을 잘 나타냈다. 색만 더 칠한다고 좋은 자료가 되는 것이 아니라 천체의 특징이 잘 드러나야 한다. 다른 모둠이 발표할 때에는 경청하고 비난하지 않는다.","scoring_points":["잘한 점을 기준과 이어 썼는가","친구 나의 말을 바르게 고쳤는가","발표를 들을 때 지킬 점을 썼는가"]},"explanation":["일지를 읽어요.","기준을 떠올려요.","고쳐 써요."],"asset":{"type":"passage","lines":["홍보할 천체 — 태양","특징 — 태양계의 중심에 있다.","홍보 내용 — 태양에서 여러 행성을 바라보는 여행","친구 나 — 「색만 더 칠하면 최고의 자료가 될 거야.」"],"title":"별빛반 일지 ⑦ 태양계 여행 홍보 자료"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_sci_u1_review_d#1','sci',4,2,'u1','','g4_2_sci_u1_review_d','unit_review','SC4-2-u1-C3',1,'mc','auto','밤하늘 단어 놀이에서 지킬 태도는 무엇인가요?',ARRAY['SC4-2-u1-X06','SC4-2-u1-X04','SC4-2-u1-X05']::text[],false,'{"seq":1,"concept":"SC4-2-u1-C3","difficulty":1,"kind":"mc","stem":"밤하늘 단어 놀이에서 지킬 태도는 무엇인가요?","options":[{"t":"친구의 이야기를 존중한다","correct":true},{"t":"친구 말을 비난한다","mis":"SC4-2-u1-X06"},{"t":"단어를 많이 안다고 뽐낸다","mis":"SC4-2-u1-X04"},{"t":"뜻을 모르면 말하지 않는다","mis":"SC4-2-u1-X05"}],"explanation":["다짐을 떠올려요.","서로 존중해요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_sci_u1_review_d#2','sci',4,2,'u1','','g4_2_sci_u1_review_d','unit_review','SC4-2-u1-C5',1,'mc','auto','달 표면에서 움푹 파인 곳을 무엇이라고 하나요?',ARRAY['SC4-2-u1-X10']::text[],false,'{"seq":2,"concept":"SC4-2-u1-C5","difficulty":1,"kind":"mc","stem":"달 표면에서 움푹 파인 곳을 무엇이라고 하나요?","options":[{"t":"충돌 구덩이","correct":true},{"t":"달의 바다","mis":"SC4-2-u1-X10"},{"t":"단단한 땅","mis":"SC4-2-u1-X10"},{"t":"밝은 곳","mis":"SC4-2-u1-X10"}],"explanation":["움푹 파였어요.","크고 작은 구덩이예요.","충돌 구덩이예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_sci_u1_review_d#3','sci',4,2,'u1','','g4_2_sci_u1_review_d','unit_review','SC4-2-u1-C10',1,'mc','auto','보름달은 어떤 모양으로 보이나요?',ARRAY['SC4-2-u1-X18']::text[],false,'{"seq":3,"concept":"SC4-2-u1-C10","difficulty":1,"kind":"mc","stem":"보름달은 어떤 모양으로 보이나요?","options":[{"t":"둥근 모양","correct":true},{"t":"눈썹 모양","mis":"SC4-2-u1-X18"},{"t":"반달 모양","mis":"SC4-2-u1-X18"},{"t":"네모 모양","mis":"SC4-2-u1-X18"}],"explanation":["가운데 차례예요.","꽉 찼어요.","둥근 모양이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_sci_u1_review_d#4','sci',4,2,'u1','','g4_2_sci_u1_review_d','unit_review','SC4-2-u1-C13',1,'mc','auto','태양계의 행성은 모두 몇 개인가요?',ARRAY['SC4-2-u1-X26']::text[],false,'{"seq":4,"concept":"SC4-2-u1-C13","difficulty":1,"kind":"mc","stem":"태양계의 행성은 모두 몇 개인가요?","options":[{"t":"여덟 개","correct":true},{"t":"다섯 개","mis":"SC4-2-u1-X26"},{"t":"아홉 개","mis":"SC4-2-u1-X26"},{"t":"세 개","mis":"SC4-2-u1-X26"}],"explanation":["수성부터 세어요.","해왕성까지예요.","여덟 개예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_sci_u1_review_d#5','sci',4,2,'u1','','g4_2_sci_u1_review_d','unit_review','SC4-2-u1-C16',1,'mc','auto','북극성은 어떤 천체인가요?',ARRAY['SC4-2-u1-X32']::text[],false,'{"seq":5,"concept":"SC4-2-u1-C16","difficulty":1,"kind":"mc","stem":"북극성은 어떤 천체인가요?","options":[{"t":"스스로 빛을 내는 별","correct":true},{"t":"스스로 빛을 내지 않는 행성","mis":"SC4-2-u1-X32"},{"t":"태양 주위를 도는 행성","mis":"SC4-2-u1-X32"},{"t":"달","mis":"SC4-2-u1-X32"}],"explanation":["별의 뜻을 떠올려요.","스스로 빛을 내요.","별이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_sci_u1_review_d#6','sci',4,2,'u1','','g4_2_sci_u1_review_d','unit_review','SC4-2-u1-C19',1,'mc','auto','별빛반 일지 ⑥에서 밤하늘 그림에 대어 별자리를 찾은 도구는 무엇인가요?',ARRAY['SC4-2-u1-X39']::text[],false,'{"seq":6,"concept":"SC4-2-u1-C19","difficulty":1,"kind":"mc","stem":"별빛반 일지 ⑥에서 밤하늘 그림에 대어 별자리를 찾은 도구는 무엇인가요?","options":[{"t":"별자리 투명 필름","correct":true},{"t":"돋보기","mis":"SC4-2-u1-X39"},{"t":"붙임딱지","mis":"SC4-2-u1-X39"},{"t":"도화지","mis":"SC4-2-u1-X39"}],"explanation":["첫 줄을 읽어요.","대어 보았어요.","투명 필름이에요."],"asset":{"type":"passage","lines":["필름으로 큰곰자리, 작은곰자리, 카시오페이아자리를 찾았다.","작은곰자리 꼬리 부분의 북극성은 위치가 거의 변하지 않았다.","큰곰자리 꼬리 부분에서 국자 모양의 일곱 별을 보았다.","프로그램을 켜니 북극성 주변에 별자리가 더 있었다."],"title":"별빛반 일지 ⑥ 북쪽 하늘 관찰"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_sci_u1_review_d#7','sci',4,2,'u1','','g4_2_sci_u1_review_d','unit_review','SC4-2-u1-C20',1,'mc','auto','관광객이 우주선을 타고 우주에 다녀오는 것을 무엇이라고 하나요?',ARRAY['SC4-2-u1-X40']::text[],false,'{"seq":7,"concept":"SC4-2-u1-C20","difficulty":1,"kind":"mc","stem":"관광객이 우주선을 타고 우주에 다녀오는 것을 무엇이라고 하나요?","options":[{"t":"우주여행","correct":true},{"t":"바다 여행","mis":"SC4-2-u1-X40"},{"t":"기차 여행","mis":"SC4-2-u1-X40"},{"t":"우주여행이 아닌 일","mis":"SC4-2-u1-X40"}],"explanation":["우주에 다녀왔어요.","다른 천체가 아니어도 돼요.","우주여행이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_sci_u1_review_d#8','sci',4,2,'u1','','g4_2_sci_u1_review_d','unit_review','SC4-2-u1-C24',1,'mc','auto','망원경이 발명되면서 발견한 행성끼리 묶은 것은 무엇인가요?',ARRAY['SC4-2-u1-X45']::text[],false,'{"seq":8,"concept":"SC4-2-u1-C24","difficulty":1,"kind":"mc","stem":"망원경이 발명되면서 발견한 행성끼리 묶은 것은 무엇인가요?","options":[{"t":"천왕성, 해왕성","correct":true},{"t":"수성, 금성","mis":"SC4-2-u1-X45"},{"t":"지구, 화성","mis":"SC4-2-u1-X45"},{"t":"목성, 토성","mis":"SC4-2-u1-X45"}],"explanation":["맨눈으로 보기 어려웠어요.","가장 바깥쪽 두 행성이에요.","천왕성, 해왕성이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_sci_u1_review_d#9','sci',4,2,'u1','','g4_2_sci_u1_review_d','unit_review','SC4-2-u1-C23',2,'mc','auto','풍선 놀이에서 옳지 않은 문장은 무엇인가요?',ARRAY['SC4-2-u1-X44']::text[],false,'{"seq":9,"concept":"SC4-2-u1-C23","difficulty":2,"kind":"mc","stem":"풍선 놀이에서 옳지 않은 문장은 무엇인가요?","options":[{"t":"북두칠성은 작은곰자리의 꼬리 부분에 있다","correct":true},{"t":"태양은 태양계의 중심에 있다","mis":"SC4-2-u1-X44"},{"t":"북극성은 북쪽 하늘에서 볼 수 있다","mis":"SC4-2-u1-X44"},{"t":"달의 모양은 매일 조금씩 달라진다","mis":"SC4-2-u1-X44"}],"explanation":["하나씩 확인해요.","북두칠성의 자리를 떠올려요.","큰곰자리가 맞아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_sci_u1_review_d#10','sci',4,2,'u1','','g4_2_sci_u1_review_d','unit_review','SC4-2-u1-C7',2,'mc','auto','달을 조사한 정보 가운데 거짓 정보를 가려내는 방법으로 알맞은 것은 무엇인가요?',ARRAY['SC4-2-u1-X13']::text[],false,'{"seq":10,"concept":"SC4-2-u1-C7","difficulty":2,"kind":"mc","stem":"달을 조사한 정보 가운데 거짓 정보를 가려내는 방법으로 알맞은 것은 무엇인가요?","options":[{"t":"출처를 확인하고 다른 믿을 만한 자료와 견주어 본다","correct":true},{"t":"가장 먼저 나온 글을 믿는다","mis":"SC4-2-u1-X13"},{"t":"글이 길면 옳다고 여긴다","mis":"SC4-2-u1-X13"},{"t":"출처를 지우고 옮긴다","mis":"SC4-2-u1-X13"}],"explanation":["정보를 살펴요.","출처가 중요해요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
