INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_sci_u1_review_d#13','sci',4,2,'u1','','g4_2_sci_u1_review_d','unit_review','SC4-2-u1-C15',2,'mc','auto','행성 모형을 만들 때 하지 않아야 할 행동은 무엇인가요?',ARRAY['SC4-2-u1-X30','SC4-2-u1-X31']::text[],false,'{"seq":13,"concept":"SC4-2-u1-C15","difficulty":2,"kind":"mc","stem":"행성 모형을 만들 때 하지 않아야 할 행동은 무엇인가요?","options":[{"t":"그림 도구의 뾰족한 곳을 친구 쪽으로 향하게 한다","correct":true},{"t":"장난치지 않는다","mis":"SC4-2-u1-X30"},{"t":"뾰족한 곳에 찔리지 않게 조심한다","mis":"SC4-2-u1-X30"},{"t":"친구 모형의 잘한 점을 말한다","mis":"SC4-2-u1-X31"}],"explanation":["안전을 떠올려요.","뾰족한 곳은 위험해요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
