INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_sci_u1_review_d#15','sci',4,2,'u1','','g4_2_sci_u1_review_d','unit_review','SC4-2-u1-C18',2,'mc','auto','북쪽 하늘의 별자리에 대해 바르게 말한 것은 무엇인가요?',ARRAY['SC4-2-u1-X37','SC4-2-u1-X35']::text[],false,'{"seq":15,"concept":"SC4-2-u1-C18","difficulty":2,"kind":"mc","stem":"북쪽 하늘의 별자리에 대해 바르게 말한 것은 무엇인가요?","options":[{"t":"큰곰자리, 작은곰자리, 카시오페이아자리 말고도 여러 별자리가 있다","correct":true},{"t":"큰곰자리, 작은곰자리, 카시오페이아자리 세 개뿐이다","mis":"SC4-2-u1-X37"},{"t":"북두칠성이 북극성을 포함한다","mis":"SC4-2-u1-X35"},{"t":"북쪽 하늘에는 별자리가 없다","mis":"SC4-2-u1-X37"}],"explanation":["프로그램을 떠올려요.","더 있었어요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_sci_u1_review_d#16','sci',4,2,'u1','','g4_2_sci_u1_review_d','unit_review','SC4-2-u1-C25',2,'mc','auto','망원경이 주는 도움이 아닌 것은 무엇인가요?',ARRAY['SC4-2-u1-X46']::text[],false,'{"seq":16,"concept":"SC4-2-u1-C25","difficulty":2,"kind":"mc","stem":"망원경이 주는 도움이 아닌 것은 무엇인가요?","options":[{"t":"밤하늘을 관찰할 필요를 없애 준다","correct":true},{"t":"천체의 표면 상태를 연구하게 해 준다","mis":"SC4-2-u1-X46"},{"t":"태양계 밖 천체를 자세히 보게 해 준다","mis":"SC4-2-u1-X46"},{"t":"날씨에 상관없이 우주를 보게 해 준다","mis":"SC4-2-u1-X46"}],"explanation":["망원경은 관찰을 도와요.","관찰은 계속해요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_sci_u1_review_d#17','sci',4,2,'u1','','g4_2_sci_u1_review_d','unit_review','SC4-2-u1-C7',3,'mc','auto','별빛반 일지 ②에서 조사할 때 출처를 적은 까닭으로 알맞은 것은 무엇인가요?',ARRAY['SC4-2-u1-X13']::text[],false,'{"seq":17,"concept":"SC4-2-u1-C7","difficulty":3,"kind":"mc","stem":"별빛반 일지 ②에서 조사할 때 출처를 적은 까닭으로 알맞은 것은 무엇인가요?","options":[{"t":"어디서 찾은 정보인지 확인하고 옳은 정보와 거짓 정보를 구분하려고","correct":true},{"t":"글을 길게 보이려고","mis":"SC4-2-u1-X13"},{"t":"출처만 적으면 내용은 안 봐도 돼서","mis":"SC4-2-u1-X13"},{"t":"친구 자료를 베끼려고","mis":"SC4-2-u1-X13"}],"explanation":["넷째 줄을 읽어요.","정보를 확인해요.","첫 번째예요."],"asset":{"type":"passage","lines":["모양 — 앞에서 보아도 옆에서 보아도 둥근 모형이 달과 같았다.","표면 — 단단한 땅이고 울퉁불퉁하며 움푹 파인 곳이 많다.","어두운 곳 — 주변보다 어둡고 매끈매끈해 보인다.","조사 — 스마트 기기로 찾은 자료의 출처를 적었다."],"title":"별빛반 일지 ② 달 사진 관찰"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_sci_u1_review_d#18','sci',4,2,'u1','','g4_2_sci_u1_review_d','unit_review','SC4-2-u1-C11',3,'mc','auto','별빛반 일지 ③에서 약 30일 뒤에 첫날과 같은 달을 다시 본 것으로 알 수 있는 것은 무엇인가요?',ARRAY['SC4-2-u1-X22','SC4-2-u1-X19','SC4-2-u1-X20']::text[],false,'{"seq":18,"concept":"SC4-2-u1-C11","difficulty":3,"kind":"mc","stem":"별빛반 일지 ③에서 약 30일 뒤에 첫날과 같은 달을 다시 본 것으로 알 수 있는 것은 무엇인가요?","options":[{"t":"달의 모양은 차례로 달라지다가 되풀이된다","correct":true},{"t":"달의 모양은 한 번 바뀌면 다시 돌아오지 않는다","mis":"SC4-2-u1-X22"},{"t":"달은 하루 만에 모든 모양으로 바뀐다","mis":"SC4-2-u1-X19"},{"t":"같은 모양을 다시 보려면 약 15일이 걸린다","mis":"SC4-2-u1-X20"}],"explanation":["넷째 줄을 읽어요.","다시 같은 모양이에요.","첫 번째예요."],"asset":{"type":"passage","lines":["관찰 — 어른과 함께 저녁에 탁 트인 운동장에서 했다.","기록 — 눈썹 모양 → 반달 → 둥근 달 → 반달 → 눈썹 모양","흐린 날 — 달이 보이지 않아 스마트 기기로 확인했다.","첫날과 같은 모양의 달을 약 30일 뒤에 다시 보았다."],"title":"별빛반 일지 ③ 여러 날 달 관찰"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_sci_u1_review_d#19','sci',4,2,'u1','','g4_2_sci_u1_review_d','unit_review','SC4-2-u1-C15',3,'mc','auto','별빛반 일지 ④의 모형 가운데 ㉢을 더 잘 만들려면 어떻게 해야 할까요?',ARRAY['SC4-2-u1-X29','SC4-2-u1-X31','SC4-2-u1-X27']::text[],false,'{"seq":19,"concept":"SC4-2-u1-C15","difficulty":3,"kind":"mc","stem":"별빛반 일지 ④의 모형 가운데 ㉢을 더 잘 만들려면 어떻게 해야 할까요?","options":[{"t":"줄무늬와 붉은 점, 희미한 고리가 잘 드러나게 표현한다","correct":true},{"t":"고리를 크고 뚜렷하게 바꾼다","mis":"SC4-2-u1-X29"},{"t":"특징은 빼고 예쁜 무늬를 넣는다","mis":"SC4-2-u1-X31"},{"t":"표면에 단단한 땅을 만든다","mis":"SC4-2-u1-X27"}],"explanation":["㉢은 목성이에요.","특징을 살려요.","첫 번째예요."],"asset":{"type":"passage","lines":["㉠ 붉은색, 표면에 단단한 땅","㉡ 연한 노란색, 크고 뚜렷한 고리","㉢ 갈색·흰색, 줄무늬와 붉은 점, 희미한 고리","㉣ 청록색, 표면이 기체, 희미한 고리","전시 — 태양 모형을 가운데에 두고 행성 모형을 놓았다."],"title":"별빛반 일지 ④ 행성 모형 전시"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_sci_u1_review_d#20','sci',4,2,'u1','','g4_2_sci_u1_review_d','unit_review','SC4-2-u1-C17',3,'mc','auto','별빛반 일지 ⑤의 친구 가의 말을 바탕으로 별자리를 바르게 설명한 것은 무엇인가요?',ARRAY['SC4-2-u1-X34']::text[],false,'{"seq":20,"concept":"SC4-2-u1-C17","difficulty":3,"kind":"mc","stem":"별빛반 일지 ⑤의 친구 가의 말을 바탕으로 별자리를 바르게 설명한 것은 무엇인가요?","options":[{"t":"사람들이 별들을 연결해 이름을 붙인 것이고, 지금은 천문학자들이 공통으로 정한 것을 쓴다","correct":true},{"t":"하늘에 저절로 그려진 그림이다","mis":"SC4-2-u1-X34"},{"t":"행성을 연결한 것이다","mis":"SC4-2-u1-X34"},{"t":"옛날부터 한 번도 바뀐 적이 없다","mis":"SC4-2-u1-X34"}],"explanation":["넷째 줄을 읽어요.","옛날과 지금도 떠올려요.","첫 번째예요."],"asset":{"type":"passage","lines":["북극성 — 스스로 빛을 내는 별이다.","목성 — 별처럼 빛나 보이지만 스스로 빛을 내지 않는다.","태양 — 태양계의 하나뿐인 별이다.","친구 가 — 「별자리는 별들을 연결해 이름을 붙인 것이야.」"],"title":"별빛반 일지 ⑤ 별과 행성"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_sci_u1_review_d#21','sci',4,2,'u1','','g4_2_sci_u1_review_d','unit_review','SC4-2-u1-C20',3,'mc','auto','별빛반 일지 ⑦의 여행 홍보를 보고 「태양에 내리지 않으면 우주여행이 아니야.」라고 말한 친구에게 알맞은 말은 무엇인가요?',ARRAY['SC4-2-u1-X40']::text[],false,'{"seq":21,"concept":"SC4-2-u1-C20","difficulty":3,"kind":"mc","stem":"별빛반 일지 ⑦의 여행 홍보를 보고 「태양에 내리지 않으면 우주여행이 아니야.」라고 말한 친구에게 알맞은 말은 무엇인가요?","options":[{"t":"「우주선을 타고 우주에 갔다가 돌아오는 것도 우주여행이야.」","correct":true},{"t":"「맞아, 천체에 내려야만 해.」","mis":"SC4-2-u1-X40"},{"t":"「우주 비행사만 우주에 갈 수 있어.」","mis":"SC4-2-u1-X40"},{"t":"「우주여행은 지구 안 여행이야.」","mis":"SC4-2-u1-X40"}],"explanation":["우주여행의 뜻을 떠올려요.","다녀오는 것도 돼요.","첫 번째예요."],"asset":{"type":"passage","lines":["홍보할 천체 — 태양","특징 — 태양계의 중심에 있다.","홍보 내용 — 태양에서 여러 행성을 바라보는 여행","친구 나 — 「색만 더 칠하면 최고의 자료가 될 거야.」"],"title":"별빛반 일지 ⑦ 태양계 여행 홍보 자료"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_sci_u1_review_d#22','sci',4,2,'u1','','g4_2_sci_u1_review_d','unit_review','SC4-2-u1-C26',3,'mc','auto','별빛반 일지 ⑧에서 직접 천체에 가서 관찰하는 것은 무엇인가요?',ARRAY['SC4-2-u1-X47']::text[],false,'{"seq":22,"concept":"SC4-2-u1-C26","difficulty":3,"kind":"mc","stem":"별빛반 일지 ⑧에서 직접 천체에 가서 관찰하는 것은 무엇인가요?","options":[{"t":"다누리호","correct":true},{"t":"맨눈","mis":"SC4-2-u1-X47"},{"t":"지구 밖으로 보낸 망원경","mis":"SC4-2-u1-X47"},{"t":"지상 망원경","mis":"SC4-2-u1-X47"}],"explanation":["넷째 줄을 읽어요.","달 주위를 돌아요.","다누리호예요."],"asset":{"type":"passage","lines":["맨눈으로 보던 때에는 행성의 모습을 자세히 알기 어려웠다.","망원경으로 달의 울퉁불퉁한 표면을 알아냈다.","지구 밖으로 보낸 망원경은 날씨에 상관없이 관찰한다.","다누리호는 달 주위를 돌며 달 표면을 탐사한다."],"title":"별빛반 일지 ⑧ 망원경과 탐사선"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_sci_u1_review_d#23','sci',4,2,'u1','','g4_2_sci_u1_review_d','unit_review','SC4-2-u1-C14',4,'essay','teacher','별빛반 일지 ④를 보고 ㉠~㉣이 어느 행성인지 쓰고, 표면에 단단한 땅이 있는 행성과 표면이 기체로 이루어진 행성으로 나누어 쓰세요.','{}'::text[],false,'{"seq":23,"concept":"SC4-2-u1-C14","difficulty":4,"kind":"essay","stem":"별빛반 일지 ④를 보고 ㉠~㉣이 어느 행성인지 쓰고, 표면에 단단한 땅이 있는 행성과 표면이 기체로 이루어진 행성으로 나누어 쓰세요.","answer_guide":{"answer":"예: ㉠은 화성, ㉡은 토성, ㉢은 목성, ㉣은 천왕성이다. 표면에 단단한 땅이 있는 행성은 ㉠ 화성이고, 표면이 기체로 이루어진 행성은 ㉡ 토성, ㉢ 목성, ㉣ 천왕성이다.","scoring_points":["㉠~㉣의 행성 이름을 바르게 썼는가","단단한 땅이 있는 행성을 바르게 골랐는가","기체로 이루어진 행성을 바르게 골랐는가"]},"explanation":["특징을 읽어요.","이름을 붙여요.","나누어 써요."],"asset":{"type":"passage","lines":["㉠ 붉은색, 표면에 단단한 땅","㉡ 연한 노란색, 크고 뚜렷한 고리","㉢ 갈색·흰색, 줄무늬와 붉은 점, 희미한 고리","㉣ 청록색, 표면이 기체, 희미한 고리","전시 — 태양 모형을 가운데에 두고 행성 모형을 놓았다."],"title":"별빛반 일지 ④ 행성 모형 전시"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_sci_u1_review_d#24','sci',4,2,'u1','','g4_2_sci_u1_review_d','unit_review','SC4-2-u1-C23',4,'mc','auto','풍선 ③ 「같은 모양의 달을 보려면 약 15일이 걸린다.」와 ⑤ 「화성은 크고 뚜렷한 고리가 있다.」를 바르게 고친 것끼리 묶은 것은 무엇인가요?',ARRAY['SC4-2-u1-X20','SC4-2-u1-X29','SC4-2-u1-X22']::text[],false,'{"seq":24,"concept":"SC4-2-u1-C23","difficulty":4,"kind":"mc","stem":"풍선 ③ 「같은 모양의 달을 보려면 약 15일이 걸린다.」와 ⑤ 「화성은 크고 뚜렷한 고리가 있다.」를 바르게 고친 것끼리 묶은 것은 무엇인가요?","options":[{"t":"③ 약 30일이 걸린다 · ⑤ 토성은 크고 뚜렷한 고리가 있다","correct":true},{"t":"③ 약 7일이 걸린다 · ⑤ 토성은 크고 뚜렷한 고리가 있다","mis":"SC4-2-u1-X20"},{"t":"③ 약 30일이 걸린다 · ⑤ 화성은 희미한 고리가 있다","mis":"SC4-2-u1-X29"},{"t":"③ 다시 볼 수 없다 · ⑤ 고리가 있는 행성은 없다","mis":"SC4-2-u1-X22"}],"explanation":["두 풍선을 하나씩 고쳐요.","약 30일 · 토성이에요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_sci_u1_review_d#25','sci',4,2,'u1','','g4_2_sci_u1_review_d','unit_review','SC4-2-u1-C24',4,'essay','teacher','별빛반 일지 ⑧을 보고 망원경이 밤하늘 관찰을 어떻게 바꾸었는지 쓰고, 망원경으로 관찰하는 것과 직접 천체에 가서 관찰하는 것을 각각 예를 들어 쓰세요.','{}'::text[],false,'{"seq":25,"concept":"SC4-2-u1-C24","difficulty":4,"kind":"essay","stem":"별빛반 일지 ⑧을 보고 망원경이 밤하늘 관찰을 어떻게 바꾸었는지 쓰고, 망원경으로 관찰하는 것과 직접 천체에 가서 관찰하는 것을 각각 예를 들어 쓰세요.","answer_guide":{"answer":"예: 맨눈으로 보던 때에는 행성의 모습을 자세히 알기 어려웠지만 망원경으로 달의 울퉁불퉁한 표면을 알아냈다. 지구 밖으로 보낸 망원경은 날씨에 상관없이 우주를 관찰한다. 다누리호는 직접 달에 가서 달 주위를 돌며 달 표면을 탐사한다.","scoring_points":["망원경이 바꾼 점을 썼는가","망원경으로 관찰하는 예를 썼는가","직접 천체에 가서 관찰하는 예를 썼는가"]},"explanation":["일지를 읽어요.","견주어 써요.","예를 들어요."],"asset":{"type":"passage","lines":["맨눈으로 보던 때에는 행성의 모습을 자세히 알기 어려웠다.","망원경으로 달의 울퉁불퉁한 표면을 알아냈다.","지구 밖으로 보낸 망원경은 날씨에 상관없이 관찰한다.","다누리호는 달 주위를 돌며 달 표면을 탐사한다."],"title":"별빛반 일지 ⑧ 망원경과 탐사선"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
